// 故事详情数据
const storyDetails: Record<string, {
  background: string
  core: string
  principle: string
  thinking: string
}> = {
  'edge-001': {
    background: `
1933年，瑞士天文学家弗里茨·兹威基盯着后发座星系团的数据发呆。他算出了这个星系团的总质量，又测了其中星系的运动速度，然后发现了一件怪事：星系跑得太快了。按照可见物质提供的引力，这些星系早就该飞散——可它们好好的，待在星系团里没走。兹威基大胆推测：星系团里有大量看不见的物质，提供了额外的引力。他管这种东西叫"dunkle Materie"——暗物质。当时几乎没人拿他当回事。兹威基以脾气古怪著称，同事们觉得他不过是在空想。一个看不见摸不着的东西，凭什么相信它存在？但几十年后，越来越多的证据从不同方向涌来，暗物质从天文学家的"疯狂猜测"变成了物理学最严肃的未解之谜。今天我们知道，宇宙中85%的物质是暗物质，我们能看见的恒星、行星、星云，不过是冰山一角。那个被嘲笑的瑞士人，其实早就看到了水面下的大象。`,
    core: `
暗物质最铁的证据来自星系旋转曲线。想象一个旋转木马：越靠外的位置，转一圈走过的路程越长，需要的速度就越大——但前提是引力足够提供向心力。星系也一样，按理说离中心越远的恒星，受到的引力越弱，公转速度应该下降。1970年代，美国天文学家薇拉·鲁宾用当时最先进的望远镜测量了数十个旋涡星系的旋转曲线，结果令人震惊：外围恒星的速度几乎没有下降，几乎是平的。这意味着什么？要么牛顿的引力定律在大尺度上出了问题，要么星系外围有大量我们看不见的物质，提供了额外的引力拉住了那些恒星。鲁宾的数据如此干净、如此一致，"暗物质"从此不再是边缘假说。

\$\$\\frac{mv^2}{r} = \\frac{GMm}{r^2} \\implies v = \\sqrt{\\frac{GM}{r}}\$\$

按这个公式，速度v应该随距离r增大而减小——但观测到的是几乎恒定。要让v恒定，M必须随r增大——意味着越往星系外围，总质量越多，但我们什么也看不到。

第二个强有力的证据来自引力透镜。爱因斯坦广义相对论预言，大质量天体会弯曲周围时空，光线经过时会被偏折，就像透过一块弯曲的玻璃看东西。天文学家观测到一些星系团产生的引力透镜效应，偏折程度远超可见物质能解释的范围——只有加入暗物质，计算才和观测吻合。更震撼的是2004年的"子弹星系团"观测：两个星系团高速碰撞，可见物质（炽热气体）在碰撞中减速堆积在中间，而大部分质量——通过引力透镜测定——却毫无阻碍地穿了过去。暗物质不参与电磁相互作用，所以两个暗物质晕像幽灵一样互相穿过，而普通气体则撞在了一起。这几乎是对暗物质存在的"直接拍照"。

第三个证据来自宇宙微波背景辐射的精密测量。普朗克卫星的数据表明，宇宙中普通物质只占约5%，暗物质占约27%，其余68%是暗能量。暗物质塑造了宇宙的大尺度结构——在宇宙诞生后的最初几亿年里，暗物质的引力先聚集成了巨大的丝状骨架，普通物质才沿着这些骨架坍缩形成星系。没有暗物质的引力"种子"，星系根本来不及在137亿年内形成。计算机模拟的暗物质分布与实际观测到的星系分布高度吻合——这种"看不见的骨架"撑起了整个可见宇宙。`,
    principle: `
1. **旋转曲线与引力质量**：恒星绕星系中心的公转速度反映了它所受的引力，而引力由内部总质量决定。外围速度不降，说明内部有大量不可见质量。\$M(r) = \\frac{v^2 r}{G}\$——测出速度和距离，就能算出内部总质量，远超可见物质的估计。（高一下学期·万有引力）

2. **引力透镜**：光线经过大质量天体时偏折角 \$\\alpha \\approx \\frac{4GM}{c^2 b}\$，b是光线到天体中心的最近距离——质量越大，偏折越大。通过测量偏折程度可以"称量"天体的质量，包括暗物质。（选修·相对论简介）

3. **弱相互作用大质量粒子(WIMP)**：暗物质最热门的候选者。它不参与电磁力（所以不发光），不参与强力（所以不与原子核碰撞），只参与弱力和引力——几乎与普通物质"不接触"。质量可能在质子的10~1000倍之间，速度远小于光速，因此被称为"冷暗物质"。

4. **暗物质晕模型**：观测和模拟表明，每个星系都被一个巨大的球形暗物质晕包裹，暗物质晕的质量可达可见物质的5~10倍，延伸到星系可见边缘的数倍之外。正是这个看不见的"壳"提供了额外的引力，把高速旋转的恒星牢牢拽住。`,
    thinking: `
**为什么重要？**
暗物质是当代物理学最深的悖论之一：我们知道它占宇宙物质的85%，主导了星系的形成和宇宙的结构，却完全不知道它是什么。这就像你知道房间里有一头大象，能感受到它的重量、看到它留下的脚印，但就是看不见它。找到暗物质的真身，很可能是继相对论和量子力学之后的又一次物理学革命。

**现代应用**
暗物质探测推动了极端灵敏的探测技术发展。中国的"熊猫计划"（PandaX）在四川锦屏地下2400米的实验室中寻找暗物质粒子与氙原子碰撞的微弱信号。这些超低背景探测技术也被用于中微子物理和核安全监测。

**还有什么未解之谜？**
暗物质到底是什么？WIMP是最热门的候选人，但全球数十个实验搜索了二十多年，仍然一无所获。有人开始转向更轻的"轴子"假说，甚至有人认为根本不存在暗物质——也许只是我们的引力定律在大尺度上需要修改，这就是所谓的MOND（修改牛顿动力学）理论。但MOND难以解释子弹星系团的引力透镜观测。另外，暗物质和暗能量之间有没有深层联系？宇宙95%的组成对我们来说是"暗"的，这究竟是物理学的瓶颈，还是我们对"物质"这个概念本身的定义需要更新？`,
  },
  'edge-002': {
    background: `
1981年，理查德·费曼在麻省理工学院的一次会议上抛出了一个让所有人愣住的问题："自然界不是经典的，如果你想模拟自然，你最好用量子力学来做——而这该死的问题可没法用经典计算机高效解决。"他说的不是哲学，而是非常实在的计算瓶颈。模拟一个由50个量子粒子组成的系统，需要的经典计算量超过任何超级计算机的极限——因为量子系统的可能性是指数级增长的。费曼的提议是：既然量子系统这么难用经典计算机模拟，那为什么不直接用一套量子系统来模拟另一套量子系统？用"量子"算"量子"。这个想法在当时听起来像是天才的狂想，台下的物理学家们面面相觑——量子力学本就够难理解了，拿它来做计算？但三十多年后，量子计算机从理论模型变成了实验室里的真实机器。2019年，谷歌的量子处理器"悬铃木"用200秒完成了一个计算任务，而这个任务在当时的超级计算机上预计需要一万年。量子计算的时代，已经悄悄开始了。`,
    core: `
量子计算机凭什么能超越经典计算机？答案藏在量子力学的两个核心特性里：**叠加**和**纠缠**。经典计算机用比特（bit）存储信息，一个比特要么是0，要么是1。量子计算机用量子比特（qubit），一个qubit可以同时处于0和1的叠加态。听起来像文字游戏？想象一枚硬币：经典比特是硬币正面朝上或反面朝上，而qubit是硬币在旋转中——它同时具有正面和反面的可能性，直到你"看"它，它才坍缩到某一个确定状态。一个qubit同时包含2种可能性，两个qubit同时包含4种，三个8种……n个qubit同时包含 \$2^n\$ 种可能性。50个qubit就是超过一千万亿种可能性——经典计算机得一个一个试，量子计算机可以同时处理所有可能性。

\$\$|\\psi\\rangle = \\alpha|0\\rangle + \\beta|1\\rangle\$\$

这是单个qubit的叠加态，\$|0\\rangle\$ 和 \$|1\\rangle\$ 是基本态，\$\\alpha\$ 和 \$\\beta\$ 是概率振幅——振幅的平方 \$|\\alpha|^2\$ 和 \$|\\beta|^2\$ 分别代表测量得到0和1的概率。关键是：叠加态不是"要么0要么1我们不知道"，而是"真的同时是0和1"。

第二个关键特性是纠缠。两个纠缠的qubit之间存在一种神秘的关联：测量其中一个，另一个的状态瞬间确定，无论它们相隔多远。爱因斯坦管这叫"鬼魅般的超距作用"。在量子计算中，纠缠让多个qubit协同工作，而不是各自为政——正是这种协同，让量子计算机能在某些问题上实现指数级加速。但要注意：量子计算机不是万能加速器。它不能让所有程序跑得更快，而是针对特定类型的问题——大数分解、量子模拟、搜索问题——展现出碾压性优势。最著名的例子是Shor算法：它能将大数分解问题从指数复杂度降到多项式复杂度，这意味着现有的RSA加密在足够强大的量子计算机面前将不堪一击。还有Grover搜索算法，在无序数据库中搜索的效率是经典算法的平方根倍——虽然加速不如Shor算法惊人，但应用范围更广。

然而，量子计算机极其脆弱。qubit的叠加态很容易被外界干扰破坏——温度波动、电磁噪声、哪怕一个误入的光子都能让计算崩溃。这就是"退相干"问题。目前的超导量子计算机需要在接近绝对零度（约15毫开尔文）的环境中运行，比外太空还冷。如何在不破坏量子态的条件下操控qubit、纠正在计算中出现的错误——量子纠错——是目前最大的工程挑战。`,
    principle: `
1. **叠加态**：量子比特可同时处于多个状态，\$|\\psi\\rangle = \\alpha|0\\rangle + \\beta|1\\rangle\$，其中 \$|\\alpha|^2 + |\\beta|^2 = 1\$——概率振幅的平方和必须为1，因为测量结果必定是0或1，不可能什么都不是。（高二下学期·波粒二象性）

2. **量子纠缠**：两个粒子的状态不可独立描述，测量一个立刻影响另一个。\$\\frac{1}{\\sqrt{2}}(|00\\rangle + |11\\rangle)\$——两个qubit要么同时为0，要么同时为1，测量前谁也不知道，测量后必定一致。

3. **量子门操作**：经典计算机用逻辑门（与、或、非）处理比特，量子计算机用量子门操控qubit。Hadamard门将|0⟩变成叠加态，CNOT门创造纠缠——量子门是可逆的，不像经典逻辑门会丢失信息。

4. **退相干**：qubit与环境的相互作用导致叠加态衰减，从量子行为退化为经典行为。相干时间是量子计算的关键指标，目前超导qubit的相干时间在百微秒量级——听起来很短，但已经够执行几百次量子门操作了。`,
    thinking: `
**为什么重要？**
量子计算机不是"更快的电脑"，而是一种基于不同物理原理的全新计算范式。它重新定义了什么是"可计算"的——有些问题经典计算机算到宇宙末日也出不来，量子计算机可能几分钟搞定。这不仅改变了计算科学，更深刻地改变了我们对"信息"本质的理解。

**现代应用**
量子计算目前最有前景的应用方向包括：药物分子模拟（精确预测蛋白质折叠和新药分子结构）、金融风险建模（优化投资组合和风险评估）、以及密码学（量子安全通信）。中国的"九章"光量子计算机在特定任务上也实现了量子计算优越性。

**还有什么未解之谜？**
通用容错量子计算机何时能实现？目前最大的障碍是量子纠错——理论上需要约1000个物理qubit来编码1个逻辑qubit，而今天的量子处理器只有几百个物理qubit。从几百到百万级，工程上还有巨大的鸿沟。此外，"量子优越性"本身也有争议：谷歌的200秒实验被IBM质疑，认为用更聪明的经典算法只需几天而非万年。是否真的存在经典计算机无法有效模拟的量子优势？这场经典与量子之间的赛跑远未结束，也许答案会改写我们对计算本质的认知。`,
  },
  'edge-003': {
    background: `
太阳每秒释放的能量约为 \$3.8 \\times 10^{26}\$ 焦耳，相当于一秒内引爆910亿颗百万吨级核弹。这么恐怖的输出，太阳已经持续了46亿年，而且还能再烧50亿年。秘密不是什么神奇燃料——太阳的燃料就是最普通的氢。在1500万度的核心，氢原子核以极高的速度互相碰撞，聚变成氦，释放出巨大能量。这就是核聚变。人类从1950年代就开始梦想：能不能在地面上复制这个过程，造一个"人造太阳"？如果成功，一升海水提取的氘（聚变燃料）能释放相当于300升汽油的能量，而且几乎不产生放射性废物，燃料取之不尽。这个梦想已经追逐了70年，笑话是"聚变永远还有30年"。但现在，事情真的在起变化。`,
    core: `
核聚变的原理听起来简单：把两个轻原子核推到一起，让它们融合成更重的核，释放能量。但实际操作极其困难，因为原子核带正电，互相排斥——这就是库仑势垒。要把两个核推到足够近，让核力（短程强吸引力）战胜电磁斥力，需要极高的温度和压力。

\$\$E_{\\text{库仑}} = \\frac{kZe_1 \\cdot Ze_2}{r}\$\$

两个氘核之间的库仑势垒约40万电子伏特——在经典物理下，这是不可能跨越的墙。但量子力学给了一条暗道：**量子隧穿**。即使粒子能量低于势垒，也有一定概率"穿墙而过"。在太阳核心，虽然温度只有1500万度（对应的平均动能远低于势垒），但庞大的粒子数量意味着每秒仍有足够多的核通过隧穿实现聚变。

在地面上，我们没有太阳那样巨大的引力来压缩燃料，所以必须把温度提得更高——至少1亿度，是太阳核心的6倍以上。在这样的温度下，气体完全电离，变成由自由电子和裸核组成的**等离子体**——物质的第四态。问题来了：没有任何固体容器能承受1亿度的高温，所有材料都会瞬间气化。科学家们想出了两条路：**磁约束**和**惯性约束**。

磁约束的思路是用强大的磁场把等离子体"悬浮"在真空中，不让它碰到容器壁。最主流的设计是**托卡马克**——一个甜甜圈形状的真空室，外面缠绕超导线圈产生环向磁场，等离子体在磁场中沿磁力线旋转，被牢牢箍住。这就像用看不见的橡皮筋把1亿度的火球捆在半空中。目前世界上最大的托卡马克实验装置是欧洲的JET，2023年它实现了0.69兆焦的聚变能量输出，持续5秒——虽然是历史性突破，但能量产出仍小于输入。

惯性约束则是另一条路：用超强激光从四面八方同时轰击一个胡椒粒大小的氘氚燃料小球，在几十亿分之一秒内把小球压缩到铅密度的100倍，核心温度超过1亿度，聚变瞬间发生然后爆炸。美国国家点火装置（NIF）在2022年12月首次实现了聚变"净能量增益"——输出3.15兆焦，输入2.05兆焦，首次产出超过投入。虽然这个"增益"没有计算驱动激光消耗的总电能，但它证明了一点：聚变点火在物理上是可行的。

\$\$Q = \\frac{E_{\\text{聚变输出}}}{E_{\\text{加热输入}}}\$\$

当Q>1，意味着聚变放出的能量大于维持它所需的能量——这是"点火"的标志。Q>10才有商业价值。`,
    principle: `
1. **质能方程与聚变能**：聚变反应中，产物质量略小于反应物，差值以能量释放。\$E = \\Delta m \\cdot c^2\$——氘氚聚变中每千克燃料释放约 \$3.4 \\times 10^{14}\$ 焦耳，是铀裂变的4倍、化学燃烧的千万倍。（高二下学期·原子物理）

2. **库仑势垒与量子隧穿**：两个带正电的核互相排斥，经典条件下无法接近到核力作用范围。但量子隧穿让粒子有一定概率穿越势垒，隧穿概率随温度升高而急剧增加——温度越高，粒子速度越快，"穿墙"的可能性就越大。

3. **等离子体约束**：1亿度等离子体不能用容器盛装。磁约束靠洛伦兹力 \$F = qv \\times B\$ 让带电粒子绕磁力线螺旋运动；惯性约束靠惯性在极短时间内保持高密度——两种方法本质上是"时间换空间"的不同策略。

4. **氘氚聚变反应**：\$\\text{D} + \\text{T} \\rightarrow \\text{He-4} + n + 17.6 \\, \\text{MeV}\$——一个氘核和一个氚核聚变成一个氦-4核加一个中子，释放17.6 MeV能量。这是目前最容易实现的聚变反应，因为其截面（反应概率）最大。`,
    thinking: `
**为什么重要？**
核聚变被称为"能源的圣杯"——如果实现，它将提供近乎无限、清洁、安全的能源。一升海水中的氘通过聚变释放的能量相当于300升汽油，全球海水中的氘够人类用上百亿年。在气候变化和能源危机的双重压力下，聚变能可能是人类文明可持续发展的终极答案。

**现代应用**
目前聚变研究的最重大项目是ITER（国际热核实验反应堆），建在法国，由35个国家联合参与，中国承担了约9%的制造任务。ITER计划在2030年代实现Q≥10的聚变输出，为后续的示范电站DEMO铺路。中国的EAST（东方超环）托卡马克也屡创长脉冲运行记录。

**还有什么未解之谜？**
聚变商业化还面临大量未知：第一壁材料如何承受高通量中子辐照？超导磁体如何在强辐射环境下长期稳定运行？氚的自持增殖能否实现？聚变堆的经济性能否与裂变、太阳能竞争？甚至有物理学家怀疑，托卡马克路线本身可能不是最优解——恒星用的引力约束、仿星器等其他构型，也许会带来意想不到的突破。`,
  },
  'edge-004': {
    background: `
自古以来，人类观察宇宙只有一种方式：看。从肉眼到望远镜，从可见光到射电、红外、X射线，所有的天文观测本质上都是在接收电磁波——光。但宇宙中有些最剧烈的事件根本不发光，黑洞合并就是其中之一。1916年，爱因斯坦从广义相对论中预言了引力波的存在，但他本人对此半信半疑——他怀疑这样的信号太微弱，人类永远无法探测到。此后几十年，物理学界甚至争论过引力波是否真的存在，还是只是数学上的虚构。直到1950年代末，约瑟夫·韦伯用巨大的铝棒尝试探测引力波，虽未成功，却开启了实验探测的征程。2015年9月14日，漫长的等待终于结束。LIGO探测器的两条4公里长的激光臂同时产生了一个微弱的信号——一条仅持续0.2秒的波形。它不是光，不是无线电，而是时空本身的涟漪。13亿年前，两个黑洞在一个遥远星系中螺旋相撞，合并的瞬间释放出的能量，以引力波的形式向外传播，穿越了整个可观测宇宙，最终在地球上的两台探测器中留下了痕迹。这是人类第一次用"耳朵"而非"眼睛"感知宇宙。引力波天文学从此诞生。`,
    core: `
引力波是爱因斯坦广义相对论最惊人的预言之一。当大质量天体加速运动时，会像石头投入水中一样，在时空中激起涟漪，以光速向外传播。

\$\$h \\approx \\frac{4G}{c^4} \\cdot \\frac{\\ddot{Q}}{r}\$\$

h是应变（时空被拉伸的相对幅度），\$\\ddot{Q}\$是质量四极矩的二阶导数（描述质量分布变化的快慢），r是距离。这个公式告诉我们两件事：引力波极其微弱（因为 \$c^4\$ 在分母上，是个天文数字），而且只有质量分布剧烈变化的天体才能产生可探测的信号。

2015年LIGO探测到的第一个信号GW150914，来自两个分别为36和29倍太阳质量的黑洞合并。在合并前的最后0.2秒，两个黑洞以每秒数千公里的速度互相绕转，每秒绕转75圈——这个速度下，时空被搅得天翻地覆。合并释放的瞬间功率达到 \$3.6 \\times 10^{49}\$ 瓦，是整个可观测宇宙所有星光总和的50倍。但这么恐怖的能量，到达地球时引起的时空形变只有 \$10^{-21}\$——相当于把4公里长的激光臂拉伸了不到一个质子直径的千分之一。LIGO能探测到这个信号，工程学上的成就不亚于物理学。

2017年8月17日，引力波天文学迎来了真正的里程碑：LIGO和Virgo联合探测到了两颗中子星合并的引力波信号GW170817。仅仅1.7秒后，费米卫星在同一片天区探测到了伽马射线暴。全球70多台望远镜立即转向，在后续几周内追踪到了光学、红外、射电和X射线信号。这是人类第一次用引力波和电磁波同时观测同一个天体事件——**多信使天文学**从此诞生。更令人兴奋的是，光学光谱分析证实，中子星合并过程中合成了大量重元素，包括金和铂。你手上金戒指里的金子，很可能就是几十亿年前两颗中子星相撞的产物。

引力波天文学打开了宇宙的"声学频道"。黑洞是完全"黑暗"的——没有光，电磁波什么都看不到，但引力波能穿透一切。以前天文学家只能"看"黑洞对周围环境的影响，现在可以直接"听"黑洞本身在做什么。`,
    principle: `
1. **时空弯曲与引力波**：广义相对论中，质量弯曲时空，加速运动的质量产生时空涟漪。引力波是横波，有两个偏振态——"加"偏振沿对角线方向交替拉伸和压缩空间，"叉"偏振旋转45度做同样的事。就像一张橡皮膜上传播的褶皱，从不同方向推拉着你。（选修·相对论简介）

2. **应变与探测**：引力波的应变 \$h = \\frac{\\Delta L}{L}\$，即长度的相对变化。LIGO探测到的 \$h \\sim 10^{-21}\$ 意味着4公里臂长变化约 \$4 \\times 10^{-18}\$ 米——质子直径的千分之一。探测如此微小的变化，需要激光干涉仪的精度达到亚原子尺度。

3. **致密天体合并波形**：引力波信号呈"啁啾"（chirp）波形——频率和振幅随时间递增。两个天体越靠越近，绕转越快，辐射的引力波频率越高、振幅越大，直到合并的瞬间达到峰值，然后急剧衰减。从波形可以反推天体质量、距离和自旋——就像通过乐器的音色判断它的材质和形状。

4. **多信使天文学**：引力波和电磁波携带不同信息——引力波反映质量运动的动力学，电磁波反映物质的热和化学状态。两者结合才能拼出完整图景，就像听声音同时看画面，缺一个都只是半幅画。`,
    thinking: `
**为什么重要？**
引力波天文学不是望远镜的升级版，而是一种全新的感知方式。这就好比人类一直只用眼睛观察世界，突然长出了耳朵——整个宇宙的声景一下子打开了。黑洞合并、中子星碰撞、宇宙大爆炸的回响……这些电磁波"看"不到的事件，引力波都能"听"到。

**现代应用**
引力波探测推动了精密测量技术的极限。LIGO的激光稳频技术、隔振系统和量子噪声压缩技术，已经被应用于精密制造、地震监测和惯性导航。下一代引力波探测器（如空间引力波天文台LISA）计划在太空中构建数百万公里量级的干涉臂，将探测频段扩展到毫赫兹，捕捉超大质量黑洞合并的信号。

**还有什么未解之谜？**
引力波天文学才刚刚开始。我们还没探测到连续引力波（来自旋转中子星的持续信号）、也没探测到随机引力波背景（宇宙大爆炸的"余音"）。更根本的问题是：引力波是否会揭示广义相对论在极端条件下的失效？如果在黑洞合并的最后一刻，信号偏离了爱因斯坦的预言，那可能就是量子引力的线索——一个统一相对论和量子力学的信号。`,
  },
  'edge-005': {
    background: `
1869年，门捷列夫用元素周期表把63种化学元素排得整整齐齐，预言了未知元素的存在，化学从此有了"地图"。一百年后，粒子物理学家也画了一张类似的表——但上面排的不是元素，而是构成宇宙的最基本砖块。20世纪中叶，物理学家们面对的是一个混乱的"粒子动物园"：二战后加速器技术飞速发展，新粒子像开盲盒一样不断冒出来——π介子、K介子、Λ超子、Σ超子……到1960年代已经有上百种，质量、寿命、衰变方式各不相同，没人知道它们之间有什么规律。盖尔曼在1961年提出的"八重法"——一种按对称性对粒子分类的方案——才第一次在这片混乱中找到了秩序，就像门捷列夫的周期表预言了未知元素一样，八重法也预言了Ω⁻粒子的存在，随后被实验证实。但真正的理论突破还要再等十年。1970年代，电弱统一理论和量子色动力学的建立，最终把所有这些粒子纳入了同一个框架——标准模型。它用17种基本粒子和4种基本力，解释了除引力以外的所有已知物理现象。2012年7月4日，欧洲核子研究中心（CERN）宣布发现希格斯玻色子——标准模型预言的最后一块拼图。那一刻，半个世纪的探索终于闭环。但闭环不等于完美。标准模型自己知道，它缺了太多东西。`,
    core: `
标准模型的基本粒子分为两大阵营：**费米子**（组成物质的粒子）和**玻色子**（传递力的粒子）。

费米子有12个，分成三代，每代2个夸克和2个轻子。第一代组成日常物质：上夸克和下夸克构成质子和中子，电子绕核旋转，电子中微子在核反应中出没。第二代和第三代更重、更不稳定，只在宇宙射线和高能碰撞中短暂出现。为什么恰好有三代？标准模型没有解释——这就像问元素周期表为什么到铀就停了，答案在表之外。

玻色子是力的"信使"。电磁力由光子传递，强力由胶子传递，弱力由W和Z玻色子传递。三种力的传递机制统一在"规范场论"的框架下——就像三种不同颜色的丝线编成同一条辫子。

\$\$\\mathcal{L} = -\\frac{1}{4}F_{\\mu\\nu}F^{\\mu\\nu} + i\\bar{\\psi}\\gamma^\\mu D_\\mu\\psi + \\bar{\\psi}_i y_{ij}\\psi_j \\phi + |D_\\mu\\phi|^2 - V(\\phi)\$\$

这是标准模型拉格朗日量的简化形式——把所有粒子、所有力、所有相互作用写成一个数学式子。虽然看着吓人，但每一项都有明确物理含义：第一项描述规范场（力的载体），第二项描述费米子与规范场的耦合（力如何作用于物质），第三项描述希格斯场与费米子的耦合（质量从何而来），第四和第五项描述希格斯场自身的动力学。

最关键的发现是希格斯机制。1964年，希格斯等几位物理学家提出：宇宙中充满一种看不见的场——希格斯场，粒子通过与希格斯场的相互作用获得质量。光子不与希格斯场耦合，所以质量为零，以光速传播；W和Z玻色子与希格斯场耦合强烈，所以很重，弱力因此是短程力。2012年发现的希格斯玻色子就是希格斯场的量子激发——就像探测到水面的波纹，证明水的存在。

但标准模型有明显的"洞"。首先，它不包括引力——引力用广义相对论描述，和量子力学的框架根本不兼容。其次，它无法解释暗物质——标准模型的17种粒子，没有一个暗物质候选者（WIMP只是假说，不在模型内）。第三，中微子振荡实验证明中微子有质量，但标准模型最初设定中微子质量为零——这是模型本身的缺陷。第四，为什么有三代费米子？为什么粒子质量差异如此巨大（顶夸克质量是上夸克的75000倍）？这些"为什么"，标准模型统统回答不了。`,
    principle: `
1. **规范对称性**：标准模型建立在 SU(3)×SU(2)×U(1) 规范对称性之上——SU(3)对应强力，SU(2)×U(1)对应电弱统一力。对称性决定了力的形式和粒子的相互作用方式，就像晶体的对称性决定了它的形状。（高二下学期·电磁场+选修）

2. **自发对称性破缺**：希格斯场在高温下对称，低温下"选择"一个方向，打破对称。就像一支竖立的铅笔倒下时随机选了一个方向——对称性破缺赋予了W、Z玻色子和费米子质量。\$m_W = \\frac{1}{2}gv\$，其中v是希格斯场的真空期望值，约246 GeV——这个数字决定了弱力的力程和粒子的质量尺度。

3. **夸克禁闭**：夸克永远无法被单独观察到——强力随距离增大而增强，试图拉出单个夸克时，能量大到足以产生新的夸克对。所以自然界中夸克总是成对（介子）或三胞胎（重子）出现。（高二下学期·原子物理）

4. **电弱统一**：电磁力和弱力在低能下表现截然不同，但在高能（>100 GeV）下统一为一种力——电弱力。这就像冰和水在低温下是不同形态，但在高温下都是蒸汽。温伯格、萨拉姆和格拉肖因此获1979年诺贝尔奖。`,
    thinking: `
**为什么重要？**
标准模型是人类理解微观世界的巅峰之作。它预言的粒子一个接一个被实验找到——从W/Z玻色子（1983）到顶夸克（1995）到希格斯玻色子（2012），没有一个落空。在适用范围内，它的精度高达小数点后十位以上，是物理学史上最精确的理论。但同时，它也是最令物理学家不安的理论——因为它明确知道自己是不完整的。

**现代应用**
标准模型的衍生技术已经深入日常生活。CERN发明的万维网（WWW）最初是为了让全球物理学家共享数据；加速器技术催生了医用质子治疗；探测器技术推动了医学影像和材料分析。粒子物理看似遥远，但它的"副产品"改变了每个人的生活。

**还有什么未解之谜？**
标准模型最大的遗憾是引力缺位。如何将引力纳入量子框架——构建量子引力理论——是21世纪物理学的最大挑战。弦理论、圈量子引力、渐近安全引力……候选方案很多，但没有一个获得实验支持。此外，为什么宇宙中物质远多于反物质（物质-反物质不对称）？希格斯玻色子的质量为什么恰好是125 GeV（比理论预期小很多，这叫"层级问题"）？每一个"为什么"的背后，都可能藏着超越标准模型的新物理学——也许就在下一个对撞机的发现中。`,
  },
  'fun-001': {
    background: `
你有没有玩过走马灯？一个圆筒形的灯罩，上面画着骑马的小人，蜡烛一点，灯罩转起来，那些小人就像真的在奔跑一样。

这个玩具在中国宋朝就有了，那时候叫"马骑灯"。古人觉得神奇——明明只是一圈静止的画，怎么转起来就活了？

答案藏在你自己的眼睛里。

19世纪初，欧洲人也开始琢磨这件事。一个叫彼得·罗热的英国医生在1824年写了一篇论文，指出人眼有一个奇怪的特性：一个画面消失后，它的影像会在视网膜上短暂停留大约0.1秒。也就是说，**你的眼睛比现实慢半拍**。

这个发现直接引爆了一连串发明：留影盘、走马盘、幻透镜……人们争先恐后地用这个原理造出各种"让画动起来"的装置。几十年后，这些玩具演变成了一个改变世界的东西——电影。`,
    core: `
视觉暂留的原理并不复杂：

当光线进入你的眼睛，打在视网膜上，感光细胞会产生电信号传给大脑。但感光细胞有个"反应延迟"——光消失了，信号不会立刻停止，而是会残留约0.05~0.2秒。

这意味着：如果你快速切换两幅画面，而且间隔小于0.1秒，你的大脑就来不及发现"中间断了一下"，它会自动把两幅画面"连"起来，觉得动作是流畅的。

走马灯正是利用了这一点：灯罩转得够快，画与画之间的间隙被视觉暂留填满，静止的骑马图就成了连续的奔跑。

后来人们把这个原理用到极致：

- **1891年**，爱迪生发明了活动电影放映机，每秒播放46帧画面
- **1895年**，卢米埃尔兄弟的《火车进站》让观众吓得躲闪
- **今天的电影**标准是每秒24帧，电视是25或30帧——都比视觉暂留的时间短得多

所以每一次你在电影院吃爆米花看大片，本质上和宋朝小孩盯着走马灯发呆，是同一回事。`,
    principle: `
**1. 视觉暂留（Persistence of Vision）**
光刺激消失后，视网膜上的影像残留约0.05~0.2秒。这是感光细胞的生理特性，不是物理定律，但在光学和显示技术中至关重要。

**2. 闪烁融合频率（Critical Flicker Fusion）**
当画面切换频率超过约16~24次/秒时，人眼就无法分辨单帧，感觉是连续的。这个频率就是闪烁融合频率，对应**高中物理·光学与波动**中人眼对光的响应特性。`,
    thinking: `
**为什么重要？**
视觉暂留是整个影视工业的生理基础。没有它，电影、电视、动画都不可能存在。更深层地说，它提醒我们——**你看到的"现实"，其实是大脑加工后的产品**，眼见不一定为实。

**现代应用**
今天所有的屏幕——手机、电脑、VR头显——都在利用视觉暂留。VR设备特别讲究刷新率，至少90Hz（每秒90帧），因为离眼睛太近，稍微卡顿就会让人眩晕。未来如果要实现"全息投影"，也绕不开对人眼视觉机制的深入理解。

**还有什么未解之谜？**
视觉暂留能解释为什么画面看起来连续，但它不能完全解释为什么我们会"看到运动"。大脑是怎么把一系列静止图像"脑补"成流畅动作的？这个"运动感知"的神经机制，至今仍是脑科学的前沿课题。`,
  },
  'fun-002': {
    background: `
雨后的天空，一道彩虹横跨天际。你可能从小就被告知"彩虹有七种颜色"，但你有没有想过另一个问题：**为什么彩虹是弯的？**

这个问题困扰了人类很久。亚里士多德认为彩虹是云的反射，古中国有"虹是龙吸水"的传说。直到13世纪，一位叫迪特里希的修道士第一次正确地指出：彩虹是阳光在水滴中折射后形成的。但为什么是弧形？这个答案要等到笛卡尔——对，就是那个说"我思故我在"的人——来给出。

1637年，笛卡尔用数学算出了光线在水滴中的完整路径，画出了精确的彩虹图。他的计算完美解释了彩虹的位置和形状，却始终没能解释彩虹的颜色——那要再等70年，等牛顿用三棱镜把白光拆开。`,
    core: `
彩虹的形成分三步走，每一步都是光在跟水滴"玩游戏"：

**第一步：折射进入**
阳光射入一颗球形水滴时，在表面发生折射。不同颜色的光折射角度不同——紫光偏折大，红光偏折小，白光就此开始"散伙"。

**第二步：内部反射**
光线进入水滴后，继续前进，打在水滴背面，发生一次全反射，调头往回走。

**第三步：折射射出**
反射后的光再次到达水滴表面，折射出来。此时不同颜色的光已经分道扬镳，各自朝不同方向射出。

关键来了：对于每一种颜色的光，水滴只在一个特定的角度把光集中射出。红光的这个角度大约是42°，紫光大约是40°。其他角度的光也有，但非常分散，几乎看不到。

**那弧形怎么来的？**

想象你背对太阳站着，眼前是一片雨幕。以你的眼睛为顶点，以太阳光线方向为轴，画一个42°的圆锥面——所有能向你射出红光的水滴，都分布在这个锥面上。圆锥面和雨幕相交，就是一段圆弧。紫光在40°的锥面上，所以紫光的弧比红光略小，紧挨在红光内侧。

这就是彩虹的形状——**它不是天上的弧，而是你眼睛画出的锥**。换个角度，就是换一道彩虹。`,
    principle: `
**1. 光的折射与色散**
白光由不同波长的光混合而成，进入水滴时因折射率不同而分开，紫光折射率大偏折多，红光折射率小偏折少。这是**高中物理·光学**中折射定律和色散现象的核心内容。

**2. 几何光学中的最小偏向角**
笛卡尔发现，光线在水滴中经过"折射—反射—折射"后，在约42°附近存在最小偏向角，这个角度附近的光线最密集、最亮，形成彩虹的主虹。这个现象可以用斯涅尔定律精确计算。`,
    thinking: `
**为什么重要？**
彩虹是人类最早观察到的光学现象之一，对彩虹的研究推动了折射定律的发现和光的波动说的建立。从一道彩虹出发，人类逐渐理解了光的本质。

**现代应用**
光的折射和色散原理广泛应用于光谱仪、光纤通信和相机镜头设计。每一次用手机拍下彩虹，镜头都在重复水滴做的事——把不同颜色的光分开又合拢。

**还有什么未解之谜？**
偶尔天上会出现"双彩虹"——外圈是颜色顺序反转的副虹。那是因为光线在水滴内反射了两次。但更罕见的是"火焰虹"（环天顶弧），它的形状和成因与普通彩虹完全不同，需要的条件极为苛刻，至今观测记录稀少。`,
  },
  'fun-003': {
    background: `
2019年1月，美国中西部遭遇极寒天气，气温降到-30°C以下。社交媒体上疯传一段视频：有人把一瓶瓶装水拿到室外，水是液态的——但轻轻一拍瓶身，整瓶水在几秒内从清澈变成乳白，瞬间冻成冰。

评论区炸了："水不是0°C就结冰吗？这怎么做到的？"

其实这不是什么特效，而是一个被物理学家研究了两百多年的现象——**过冷**（Supercooling）。水可以冷静到远低于0°C而不结冰，但只要你给它一个"借口"，它就会在一瞬间崩溃般地凝固。

这个"借口"叫作凝结核，通常是微小的杂质颗粒或容器壁上的粗糙点。没有它，水就像一个站在悬崖边犹豫的人——只要没人推一把，就能一直站在那里。`,
    core: `
要理解过冷，先要搞清楚水为什么会结冰。

0°C是水的凝固点，这只是热力学上的"平衡温度"——在这个温度下，冰和水可以和平共处。但"可以结冰"和"真的结冰"是两回事。结冰需要水分子排列成规则的晶体结构，而要启动这个排列，必须有一个"模板"——就是凝结核。

想象一屋子的人被要求站成整齐的方阵。如果没有人带头站到第一个位置，大家就会面面相觑，一直拖着。凝结核就是那个第一个站出来的人。一旦有了它，周围的水分子迅速模仿排列，晶体像多米诺骨牌一样蔓延开来。

在纯净的水中，几乎没有凝结核。实验表明，纯水可以冷却到约-40°C才自发结冰——这个温度叫**均匀成核温度**。在此之前，水处于过冷态：温度已经低于凝固点，但仍然是液态，像一颗随时可能引爆的炸弹。

过冷态极不稳定。任何扰动——敲击瓶身、放入一粒冰晶、甚至声音的震动——都可能提供凝结核，触发瞬间凝固。这就是视频中那一拍的效果：整瓶水在1~2秒内全部结晶，释放出大量的凝固潜热。

过冷现象不仅限于水。金属熔体可以过冷到远低于熔点而不凝固，云层中的过冷水滴在-10°C甚至-30°C的高空仍然保持液态——直到遇到飞机表面，瞬间结冰，这就是飞机积冰的危险来源。`,
    principle: `
**1. 凝固点与过冷**
凝固点是固液平衡温度，但实际结晶需要克服一个能量壁垒——成核能。没有凝结核时，水必须靠热涨落自发形成晶核，这只有在极低温度（约-40°C）下才容易发生。这是**高中物理·热学**中物态变化概念的延伸。

**2. 成核理论**
结晶分为两步：成核（形成微小晶核）和生长（晶核扩展）。成核是瓶颈步骤，需要能量起伏来"越过山丘"。异质成核（在杂质表面成核）需要的能量远低于均匀成核，所以一粒灰尘就能打破过冷态。

**3. 凝固潜热**
水结冰时每克释放约334焦耳热量，这就是过冷水瞬间凝固时温度会短暂回升的原因——大量潜热在短时间内释放，冰水混合物的温度会回到0°C并维持到全部凝固。`,
    thinking: `
**为什么重要？**
过冷现象揭示了相变的一个深刻事实：**热力学告诉你会发生什么，动力学告诉你什么时候发生**。0°C以下结冰是"应该的"，但如果没有触发条件，"应该"可以无限延迟。这个思路适用于从材料科学到宇宙学的众多领域。

**现代应用**
食品工业利用过冷原理实现"瞬间冷冻"，让冰晶细小均匀，保持食物口感。气象学中，人工降雨就是向过冷云层撒碘化银颗粒充当凝结核，促使水滴凝结降落。而在钢铁冶炼中，控制过冷度可以调节金属的晶粒大小，直接影响材料强度。

**还有什么未解之谜？**
过冷水在-45°C以下的微观结构至今有争议：有学者认为过冷水在这个区间存在两种不同的液态结构，可能在极低温度下存在一个"第二临界点"。如果这是真的，水的相图比我们想象的要复杂得多——而水，这个我们最熟悉的物质，可能还藏着最不熟悉的秘密。`,
  },
  'fun-004': {
    background: `
1963年，坦桑尼亚的一位中学生埃拉斯托·姆佩巴在学校做冰淇淋。他急着把热牛奶放进冰箱，老师提醒他"要等凉了再放"，他没听——结果那杯热牛奶竟然比同学的冷牛奶先冻上了。

老师不信，觉得他搞错了。但姆佩巴坚持自己的观察，后来还找达累斯萨拉姆大学的物理教授奥斯本做了实验。1969年，两人的论文发表，这个反常现象正式进入科学文献，被命名为**姆佩巴效应**。

然而故事其实更早。亚里士多德在公元前4世纪就记载过"加热过的水更快冷却"，弗兰西斯·培根和笛卡尔也提到过类似观察。但几千年来没人认真研究过——毕竟，谁会觉得热水比冷水先结冰呢？`,
    core: `
姆佩巴效应到底是怎么回事？半个多世纪过去了，物理学家至今没有完全统一的解释。但几个主要机制已经浮出水面：

**1. 蒸发效应**
热水表面蒸发更快，水分减少意味着剩余水量变少，当然更快结冰。而且蒸发还会带走大量热量，加速降温。这个因素最直观，但实验表明，即使控制蒸发量，效应仍然存在——蒸发不是全部答案。

**2. 对流效应**
热水冷却时，容器壁附近的水先变冷、密度变大、向下沉，中心的热水向上涌，形成强烈的对流。这种对流搅动让热量散失更快。而冷水温差小，对流弱，降温反而更"懒惰"。想象一锅热汤比一杯温水凉得快——搅动是关键。

**3. 溶解气体的影响**
冷水能溶解更多气体，而加热过程会把溶解的气体赶跑。少气泡的水和充满气泡的水，热传导性能不同，可能影响结冰速度。

**4. 过冷差异**
前面讲过，纯水可以过冷到-40°C不结冰。热水经过加热后，溶解气体减少，凝结核也变了——这可能导致热水在接近0°C时更容易触发结晶，而不需要经历那么深的过冷。换句话说，热水走的是"正常结冰"路线，冷水可能在过冷态里磨蹭。

2012年，新加坡研究团队提出了一个新解释：热水中的氢键被拉伸，冷却时氢键收缩释放能量，加速降温。但这个理论仍有争议。

2020年，一项严密的实验终于确认：**姆佩巴效应是真实存在的**，但它的出现取决于具体条件——容器形状、水量、冷却方式都会影响结果。它不是一个普适定律，而是一个"在特定条件下成立的反常现象"。`,
    principle: `
**1. 牛顿冷却定律**
物体冷却速率与物体和环境的温差成正比：

\$\$\\frac{dT}{dt} = -k(T - T_{\\text{env}})\$\$

热水初始温差大，降温速率快——但这只解释了"热水降温快"，不能直接推出"热水先到0°C"，因为冷水有"起跑优势"。姆佩巴效应之所以反直觉，正是因为简单冷却定律不足以解释它。

**2. 非平衡热力学**
姆佩巴效应的本质是一个**非平衡过程**：热水和冷水经历的不是同一条降温路径，它们的状态（对流模式、溶解气体、气泡分布）截然不同。这是**高中物理·热学**中热平衡与物态变化知识的延伸。`,
    thinking: `
**为什么重要？**
姆佩巴效应提醒我们：**直觉在科学面前不可靠**。一个看似荒唐的观察，可能隐藏着深层物理机制。而且它揭示了非平衡过程的复杂性——系统从不同初态出发，可能走完全不同的路径，不遵循简单的线性逻辑。

**现代应用**
理解姆佩巴效应对冷冻工程有实际意义——在食品速冻、生物样本保存中，初始温度的选择可能显著影响冻结速度和质量。如果热样品反而冻得快，很多"先冷却再冷冻"的工艺流程可能需要重新审视。

**还有什么未解之谜？**
姆佩巴效应是否有一个统一的、适用于所有条件的解释？目前没人敢说有。甚至它的逆效应——"冷水比热水先沸腾"——也有人在研究。非平衡热力学中，初态如何影响终态到达时间，至今是一个开放性问题，可能在更复杂的系统中（如化学反应、磁畴翻转）也存在类似现象。`,
  },
  'fun-005': {
    background: `
吃披萨的时候，最让人兴奋的瞬间是什么？不是咬下去的第一口，而是拿起一块时，芝士从饼上拉出一条长长的丝——两块披萨之间，一根金色的丝线悬在空中，越拉越长，最后才恋恋不舍地断开。

你有没有想过：为什么芝士能拉丝，而加热后的黄油不能？豆腐不能？巧克力也不能？

答案藏在分子层面。芝士的主要成分是酪蛋白——一种长链蛋白质分子。室温下，这些分子像一团纠缠的毛线，彼此之间靠分子间作用力牵扯着。温度升高，它们开始松动，但不会完全散开，而是像手拉手的人群一样，保持着一种"黏连而可滑移"的状态。这就是拉丝的秘密。`,
    core: `
要理解芝士拉丝，关键在于理解**分子间力与温度的关系**。

酪蛋白分子是一条条长链，链上有很多可以互相吸引的位点。在固态时，这些吸引力很强，分子们牢牢抱在一起，整个芝士是硬的。加热后，分子获得热能，开始振动和滑移，吸引力减弱但并没有消失——它们从"死死抱住"变成了"松松拉着"。

这时候你往外拉，分子链会沿着力的方向滑动，一条链脱开了这条邻居的手，又搭上了那条邻居的手。就像一群人手拉手：你从一端拽，前面的人跟着走，但手不会马上松开，而是逐个滑动，整队人被拉成一条长线。

但温度不能太高。如果过热，分子间力彻底崩溃，链与链之间完全脱钩——芝士就变成了一滩液态油脂，再也拉不出丝。所以完美的拉丝需要一个"窗口"：热到分子能滑移，但没热到彼此脱钩，大约在60~80°C之间。

不同芝士的拉丝能力天差地别。莫扎瑞拉（Mozzarella）是拉丝之王，因为它的酪蛋白含量高、脂肪比例适中、酸度低。切达（Cheddar）就差得多，因为它在制作过程中酸度较高，蛋白质结构已经被部分破坏。`,
    principle: `
**1. 分子间作用力**
分子之间存在引力（范德华力、氢键等），距离近时吸引，太近时排斥。温度升高，分子热运动加剧，平均间距增大，引力减弱。这是**高中化学和物理**中分子动理论的基础内容。

**2. 高分子链的黏弹性**
长链蛋白质同时具有黏性（可流动）和弹性（可回缩），这种"黏弹性"让芝士既能拉长又不断裂。衡量材料"难不难拉长"的物理量叫弹性模量：

\$\$E = \\frac{\\sigma}{\\varepsilon}\$\$

其中 \$\\sigma\$ 是应力（单位面积上的拉力），\$\\varepsilon\$ 是应变（相对伸长量）——简单说就是"拉多长需要多大力"。弹性模量越大，材料越难变形。莫扎瑞拉的弹性模量适中，所以拉丝效果好；完全液态的材料弹性模量趋近于零，拉不出丝。`,
    thinking: `
**为什么重要？**
芝士拉丝看似是餐桌小事，但它背后的"黏弹性"概念是材料科学的基石。塑料、橡胶、甚至人体组织都表现出类似行为——既不像液体那样完全流动，也不像固体那样完全刚性。理解了黏弹性，你就理解了为什么橡皮筋能拉伸又能回弹，为什么沥青路面夏天会变软，为什么你的耳垂能被拉长但松手后又恢复原状。

**现代应用**
工业上利用高分子黏弹性制造各种材料：防弹衣用的凯夫拉纤维、汽车轮胎的橡胶、3D打印的耗材，本质上都在操控分子链的"拉丝"行为。食品工业更是如此——芝士的配方设计，就是在调控蛋白质分子间力与温度的关系。

**还有什么未解之谜？**
为什么同样是蛋白质，有的加热后拉丝，有的却变成一锅糊？蛋白质变性的细节机制——从折叠结构到链间交联如何随温度演化——至今仍是生物物理学的前沿课题。每一块芝士的分子故事，可能都比我们想象的更复杂。`,
  },
  'fun-006': {
    background: `
每个孩子都会问这个问题："妈妈，天为什么是蓝色的？"

如果你搜索答案，大概率会看到一句话："因为空气散射了蓝光。"但这只回答了一半——如果蓝光被散射了，那它应该往四面八方跑，为什么偏偏跑到你眼睛里的是蓝色？而且，紫色波长比蓝色更短，按同样的逻辑应该散射更强，那为什么天不是紫色的？

更奇怪的是：日落的时候，同一片天空变成了红色、橙色。空气还是那些空气，光还是那个太阳光，为什么颜色完全变了？

解开这个谜题的人是英国物理学家瑞利勋爵（Lord Rayleigh）。1871年，他用数学推导出了一个优雅的结论，后来被称为**瑞利散射定律**。这个定律不仅能解释蓝天和红霞，还解释了为什么在月球上看天空，永远是黑色的——哪怕太阳就在头顶。`,
    core: `
太阳发出的白光，其实是所有颜色光的混合——从红到紫，波长从长到短。当这些光进入地球大气层，会遇到无数空气分子（主要是氮气和氧气）。

瑞利发现，光被分子散射的强度与波长的四次方成反比：

\$\$I_{\\text{散射}} \\propto \\frac{1}{\\lambda^4}\$\$

这意味着波长越短的光，散射越剧烈。蓝光波长约450纳米，红光波长约700纳米，蓝光的散射强度大约是红光的 \$(700/450)^4 \\approx 5.7\$ 倍——**蓝光被弹射到四面八方的概率是红光的近6倍**。

白天太阳高悬，阳光穿过大气层的路径较短。蓝光被大量散射，布满整个天空，所以你抬头看天——蓝色的。而红光、橙光几乎不被散射，沿直线继续前进，所以直视太阳时它偏白偏黄。

那为什么天不是紫色的？因为太阳光谱中紫光本身就比蓝光少，而且人眼对紫色不如蓝色敏感。两个因素叠加，蓝天胜出。

到了傍晚，太阳靠近地平线，阳光要穿过更厚的大气层才能到达你的眼睛——路径长度是正午的10~40倍。这么长的路，蓝光几乎全被散射掉了，"漏"过来的只剩下红光和橙光。于是你看到的太阳和周围的天空，都变成了温暖的红橙色。

在月球上呢？没有大气层，没有散射，光要么直射你眼，要么不射。所以月球的天空永远是漆黑的，太阳挂在一个纯黑的背景上——一种令人不安的景象。`,
    principle: `
**1. 瑞利散射**
当散射体（空气分子）远小于光的波长时，散射强度与波长四次方成反比。这是**高中物理·光学**中光的散射现象的经典案例。

**2. 大气光学路径**
光穿过大气层的路径越长，短波光的损耗越大，长波光透射比例越高。这和**高中物理·几何光学**中光的传播概念相关。`,
    thinking: `
**为什么重要？**
瑞利散射不只是解释了天空的颜色，它揭示了光与物质相互作用的基本规律。从天空的蓝到深海的黑，从星光的闪烁到宇宙微波背景的发现，散射现象贯穿了整个物理学。

**现代应用**
激光雷达（LIDAR）利用散射信号探测大气成分和污染物浓度。光纤通信中，瑞利散射是信号衰减的主要原因之一，工程师必须想办法克服它。甚至雾霾天灰蒙蒙的天空，也是散射——只是散射体从空气分子变成了更大的颗粒，规律从瑞利散射变成了米氏散射。

**还有什么未解之谜？**
火星的天空是粉红色的，因为大气中飘浮着细小的红色尘埃颗粒，散射规律完全不同。如果某颗系外行星的大气成分和颗粒分布不同，它的天空可能呈现出人类从未见过的颜色——天文学家正在通过光谱分析推测这些遥远世界的"天空颜色"。`,
  },
  'fun-007': {
    background: `
你坐在过山车的座位上，安全压杆"咔嗒"一声锁紧。列车缓缓爬升，链条发出沉闷的咔咔声，越爬越高。你的心跳加速——不是因为浪漫，而是因为恐惧。

终于到达顶点，列车一跃而下，风灌进耳朵，胃像被提起又扔下。紧接着，你被甩进一个竖直圆环——头朝下，脚朝上，整个世界倒过来了。你明明没有任何东西把你绑在座椅上（好吧，除了那根压杆），可你就是没掉下去。

为什么？

这个疑问可能比你想象的更古老。17世纪，牛顿就在思考一个类似的问题：月球绕地球转，为什么不会飞走也不会坠落？过山车和月亮，看似八竿子打不着，其实遵循同一套物理——向心力和惯性的精确配合。速度恰好够快，轨道恰好够弯，重力恰好被抵消——过山车的设计师用物理方程写出了每一秒的惊险。`,
    core: `
过山车最让人心惊肉跳的瞬间，是在竖直圆环顶端——你倒挂着，头顶是轨道，脚下是几十米高的虚空。

这时候你受到两个力：**重力**向下拽你，**轨道的支持力**也向下压你（因为你在轨道内侧，轨道在你头顶）。两个力都指向圆心，合力就是维持圆周运动的向心力。

\$\$mg + N = m\\frac{v^2}{R}\$\$

其中 \$m\$ 是你的质量，\$g\$ 是重力加速度，\$N\$ 是轨道对你的支持力，\$v\$ 是你在顶点的速度，\$R\$ 是圆环的半径。

关键问题来了：\$N\$ 可以为零吗？

可以。如果速度恰好使得 \$mg = m\\frac{v^2}{R}\$，即 \$v = \\sqrt{gR}\$，轨道完全不需要给你任何支持力——单靠重力就够提供向心力了。这个速度叫**临界速度**，是你不掉下来的最低速度。

假设圆环半径 \$R = 10\$ 米，临界速度就是：

\$\$v_{\\text{临界}} = \\sqrt{9.8 \\times 10} \\approx 9.9 \\, \\text{m/s}\$\$

大约36公里/小时。只要过山车在顶点的速度不低于这个值，你就不会掉下来。实际设计中，为了安全，顶点速度通常远高于临界值——一般在15~20 m/s，这样支持力 \$N\$ 仍然是正值，你被牢牢压在座椅上。

但如果你在顶点突然减速——比如轨道太粗糙，摩擦力太大——速度低于临界值，向心力不够了，你就会开始脱离轨道，做抛体运动。这就是为什么过山车的维护检查容不得半点马虎。

还有一点值得注意：过山车的圆环并不是完美的圆形。现代过山车采用的是"倒水滴"形状——入口半径大（曲率小，向心加速度小，乘客不会承受太大的力），顶部半径小（保证足够的向心力，防止掉落）。这种设计让乘客既刺激又安全，背后的每一处弧度都是物理计算的结果。`,
    principle: `
**1. 匀速圆周运动的向心力**
物体做圆周运动需要一个指向圆心的力，大小为 \$F = m\\frac{v^2}{R}\$。这是**高一下学期·曲线运动**的核心内容，也是过山车物理的灵魂。

**2. 临界条件分析**
当外力刚好等于所需向心力时，物体维持圆周运动；当外力不足时，物体做离心运动（远离圆心）；当外力过大时，物体做向心运动（靠近圆心）。这种临界分析是高中物理力学的常见题型。

**3. 机械能守恒**
过山车没有引擎，全靠初始高度转化来的动能。忽略摩擦时，任意两点间的机械能相等：

\$\$mgh_1 + \\frac{1}{2}mv_1^2 = mgh_2 + \\frac{1}{2}mv_2^2\$\$

最高点速度最慢，最低点速度最快——这是**高一·机械能守恒定律**的完美演示，也是过山车设计师计算每个位置速度的核心方程。`,
    thinking: `
**为什么重要？**
过山车是圆周运动和能量守恒的"活教材"。它把抽象的向心力变成了你身体能感受到的压力，把公式变成了肾上腺素。理解了它，你就理解了为什么卫星绕地球转不会掉下来——本质上是同一个物理。

**现代应用**
离心机、洗衣机脱水、汽车弯道设计、高速公路的弯道超高——都需要计算向心力和临界速度。航天员在离心机里训练时承受的力，和你在过山车顶点承受的力，遵循完全相同的方程，只是量级差了几十倍。

**还有什么未解之谜？**
人在极端加速和失重状态下的生理反应，至今还有许多未解之处。为什么有些人享受过山车，有些人却会晕厥？前庭系统（内耳平衡器官）的信号和视觉信号的冲突如何导致空间迷向？这些问题的答案，可能藏在神经科学而不是力学里。`,
  },
  'fun-008': {
    background: `
你有没有发现一个奇怪的事：手机屏幕能感应你的手指，但戴着手套就不行，拿铅笔也不行，甚至用指甲尖也不太灵。它到底在"看"什么？

不是压力，不是温度，也不是你在屏幕上的摩擦。你的手机屏幕——准确地说是绝大多数智能手机的屏幕——用的是**电容感应**。它感知的不是你"按了多用力"，而是你的手指作为一个导体，改变了屏幕表面的静电场分布。

这个技术2007年随初代iPhone引爆全球，但它的原理可以追溯到更早：1875年，英国物理学家弗莱明就在研究金属板之间的电容变化了。只不过那时候没人想到，这个原理有一天会被装进几十亿人的口袋里。`,
    core: `
电容触摸屏的结构比你想象的精巧得多。

屏幕表面布满了肉眼看不见的电极阵列——横向一排，纵向一列，交错排列。每一条横向电极和纵向电极的交叉点，就形成了一个微小的电容器。工作时，驱动芯片持续向这些电极施加电信号，在每个交叉点维持一个稳定的静电场。

这个场很小，小到你的手指没碰到屏幕时，它安安静静地待着。

但人是导体——人体大约60%是水，充满电解质，导电性相当不错。当你的手指靠近屏幕上某个位置，手指和屏幕之间形成了一个新的电容通路：一部分电场线不再在交叉点之间闭合，而是"泄漏"到了你的手指上。

结果呢？那个交叉点的电容量发生了微小变化——变小了，因为电场被"偷走"了一部分。驱动芯片每秒扫描上百次，检测到哪个交叉点的电容异常，就能精确定位你的触摸位置。

这就是为什么：
- **戴手套不行**——手套是绝缘体，切断了手指和屏幕之间的电容耦合
- **铅笔不行**——石墨虽然导电，但面积太小，电容变化微弱到检测不到
- **指甲不行**——指甲是绝缘体
- **湿手不太灵**——水是导体，大面积水膜会同时"偷走"多个交叉点的电场，导致定位混乱

多点触控也是同理——屏幕同时检测到多个电容异常点，分别计算坐标。你的两根手指捏合放大照片时，屏幕在几十毫秒内就完成了两次独立定位。`,
    principle: `
**1. 电容器与电容**
两个导体之间夹一层绝缘体就构成电容器，其电容量与导体面积、间距和绝缘体性质有关：

\$\$C = \\frac{\\varepsilon S}{d}\$\$

手指靠近屏幕时，相当于在原有电容器旁边并联了一个新的电容通路，改变了总电容量。这是**高二物理·电容器**的核心内容。

**2. 静电场与导体**
导体放入静电场中会感应出电荷，改变原有场分布。人体作为导体，靠近屏幕电极时引起电场线重新分布，这就是电容变化的根源。这些内容对应**高二·静电场**。`,
    thinking: `
**为什么重要？**
电容触控技术彻底改变了人机交互方式。从电阻屏（需要用力按压）到电容屏（轻触即应），这一步跨越让智能手机成为可能。没有它，就没有滑动解锁、双指缩放、手写输入——现代移动计算的一切体验都建立在这个物理原理之上。

**现代应用**
除了手机，电容感应还用在笔记本电脑的触控板、汽车的触控中控屏、工业触摸屏，甚至某些电子鼓的鼓面。可穿戴设备上的心电监测，也是靠检测皮肤表面的微弱电信号——本质上和触屏感应是同一类物理。

**还有什么未解之谜？**
电容屏在极端环境下表现不佳：戴厚手套、水下操作、出汗太多都会失灵。如何让触屏在各种条件下都稳定工作？柔性屏和折叠屏的电容阵列怎么跟随弯折？这些都是当下工程师在攻克的难题。也许未来的触屏不再依赖电容，而是用光学或超声波方案——到那时，戴着手套也能丝滑操作了。`,
  },
  'future-001': {
    background: `
《星际迷航》里的"企业号"一声"Engage!"就消失在星光中，以超光速穿越银河。科幻迷们看得热血沸腾，物理学家们则摇头——爱因斯坦说了，有质量的物体不可能达到光速，更别说超光速了。但1994年，威尔士物理学家米格尔·阿库别瑞发表了一篇论文，让整个相对论界坐了起来：他构造了一个不违反相对论的"超光速"时空——不是让飞船飞得比光快，而是让飞船前方的空间收缩、后方的空间膨胀，飞船本身不动，但被空间"搬运"着前进。就像冲浪者不需要跑得比浪快——站在浪上，浪带着你走。这个方案叫**阿库别瑞度规**，也叫曲速引擎。`,
    core: `
阿库别瑞的构想是这样的：飞船被包裹在一个"曲速泡"中，泡内时空平坦，飞船内的宇航员感觉不到任何加速度——没有过载，没有时间膨胀。泡外的时空则被极端扭曲：前方收缩，后方膨胀。整体效果是：曲速泡以超光速在空间中移动，但飞船相对于泡内局域空间是静止的。

\$\$ds^2 = -dt^2 + (dx - v_s f(r_s) dt)^2 + dy^2 + dz^2\$\$

这是阿库别瑞度规的简化形式——\$v_s\$ 是曲速泡的速度，\$f(r_s)\$ 是一个"形状函数"控制泡的边界。关键在于：\$v_s\$ 理论上可以大于c，因为这不是物体在空间中运动的速度，而是空间本身变形的速度——广义相对论没有限制空间膨胀或收缩的速度。

但问题立刻来了。第一，**需要负能量**。要把前方的空间压缩、后方的空间拉伸，需要一种能量密度为负的物质——"奇异物质"。我们目前只知道负能量在量子力学中可以以极微弱的形式存在（卡西米尔效应），但曲速泡需要的负能量总量是天文数字——阿库别瑞最初的计算表明，驱动一个100米宽的曲速泡需要的负能量比整个可观测宇宙的总质量还多。

第二，**因果律悖论**。如果超光速旅行可行，就有可能构建时间回路——你可以回到过去给自己发消息，这违反了因果律。大多数物理学家认为，任何允许超光速的方案最终都会与因果律冲突，而大自然不会允许这种事情发生。

第三，**控制问题**。飞船前方的空间被压缩了，这意味着所有前方的物质——星际尘埃、光子、甚至行星——都被挤压到泡壁上。当你减速停下时，这些积累的能量会被释放出来，形成毁灭性的冲击波。曲速飞船到达目的地的那一刻，可能先把目的地炸了。

近年有一些乐观的进展。2012年，NASA的哈罗德·怀特提出，如果改变曲速泡的形状——从薄环变成厚环——可以将负能量需求从"整个宇宙的质量"降低到"木星的质量"量级。虽然仍然是天文数字，但至少不是不可能了。2021年，物理学家埃里克·伦茨找到了一种不需要负能量的超光速时空解——但他的方案需要一种新型的"正质量超光速流体"，这种物质是否存在完全是未知数。`,
    principle: `
1. **光速限制**：狭义相对论中，有质量物体加速到光速需要无限能量。\$E = \\gamma mc^2\$，当 \$v \\to c\$，\$\\gamma \\to \\infty\$——但这是物体在空间中运动的速度限制，不是空间本身变形的限制。（选修·相对论简介）

2. **空间膨胀可以超光速**：宇宙膨胀已经使得极远处的星系以超光速退行——这不是星系在空间中运动快于光速，而是空间本身在膨胀。\$v_{\\text{退行}} = H_0 \\times d\$，距离足够远时退行速度超过c，这不违反相对论。

3. **负能量与卡西米尔效应**：两块平行金属板之间的真空涨落被限制，产生比板外更低的能量密度——这就是量子力学中已知的负能量。\$E_{\\text{卡西米尔}}/A = -\\frac{\\pi^2 \\hbar c}{720 d^4}\$——但这个量极其微小，远不足以驱动曲速泡。

4. **度规与时空几何**：广义相对论中，时空的几何由度规张量描述。阿库别瑞通过巧妙选择度规的形式，构造了一个允许"超光速运动"的时空解——这是数学上的解，不代表自然界一定允许这种时空存在。`,
    thinking: `
**为什么重要？**
曲速引擎代表了人类对星际旅行最根本的渴望。如果银河系内有宜居行星，但以1%光速到达最近的恒星也要400多年——这样的时间尺度让星际文明几乎不可能。曲速引擎如果实现，将彻底打开星际旅行的大门。

**现代应用**
虽然曲速引擎本身尚未实现，但相关研究推动了广义相对论数值计算和时空几何的发展。NASA的Eagleworks实验室在极小尺度上测试了空间被压缩的可能性，虽然结果尚无定论，但这种"大胆假设、小心验证"的精神正是科学进步的动力。

**还有什么未解之谜？**
曲速引擎最大的未知是：负能量是否能在宏观尺度上实现？如果能，需要多少？更深层的问题是：广义相对论的解是否都对应物理上可实现的状态？数学允许的不一定自然允许——也许未来某个更完整的量子引力理论会证明，曲速泡在原理上就不可能存在。但在那个理论出现之前，人类对星际旅行的梦想不会停止。`,
  },
  'future-002': {
    background: `
《星际迷航》里最令人神往的技术不是曲速引擎，而是传送器——人站在平台上，一道光闪过，身体化成粒子流穿越太空，在目的地重新凝聚。这比任何飞船都浪漫：瞬间到达，无需旅途。1993年，六个物理学家在一篇论文中证明了一件惊人的事：利用量子纠缠，可以把一个粒子的量子状态"传送"到远处的另一个粒子上——这就是**量子隐形传态**。1997年，安东·蔡林格的团队首次在光子之间实现了量子隐形传态。2017年，中国"墨子号"卫星实现了相距1200公里的量子隐形传态。但这是不是意味着有朝一日能传送人？答案比你想的复杂得多。`,
    core: `
量子隐形传态的原理精妙而反直觉。假设Alice有一个光子A，处于某个未知的量子态 \$|\\psi\\rangle\$，她想把信息传给远处的Bob。但量子力学有个铁律：**不可克隆定理**——你不可能完美复制一个未知的量子态。测量它会破坏它，复制它不可能。Alice怎么把 \$|\\psi\\rangle\$ 传给Bob？

解决方案用到了量子纠缠。Alice和Bob事先共享一对纠缠光子B和C——Alice拿B，Bob拿C。然后Alice对A和B做一种特殊的联合测量（Bell态测量），这个测量会立刻改变远处Bob手中的C的状态——但此时C并不直接等于 \$|\\psi\\rangle\$，而是与 \$|\\psi\\rangle\$ 差了一个操作。Alice把测量结果通过经典信道（电话、电子邮件等，速度不超过光速）告诉Bob，Bob根据这个信息对C做相应的酉操作，C就变成了 \$|\\psi\\rangle\$ 的精确复制品。同时，A的状态已经被测量破坏——原来的 \$|\\psi\\rangle\$ 不复存在。信息从Alice传到了Bob，但没有粒子在两地之间移动，这就是"隐形传态"。

\$\$|\\psi\\rangle_A \\xrightarrow{\\text{Bell测量+经典通信+酉操作}} |\\psi\\rangle_C\$\$

关键限制：经典通信步骤不可省略，所以量子隐形传态**不可能超光速**——Alice必须通过光速以下的信道告诉Bob测量结果，Bob才能恢复量子态。这确保了不违反因果律。

另一个关键限制来自**不可克隆定理**：\$|\\psi\\rangle\$ 被传送后，原版被破坏。你不可能同时拥有原件和复制品——要么传送，要么保留，不能兼得。这对"传送人"有深刻的哲学含义。

如果要把一个人传送到火星，你需要测量他全身约 \$10^{27}\$ 个原子的量子态，用纠缠粒子对和经典信道把这些信息传到火星，再在火星上用这些信息重建他的身体。但问题是：测量人体所有原子的量子态会完全破坏原来的身体——你实际上是被"杀死"了，然后在火星上被"重新制造"了一个。火星上的那个人和你拥有完全相同的记忆、性格和身体，但他是不是"你"？如果传送过程中出了故障，原来的你被销毁了，新的你还没建好呢——你就真的死了。哲学家们管这叫"传送悖论"。`,
    principle: `
1. **量子纠缠**：两个纠缠粒子的状态不可独立描述。测量一个立刻确定另一个，无论距离多远。\$|\\Psi\\rangle = \\frac{1}{\\sqrt{2}}(|00\\rangle + |11\\rangle)\$——这就是Alice和Bob共享的纠缠资源。（高二下学期·波粒二象性延伸）

2. **不可克隆定理**：不存在一个通用操作能完美复制任意未知量子态。证明基于量子力学的线性性和幺正性——如果允许克隆，就可以超光速通信，违反因果律。这是量子信息论的基石之一。

3. **Bell态测量**：对两个粒子进行联合测量，投影到四个Bell态之一。测量结果决定Bob需要对C做什么操作——四种可能对应四种不同的酉操作。

4. **经典信道的必要性**：没有经典通信，Bob无法知道该做什么操作——量子态传送不可超光速。传送1个量子比特需要1对纠缠粒子+2经典比特。`,
    thinking: `
**为什么重要？**
量子隐形传态不是科幻中的瞬间传送，但它是量子通信和量子计算的关键技术。量子密码、量子中继器、量子互联网——所有这些未来技术都需要隐形传态作为基础组件。它也是理解量子力学最深刻悖论（纠缠和非定域性）的绝佳窗口。

**现代应用**
量子隐形传态是量子互联网的核心技术。中国的京沪干线量子通信网络已经实现了北京-上海之间的量子密钥分发，下一步目标就是量子中继和量子互联网。欧洲的量子互联网联盟也在推进类似计划。2022年诺贝尔物理学奖颁给了蔡林格等人，表彰他们在量子信息和隐形传态方面的开创性工作。

**还有什么未解之谜？**
量子隐形传态能传送多大的系统？目前实验已经实现了少量原子的量子态传送，但距离传送宏观物体还差几十个数量级。更深层的问题是意识：如果一个人的完整量子态被传送到另一个身体里，新的个体是否拥有原来的意识？意识是否可以"拷贝"？或者，意识根本不是量子态能描述的东西？这些问题横跨物理、哲学和认知科学，也许永远不会有标准答案——但正是这些没有答案的问题，让物理学始终与人类最深的思考相连。`,
  },
  'insight-001': {
    background: `
1712年，英国矿井里弥漫着积水。矿工们用马拉的水泵日夜抽水，效率低得令人绝望。一个叫托马斯·纽科门的铁匠造出了一台奇怪的机器：锅炉烧水产生蒸汽，蒸汽推入汽缸，然后喷入冷水让蒸汽骤然凝结，汽缸内形成真空，大气压就把活塞压回来——这一推一拉，就能带动水泵抽水。纽科门蒸汽机确实能抽水，但它效率极低，烧掉成吨的煤却只干了一点活，只有煤矿这种燃料不要钱的地方才用得起。半个世纪后，一个叫詹姆斯·瓦特的仪器修理工被请去修理一台纽科门机。他盯着那台笨重的机器看了很久，发现了一个致命的问题：汽缸一会儿加热一会儿冷却，来回浪费了大量热能。如果能解决这个问题呢？`,
    core: `
瓦特的天才改进是加了一个**分离冷凝器**：汽缸始终保持高温，蒸汽做完功后导入一个单独的冷凝器冷却。这样汽缸就不用反复加热冷却了——仅此一项，效率就提高了三倍。瓦特后来又加了飞轮、曲轴、离心调速器（自动控制转速的装置），让蒸汽机从只能抽水的单功能机器变成了通用动力源。到了18世纪末，蒸汽机驱动纺织机、驱动磨坊、驱动火车——整个英国的工厂开始轰鸣，工业革命就这样被一台冒烟的铁家伙推着往前冲。但蒸汽机的效率到底能有多高？这个问题困扰了物理学家几十年。1824年，一个28岁的法国工程师萨迪·卡诺给出了答案。他想象了一台"完美的热机"：工作在两个恒温热源之间，所有过程都是理想的可逆过程。他证明了热机的最大效率只取决于两个温度：

\$\$\\eta_{\\max} = 1 - \\frac{T_C}{T_H}\$\$

冷源温度 \$T_C\$ 越低、热源温度 \$T_H\$ 越高，效率越大。这就是卡诺定理——它不仅给蒸汽机指明了改进方向（提高锅炉温度、降低排气温度），更深刻地揭示了热与功之间的根本关系，为热力学第二定律的建立铺平了道路。`,
    principle: `
1. **热机的工作原理**：热机从高温热源吸热 \$Q_H\$，对外做功 \$W\$，向低温热源放热 \$Q_C\$。能量守恒要求 \$Q_H = W + Q_C\$——你不可能把吸收的热量全部变成功，必然有一部分要排掉。（高一下学期·热学）

2. **卡诺效率**：\$\\eta = 1 - T_C/T_H\$，温度必须用开尔文温标。如果锅炉400°C（673K）、排气25°C（298K），最大效率约56%——实际蒸汽机远低于此，19世纪的蒸汽机效率只有5%~10%。

3. **热力学第二定律的雏形**：卡诺定理暗示了一个深刻的真理——热量不可能100%转化为功。总有一部分热被"浪费"了，这不是技术问题，而是自然法则。`,
    thinking: `
**为什么重要？**
蒸汽机和卡诺定理一起，开创了"热力学"这门科学。热力学不仅统治了所有热机的设计，更揭示了宇宙的一个基本法则：能量转化是有方向性的，你不可能无代价地把热变成功。从蒸汽机到内燃机到喷气发动机，所有动力技术的进步都遵循这条底层规则。

**现代应用**
现代燃气轮机和联合循环电站的热效率已超过60%，非常接近卡诺极限。而超临界二氧化碳发电技术正在尝试将工作温度推到700°C以上，进一步逼近理论极限——每一次效率的提升，都是对卡诺定理更精确的实践。

**还有什么未解之谜？**
卡诺定理设定了效率的天花板，但能否绕过它？量子热机——利用量子相干性和纠缠工作的微型"热机"——在理论模型中展现了一些反直觉的特性，比如在特定条件下可能突破经典的效率限制。这究竟是真正的突破，还是理论上的特例？量子热力学正在重新审视那些被卡诺视为理所当然的假设。`,
  },
  'insight-002': {
    background: `
1895年11月8日，德国维尔茨堡大学的威廉·伦琴像往常一样在实验室里做阴极射线实验。他用黑色硬纸板把克鲁克斯管（一种放电管）严严实实地包住，确保没有光漏出来。然后他关掉灯，准备离开。就在这时，他注意到工作台上距离管子约一米远的一块荧光屏在发光——理论上，阴极射线不可能穿透硬纸板走那么远。伦琴没有忽略这个"不对劲"。他反复实验，发现这种未知的射线能穿透纸板、木头、甚至人体，唯独对金属和骨骼几乎无法穿透。他把这种射线叫"X射线"——X代表"未知"。几周后，他给妻子的手拍了一张X光片：骨骼清晰可见，手指上的戒指在黑暗中投下一道白影。这张照片轰动了全世界，不到一年，X射线就被用于战场上的弹片定位。1901年，伦琴获得了首届诺贝尔物理学奖。`,
    core: `
X射线的本质是什么？它不是粒子，也不是什么神秘物质——它是电磁波，波长在0.01到10纳米之间，比可见光短上千倍。波长越短，光子能量越高，穿透能力越强。这就是为什么X射线能穿透肌肉（密度低、原子序数小）却被骨骼（密度高、含钙等重元素）挡住。

\$\$E = h\\nu = \\frac{hc}{\\lambda}\$\$

X射线光子的能量 \$E\$ 与波长 \$\\lambda\$ 成反比——波长越短，能量越高。医用X射线波长约0.01~0.1纳米，对应能量12~120 keV，刚好在"穿透软组织、被骨骼吸收"的甜蜜区间。

X射线如何成像？当X射线穿过人体时，不同组织对X射线的吸收程度不同。骨骼含钙（原子序数20），吸收最多，在底片上呈现白色；肌肉和器官主要含碳、氢、氧等轻元素，吸收较少，呈现灰色；空气几乎不吸收，呈现黑色。这就是X光片的原理——本质上是一张"密度地图"。

但普通X光片是二维投影，所有组织重叠在一起。1970年代，英国工程师豪斯菲尔德和美国物理学家科马克独立发明了CT（计算机断层扫描）：从多个角度拍摄X射线投影，然后用数学算法（Radon变换）重建出三维的断层图像。CT让医生第一次看到了大脑、肺、肝脏的横截面——不再是一堆重叠的影子，而是清晰的切面。豪斯菲尔德和科马克因此获得1979年诺贝尔生理学或医学奖。

X射线不仅改变了医学，还彻底改变了物理学。1895年发现X射线后仅仅几个月，贝克勒尔就发现铀盐也能使底片感光——这就是放射性的发现。X射线又催生了布拉格父子的晶体衍射实验，让人类第一次"看到"了原子的排列方式。DNA双螺旋结构的发现也依赖于X射线衍射——罗莎琳德·富兰克林拍摄的第51号照片，是沃森和克里克破解生命密码的关键线索。`,
    principle: `
1. **X射线的产生**：高速电子撞击金属靶（通常为钨），突然减速时发出轫致辐射（bremsstrahlung）——电子被原子核偏转时，动能转化为X射线光子。管电压越高，电子速度越快，产生的X射线波长越短、能量越高。（高二下学期·电磁波+原子物理）

2. **光电吸收**：X射线穿过物质时，光子被原子吸收，打出内层电子。吸收概率与原子序数Z的约4次方成正比，\$P_{\\text{abs}} \\propto Z^4/\\lambda^3\$——所以骨骼（含钙Z=20）比肌肉（主要含碳Z=6）吸收得多得多，这就是骨骼在X光片上显白的原因。

3. **CT重建原理**：从不同角度测量X射线的衰减，用数学反投影算法重建每个体素的衰减系数——就像从无数个方向的影子反推出物体的三维形状。

4. **X射线衍射**：X射线波长与原子间距相近，晶体就像天然的光栅。布拉格定律 \$2d\\sin\\theta = n\\lambda\$ 确定了衍射条件——通过分析衍射图案，可以推断出晶体的原子结构。`,
    thinking: `
**为什么重要？**
X射线的发现是物理学"纯粹好奇驱动应用"的经典案例。伦琴不是为了看病才研究阴极射线的，但他的好奇心直接催生了现代医学影像。从X光到CT到放疗，X射线相关的技术拯救了数以亿计的生命——而这一切始于实验室里一块不该发光的荧光屏。

**现代应用**
除了传统X光和CT，X射线在同步辐射光源中扮演了更强大的角色。同步辐射X射线亮度比医用X光机高万亿倍，能用于蛋白质结构解析、新材料设计和文化遗产分析。上海光源就是中国最先进的第三代同步辐射装置，每年服务上千个研究项目。

**还有什么未解之谜？**
X射线对人体的伤害如何更精确地量化和控制？低剂量X射线是否真的安全，是否存在"线性无阈"效应——即任何剂量的辐射都有致癌风险？这个问题至今没有定论，直接影响着医疗辐射防护的标准制定。同时，自由电子激光正在把X射线技术推向单分子成像的极限——也许有一天，我们能实时拍下化学反应中原子运动的"电影"。`,
  },
  'insight-003': {
    background: `
1947年12月23日，贝尔实验室的两位科学家巴丁和布拉坦做了一个看起来毫不起眼的实验：在一块锗晶体上贴了两根相距仅50微米的金丝，通上电流后，他们发现从一根金丝输入的微弱信号，从另一根出来时被放大了——世界上第一个晶体管诞生了。这个指甲盖大小的器件，取代了比灯泡还大的真空管，开启了电子学的新纪元。但当时的贝尔实验室主管们并没有意识到他们手里的东西有多伟大——他们的目标是造出更好的电话中继器，而不是改变世界。十一年后，杰克·基尔比把多个晶体管、电阻、电容做在同一块半导体片上，发明了集成电路——从此，硅取代了钢铁，成为定义文明的核心材料。`,
    core: `
半导体的"半"字很关键：它不像金属那样导电，也不像绝缘体那样完全不导电，而是处于两者之间——更厉害的是，它的导电性可以被精确操控。这种操控的秘密在于**掺杂**。纯硅有4个外层电子，每个电子和相邻硅原子共享，形成稳定的共价键——几乎没有自由电子，所以纯硅导电性很差。但如果你在硅里掺入少量磷（5个外层电子），多出来的那个电子无处可去，变成自由电子——这就是N型半导体。如果掺入硼（3个外层电子），少了一个电子的位置形成"空穴"——空穴像正电荷一样移动，这就是P型半导体。

当P型和N型半导体贴在一起时，交界处形成一个**PN结**——这是半导体世界最重要的发明。N型的自由电子向P型扩散，填补空穴，在交界处形成一个没有自由电荷的"耗尽层"，同时产生一个内建电场，阻止进一步扩散。这就是PN结的单向导电性：正向电压压缩耗尽层，电流畅通；反向电压拉宽耗尽层，电流几乎为零。

\$\$I = I_S(e^{qV/kT} - 1)\$\$

这是PN结的电流-电压关系——V是外加电压，q是电子电荷，k是玻尔兹曼常数，T是温度。正向偏置时电流指数增长，反向偏置时几乎为零——一个PN结就是一个天然的电子阀门。

晶体管的结构更精巧：两个PN结背靠背，形成NPN或PNP三层结构。中间的薄层叫基极，通过控制基极的微小电流，就能控制从发射极到集电极的大电流——这就是"放大"。想象一个水龙头：你轻轻拧一下手柄（基极电流），大量的水（集电极电流）就喷涌而出。这个原理听起来简单，但它让所有电子设备成为可能。

集成电路则更进一步：在一片硅片上同时制造数十亿个晶体管，用金属线连接它们，形成一个完整的电路。1971年，Intel 4004芯片上有2300个晶体管；2024年，最先进的芯片上晶体管数量超过1000亿个——50年间增长了4亿倍。摩尔定律虽然正在减速，但人类把更多功能塞进更小空间的能力仍然令人瞠目。`,
    principle: `
1. **能带理论**：固体中大量原子的能级合并成连续的能带。价带被电子填满，导带是空的，中间的间隙叫禁带。半导体的禁带宽度约0.5~3 eV——不大不小，既不像金属（禁带为零，电子自由移动），也不像绝缘体（禁带>5 eV，电子跨不过去）。（选修·固体物理简介）

2. **PN结的单向导电性**：扩散与漂移的平衡决定了电流方向。正向偏置时耗尽层变窄，扩散电流>>漂移电流，导通；反向偏置时耗尽层变宽，几乎截止——这就是整流和开关的物理基础。

3. **场效应管(MOSFET)**：现代芯片的基本单元。在栅极上加电压，产生的电场在硅表面诱导出一个导电通道——通过电场控制电流，不需要基极电流输入，功耗极低。\$I_D \\propto (V_{GS} - V_{th})^2\$——漏极电流与栅极电压的关系是平方律。

4. **光刻与微纳加工**：用紫外光把电路图案"印"到硅片上的光刻胶上，再通过刻蚀、离子注入等步骤形成晶体管结构。光刻精度决定了晶体管的最小尺寸——目前最先进的极紫外光刻(EUV)使用13.5纳米波长的光。`,
    thinking: `
**为什么重要？**
没有半导体，就没有计算机、没有互联网、没有智能手机——现代文明的信息基础设施完全建立在硅片之上。半导体技术是物理学（能带理论、量子力学）转化为工程奇迹的最成功案例，它证明了对微观世界的理解可以直接改写宏观世界的面貌。

**现代应用**
除了处理器和存储器，半导体还推动了光伏发电（硅太阳能电池将光能转化为电能）、LED照明（半导体发光二极管）、和功率电子（电动汽车的电控系统）。中国在光伏领域已占据全球80%以上的产能，半导体产业链正在加速追赶。

**还有什么未解之谜？**
摩尔定律还能走多远？当晶体管尺寸缩小到几个纳米，量子隧穿效应开始捣乱——电子会"穿墙"泄漏，器件无法正常关断。新材料（碳纳米管、二维材料、拓扑绝缘体）和新架构（量子计算、神经形态计算）正在探索后硅时代的出路。谁先找到替代方案，谁就掌握了下一代信息文明的钥匙。`,
  },
  'insight-004': {
    background: `
1958年，阿瑟·肖洛和查尔斯·汤斯发表了一篇论文，论证了用红外线和可见光实现受激辐射的可能性。他们的同事听了之后纷纷摇头：这东西有什么用？两年后，1960年5月16日，西奥多·梅曼用一根红宝石棒和一盏闪光灯，第一次让光放大成为现实——一束极细、极亮、颜色单一的红色光从红宝石中射出。这就是世界上第一台激光器。当时的媒体把激光称为"死亡射线"，科幻作家们脑洞大开，想象激光武器摧毁城市。但物理学家们的反应更务实，也更刻薄：有人管激光叫"a solution looking for a problem"——一个到处找问题的解决方案。没人想到，这束光日后会渗入人类生活的每一个角落。`,
    core: `
激光的"激"字来自**受激辐射**——爱因斯坦在1917年就从理论上预言了这种现象。想象一个原子处于高能态，一个光子经过时恰好具有与原子跃迁能量匹配的频率，这个光子会"诱导"原子释放一个完全相同的光子：频率相同、方向相同、相位相同——就像一个光子"克隆"了自己。一个变两个，两个变四个……这就是光放大。

但要让受激辐射超过自发辐射（原子随机跳回低能态），必须实现**粒子数反转**——高能态的原子比低能态的多。在热平衡中，低能态原子总是更多，受激辐射被吸收压过，不会产生净放大。梅曼的突破在于：用闪光灯"泵浦"红宝石中的铬离子，把大量原子推到高能态，实现反转。一旦反转实现，一个自发辐射的光子就能触发连锁反应，在两面平行的反射镜之间来回放大，最终从半透镜射出一束高度平行的光——激光。

\$\$N_2 > N_1 \\implies \\text{粒子数反转}\$\$

\$N_2\$ 是高能态粒子数，\$N_1\$ 是低能态粒子数——要实现激光，高能态必须比低能态多，这违反了热平衡的常态。

激光有三个独特性质让它无可替代：**单色性**（只有一个频率，不像灯泡发出各种颜色的光）、**相干性**（所有光波步调一致）、**方向性**（几乎不发散，从地球照到月球也只扩散到几公里宽）。这三个特性组合起来，让激光成了精密操控光子的终极工具。

光纤通信是激光最伟大的应用。信息被编码成激光脉冲，在比头发还细的玻璃纤维中全反射传播，速度接近光速。一根光纤的传输容量可达每秒数万亿比特——全球互联网的流量，大部分都在激光脉冲中穿越大洋。没有激光，就没有现代互联网。`,
    principle: `
1. **受激辐射**：入射光子诱导高能态原子释放同频率、同方向、同相位的光子。\$E_2 - E_1 = h\\nu\$——释放的光子能量精确等于两个能级之差，所以激光的单色性极好。（高二下学期·原子物理）

2. **粒子数反转**：通过外部能量（泵浦）将原子从低能态抽运到高能态，使 \$N_2 > N_1\$。常见方式有光泵浦（闪光灯/激光二极管）、电泵浦（电流注入）、化学泵浦等。

3. **光学谐振腔**：两面平行反射镜之间，光子来回反射不断被放大。谐振条件 \$2nL = m\\lambda\$——只有特定波长能在腔内形成驻波并被强化，进一步提升了单色性。

4. **全反射与光纤**：光从光密介质射向光疏介质时，入射角大于临界角即全反射。\$\\sin\\theta_c = n_2/n_1\$——光纤纤芯折射率高于包层，光在纤芯中不断全反射向前传播，损耗极低。（高二上学期·光学）`,
    thinking: `
**为什么重要？**
激光是人类第一次能够"定制"光的性质——选择它的颜色、方向、脉冲方式。这种对光的精确操控，直接催生了光纤通信、激光手术、精密测量等现代技术。它证明了"纯粹物理"（受激辐射是量子力学的基本过程）可以产生改变世界的应用。

**现代应用**
激光切割和焊接已成为制造业的标准工艺，精度可达微米级。激光雷达（LiDAR）用激光脉冲测绘地形，是自动驾驶的"眼睛"。飞秒激光能在不损伤周围组织的情况下切割角膜，让LASIK手术成为可能。2023年全球激光产业市场规模已超过200亿美元。

**还有什么未解之谜？**
X射线激光和伽马射线激光仍然是未竟的目标——它们的波长更短、能量更高，如果实现，将带来原子尺度的全息成像和核物理的精确操控。另一个前沿是"激光推进"：用高功率激光照射飞船底部的反射板，利用光压推进——理论上可以让飞船达到光速的几分之一，但所需的激光功率远超目前的技术极限。`,
  },
  'insight-005': {
    background: `
打开手机导航，几秒内就能知道自己的位置——这套便利背后藏着一个多数人不知道的秘密：GPS卫星上的时钟每天都在被相对论修正。这不是工程师的过度设计，而是硬性需求。如果不去修正相对论效应，GPS的定位误差每天会增加约10公里——一个月后，导航会把你指到另一个城市。爱因斯坦在1905年和1915年提出的两个相对论，一个让卫星上的钟变慢，一个让卫星上的钟变快，两个效应方向相反但量级不同，必须同时考虑才能得到正确结果。GPS是人类日常使用中唯一需要同时考虑狭义和广义相对论的系统——相对论不是遥远的理论物理，它就在你的口袋里。`,
    core: `
GPS的工作原理依赖精确计时。24颗以上的卫星在约20200公里的高空绕地球飞行，每颗卫星携带铯原子钟，精度达到纳秒级。卫星不断广播自己的位置和时间，你的手机接收至少4颗卫星的信号，通过计算信号到达的时间差，算出自己到每颗卫星的距离，从而确定三维位置。

\$\$d = c \\times \\Delta t\$\$

距离等于光速乘时间差。光速约30万公里/秒，1微秒的计时误差就导致300米的定位偏差。所以，卫星时钟的精度直接决定导航的精度——差1纳秒，就偏30厘米。

问题来了：卫星上的钟和地面的钟走得不一样快。有两层原因：

**狭义相对论效应**：卫星以约3.9 km/s的速度飞行，根据狭义相对论，运动时钟变慢。时间膨胀系数约为 \$1/\\sqrt{1-v^2/c^2}\$，卫星钟每天比地面钟慢约7微秒。

**广义相对论效应**：卫星在20200公里高处，引力比地面弱。根据广义相对论，引力越弱，时钟越快。卫星钟每天比地面钟快约45微秒。

两个效应叠加：\$45 - 7 = 38\$ 微秒/天——卫星钟比地面钟每天快约38微秒。如果不修正，每天累积的定位误差为 \$38 \\times 10^{-6} \\times 3 \\times 10^8 \\approx 11.4\$ 公里。

\$\$\\Delta t_{\\text{总}} = \\Delta t_{\\text{广义}} + \\Delta t_{\\text{狭义}} \\approx +45 - 7 = +38 \\, \\mu\\text{s/天}\$\$

工程师的解决方案简单粗暴：在卫星发射前，把原子钟的振荡频率从10.23 MHz调低到10.22999999543 MHz——故意让它在地面走慢一点，上天后因为相对论效应自然"校准"到正确的频率。此外，地面监控系统还持续对卫星钟进行微调校正。就这样，爱因斯坦的两个理论在你每天用导航时默默工作。`,
    principle: `
1. **狭义相对论·时间膨胀**：运动时钟变慢。\$\\Delta t' = \\Delta t / \\sqrt{1 - v^2/c^2}\$——v越大，时间膨胀越显著。卫星速度3.9 km/s，虽远小于光速，但每天累积的效应已达微秒量级。（选修·相对论简介）

2. **广义相对论·引力时间膨胀**：引力越强，时钟越慢。\$\\Delta t_{\\text{高}} = \\Delta t_{\\text{低}} \\times (1 + \\Delta\\Phi/c^2)\$——\$\\Delta\\Phi\$是引力势差。卫星所在高度的引力势比地面高，所以卫星钟更快。

3. **三边测量定位**：已知4颗卫星的位置和信号到达时间，列4个方程求解接收机的3个空间坐标和1个时钟偏差。\$d_i = \\sqrt{(x-x_i)^2 + (y-y_i)^2 + (z-z_i)^2} = c(t_i - t_0)\$——4个方程4个未知数，有唯一解。（高一上学期·运动学基础）

4. **原子钟原理**：利用铯-133原子超精细跃迁频率（9192631770 Hz）定义"秒"。原子钟的精度可达 \$10^{-16}\$，即运行3亿年误差不超过1秒——这种精度才让GPS的米级定位成为可能。`,
    thinking: `
**为什么重要？**
GPS是相对论从象牙塔走向日常生活的经典案例。在爱因斯坦发表相对论的时代，没有人能想象这些理论有一天会用在导航上。它告诉我们：基础研究看似"无用"，但今天的"无用"可能是明天不可或缺的基础。

**现代应用**
GPS不仅用于导航，还支撑着金融交易的精确时间戳（纳秒级同步）、电网的相位同步、地震监测和自动驾驶。中国的北斗导航系统同样需要相对论修正，且额外使用了更复杂的星间链路技术实现自主运行。全球四大导航系统（GPS、北斗、伽利略、格洛纳斯）的精确运转都离不开相对论。

**还有什么未解之谜？**
相对论效应在GPS中的修正精度是否还能更高？目前修正到纳秒级已经够用，但未来的深空导航需要更高精度——在火星距离上，相对论效应的量级完全不同，需要考虑太阳引力场的弯曲和行星运动的复杂性。此外，量子钟（精度达 \$10^{-18}\$）能否替代原子钟进一步提升导航精度？量子钟如此灵敏，甚至能探测到1厘米高度差的引力时间膨胀——如果用在导航卫星上，相对论修正需要精确到前所未有的程度。`,
  },
  'micro-001': {
    background: `
1909年的曼彻斯特，卢瑟福的实验室里有两个年轻人——盖革和马斯登。卢瑟福让他们做一个看似无聊的实验：用α粒子（高速氦核）轰击金箔，观察α粒子偏转的角度。

按照当时的原子模型——J.J.汤姆孙的"葡萄干布丁"模型——原子是一团均匀分布的正电荷，电子像葡萄干一样嵌在里面。α粒子比电子重几千倍，穿过这样的原子应该几乎不偏转，就像子弹穿过棉花。

盖革和马斯登照做了。大多数α粒子确实穿过了金箔，偏转很小。但有一个结果让所有人都懵了：**偶尔有α粒子被大角度弹回——有的甚至反弹了90°以上。**

盖革把结果告诉卢瑟福。卢瑟福后来说："那是我一生中最不可思议的事情。就像你朝一张卫生纸发射一枚15英寸炮弹，炮弹弹回来打中了你。"`,
    core: `
卢瑟福花了两年来理解这个结果。

如果原子是"葡萄干布丁"，α粒子不可能被弹回——因为正电荷均匀分布，没有集中力能把沉重的α粒子推回去。唯一的解释是：**原子的正电荷和绝大部分质量集中在一个极小的核心——原子核**。

卢瑟福的计算表明，原子核的半径约为 \$10^{-14}\$ 米，而原子半径约为 \$10^{-10}\$ 米。也就是说，**原子核只占原子体积的万亿分之一**——如果把原子放大到足球场那么大，原子核只有一颗绿豆大小。

这解释了为什么绝大多数α粒子直接穿过——它们根本没有碰到原子核。偶尔有一发α粒子恰好对准了那个微小的核心，被强大的库仑力弹回来，就像被保龄球弹回的乒乓球。

1911年，卢瑟福提出了**原子核式结构模型**：原子中心是一个带正电的原子核，电子在核外绕核运动，就像行星绕太阳——后来被称为"行星模型"。

这个模型有一个根本问题（前面玻尔那篇已经提过）：经典电磁学预言电子绕核运动会辐射能量，最终坠入原子核。但卢瑟福不管这些——他的实验数据清楚地表明原子核存在，理论的问题留给后人解决。

**金箔实验的意义远不止发现原子核**。它开创了一种全新的研究方法——**散射实验**：用高速粒子轰击目标，从偏转角度推断目标的内部结构。这种方法后来成为粒子物理的标准手段，一直延续到今天的大型强子对撞机（LHC）。`,
    principle: `
**1. 库仑散射**
α粒子带正电（电荷+2e），金原子核也带正电（电荷+79e），两者互相排斥。α粒子越靠近原子核，受到的库仑力越大，偏转越厉害。卢瑟福推导了散射角分布的公式，与实验数据完全吻合——这是库仑定律在微观尺度上的直接验证。对应**高二·静电场**中库仑力的应用。

**2. 原子的核式结构**
原子由极小的原子核和核外电子组成。原子核集中了原子的全部正电荷和99.9%以上的质量。这是**高三物理·原子结构**的基础知识。`,
    thinking: `
**为什么重要？**
发现原子核是人类认识物质世界的一个关键转折点。在此之前，人们以为原子是不可分割的最小单位；卢瑟福告诉你：原子里面几乎是空的，核心只有绿豆大。这种"空虚"令人震惊——你坐的椅子、你的身体、整个世界，本质上都是虚空中的稀疏结构。

**现代应用**
卢瑟福的散射方法至今是探测微观结构的通用手段。材料科学中用离子束散射分析薄膜的厚度和成分；医学中用质子束治疗肿瘤，利用的正是带电粒子在物质中的散射行为。而LHC上每一次质子对撞的数据分析，本质上都是金箔实验的超级放大版。

**还有什么未解之谜？**
原子核内部又是什么？质子和中子由夸克组成，夸克之间通过胶子传递强力——但这套理论（量子色动力学）在计算原子核的多体问题时仍然极其困难。为什么夸克不能单独存在（色禁闭）？原子核的质量为什么不等于质子质量加中子质量（质量亏损从哪来）？这些问题直指强相互作用的核心谜题。`,
  },
  'micro-002': {
    background: `
1895年，伦琴发现了X射线，整个物理学界兴奋不已——一种看不见的射线居然能穿透人体！科学家们纷纷开始寻找新的"神秘射线"。

1896年，法国物理学家贝克勒尔也加入了搜索。他听说X射线和荧光有关，就猜想：会不会荧光物质在发光的同时也在发出X射线？他把一块铀盐（一种荧光矿物）放在用黑纸包好的底片上，放在太阳底下晒——底片果然感光了！

贝克勒尔以为自己猜对了。但接下来发生了意外：连续几天阴天，实验做不了，他把铀盐和底片一起锁进了抽屉。几天后他冲洗底片一看——**底片还是感光了**，而且比阳光下更清晰！

铀盐不需要阳光，不需要荧光，它在自发地发出某种射线。贝克勒尔意识到，他发现的不是荧光的副产品，而是一种全新的现象——**放射性**。`,
    core: `
贝克勒尔的发现引起了居里夫人的极大兴趣。她决定深入研究：到底是什么在发出射线？铀是唯一的放射源吗？

她系统测量了各种矿物的放射性，发现了一个奇怪的线索：天然沥青铀矿的放射性比纯铀强得多。如果放射性只来自铀，纯铀应该最强——但实际上矿石更强。唯一的解释：**矿石里还有别的放射性元素，而且比铀的放射性更强。**

这就是居里夫人开始提炼的起点。她在1898年发现了钋，同年又发现了镭——镭的放射性是铀的上百万倍。

**三种射线的发现**

贝克勒尔和居里夫人的发现引来了更多研究者。卢瑟福在1899年用磁场把射线分成三种：

- **α射线**：带正电，质量大，穿透力弱——一张纸就能挡住。后来证明是氦原子核（2个质子+2个中子）。
- **β射线**：带负电，质量小，穿透力中等——铝板可以挡住。后来证明是高速电子。
- **γ射线**：不带电，无静止质量，穿透力极强——需要厚铅板或混凝土才能挡住。它是高能电磁波，波长比X射线更短。

在磁场中，三种射线的偏转方向不同：α向一侧偏，β向另一侧偏（电荷相反），γ不偏（不带电）。这直接对应**高二物理·磁场对运动电荷的作用**——洛伦兹力使带电粒子在磁场中偏转，偏转方向由电荷正负决定。

**放射性的本质**

放射性的根源在于原子核的不稳定。某些原子核的质子和中子比例不合适，内部能量太高，会自发地"重组"——发射α或β粒子来调整，同时释放γ射线带走多余能量。

这不是化学反应——化学只涉及电子的重新排列，原子核不变；放射性改变的是原子核本身，是一种元素变成另一种元素。居里夫人和她的同时代人第一次证明：**元素不是永恒不变的**。`,
    principle: `
**1. 三种射线的性质**
α粒子是氦核，β粒子是电子，γ射线是电磁波。在磁场中偏转行为不同，是**高二·磁场**中带电粒子运动的经典案例。

**2. 放射性衰变**
不稳定核素自发衰变，遵循指数规律：

\$\$N = N_0 e^{-\\lambda t}\$\$

半衰期 \$T_{1/2} = \\frac{\\ln 2}{\\lambda}\$ 是衰变速率的量度。对应**高三·原子核**。`,
    thinking: `
**为什么重要？**
放射性的发现打开了原子核物理的大门。它证明了原子核不是不可分割的，元素可以相互转化——这打破了从古希腊以来的"元素永恒"观念。此后几十年，核物理学从零发展为一门精确科学，直接催生了核能和核武器。

**现代应用**
碳-14测年法利用放射性衰变的规律测定古代遗物的年代——考古学、地质学、气候科学都依赖它。医疗中的放射治疗和核医学成像也源于此。烟感报警器里装着微量的镅-241，利用α射线电离空气来检测烟雾。

**还有什么未解之谜？**
为什么有些原子核稳定，有些不稳定？质子和中子在核内的精确行为是什么？虽然量子色动力学描述了夸克和胶子的相互作用，但把夸克层面的理论推广到整个原子核的多体系统，计算上仍然极其困难。核力的"有效理论"虽然好用，但本质上是一种近似——真正的从第一性原理出发的核物理，至今仍是挑战。`,
  },
  'micro-003': {
    background: `
19世纪末，物理学家们对一种神秘现象着了迷：在抽成真空的玻璃管两端加上高压，管内会出现一道发光的射线——**阴极射线**。这道绿幽幽的光到底是什么？是波还是粒子？

两派吵了十几年。德国学派说它是波——因为它是直线传播的，像光。英国学派说它是粒子——因为它能被磁场偏转，带电的东西才偏转。这场争论不只是学术口角，它关乎一个根本问题：物质的最小单元到底是什么？如果阴极射线是比原子还小的粒子，那"原子不可分"的千年信条就要崩塌。

1897年，剑桥大学卡文迪许实验室的J.J.汤姆孙用一组精密实验一锤定音：阴极射线是带负电的粒子，而且它的质量比最小的原子还轻得多。

这个粒子后来被命名为**电子**——人类认识的第一个亚原子粒子。它的发现意味着：**原子不是不可分割的**，原子内部还有更小的东西。`,
    core: `
汤姆孙的实验分三步走：

**第一步：证明阴极射线带负电**

他在阴极射线管中加上电场，射线朝正极板偏转——说明它带负电。加上磁场，射线也偏转，方向和带负电的粒子一致。

**第二步：测量荷质比**

他同时加上电场和磁场，精心调节两者使得射线不偏转——电场力和磁场力恰好抵消：

\$\$eE = evB\$\$

由此得到粒子的速度 \$v = E/B\$。然后关掉电场，只留磁场，测量粒子在磁场中的偏转半径 \$r\$：

\$\$evB = m\\frac{v^2}{r}\$\$

联立两式，消去 \$v\$，得到荷质比：

\$\$\\frac{e}{m} = \\frac{E}{rB^2}\$\$

汤姆孙测出 \$e/m \\approx 1.76 \\times 10^{11}\$ C/kg——这个值比氢离子（质子）的荷质比大约1836倍。

**这意味着什么？**

两种可能：要么这个粒子的电荷比氢离子大1836倍，要么它的质量比氢离子小1836倍。

汤姆孙后来通过其他实验证明，这个粒子的电荷和氢离子差不多——所以它的质量一定非常小，只有氢原子的约1/1836。

**第三步：证明它是普遍存在的**

汤姆孙换用不同的金属材料做阴极，换用不同的气体填充管子——荷质比始终相同。这说明：**无论什么原子，里面都含有这种粒子**。它是所有原子的共同组成部分。

1897年4月30日，汤姆孙在皇家学会宣布了这个发现。他最初称它为"微粒"（corpuscle），后来采用了"电子"（electron）这个名字——这个词早在1891年就被爱尔兰物理学家斯通尼提出，用来表示电荷的基本单位。

电子的发现直接打破了"原子不可分"的教条——两千年来，从德谟克利特到道尔顿，所有人都以为原子是物质的最小砖块。汤姆孙告诉你：砖块还能再碎。`,
    principle: `
**1. 带电粒子在电磁场中的运动**
电场力 \$F = qE\$ 使粒子偏转，磁场力（洛伦兹力）\$F = qvB\$ 也使粒子偏转，两者方向不同。汤姆孙巧妙利用两个力的平衡来测量荷质比，这是**高二物理·带电粒子在磁场中的运动**的经典方法。这种"用电场和磁场互相抵消来测量粒子参数"的思路，后来成为粒子物理实验的基本功。

**2. 荷质比测量**
荷质比 \$e/m\$ 是带电粒子的基本参数。电子的荷质比约为 \$1.76 \\times 10^{11}\$ C/kg，质子的荷质比约为 \$9.58 \\times 10^{7}\$ C/kg——两者之比约1836，正是质子质量与电子质量之比。这个数字直接告诉你：电子比质子轻了将近两千倍。`,
    thinking: `
**为什么重要？**
电子的发现是人类第一次"看到"原子内部的东西。它开启了一个全新的研究领域——亚原子物理，直接催生了玻尔的原子模型、量子力学和整个现代电子学。没有对电子的理解，就没有晶体管、没有芯片、没有互联网——你正在用来读这段文字的设备，本质上是亿万电子在精确控制下的流动。

**现代应用**
阴极射线管（CRT）——老式电视机和显示器的核心——就是汤姆孙实验的直接后裔。今天的电子显微镜用电子束代替光线，分辨率达到原子级别。半导体工业中，每一个晶体管的运作都依赖于对电子行为的精确控制。而粒子加速器中的电子束，仍在帮我们探索更深层的微观世界。

**还有什么未解之谜？**
电子到底有多大？实验表明它的半径小于 \$10^{-18}\$ 米——在目前的精度下，它就是一个点，没有内部结构。但为什么电子有它特定的质量（\$9.109 \\times 10^{-31}\$ kg）？这个数字从何而来？标准模型无法解释粒子的质量为什么取这些值——它只能把质量作为输入参数。也许在更深层理论中，质量是可以计算的——但我们还没找到那套理论。`,
  },
  'micro-004': {
    background: `
1930年的物理学界面临一个尴尬的局面：他们知道原子核里有质子，但质子的数量对不上。

以碳原子为例，碳的原子量是12，按理说原子核里应该有12个质子。但碳的原子序数是6——也就是说，核外只有6个电子，核内只有6个正电荷。如果核里真有12个质子，正电荷就太多了，和电子数根本对不上。

一开始，物理学家们的解释是：原子核里除了质子，还有电子——质子贡献正电荷和大部分质量，电子中和掉多余的正电荷。但这套说法漏洞百出：如果核内有电子，按量子力学的不确定性原理，电子被束缚在这么小的空间里，动能应该极大，根本待不住。

一定有别的什么东西藏在原子核里。它贡献质量，但不带电——一个"隐形"的粒子。理论上容易想到，但实验上怎么抓？不带电的粒子不参与电磁相互作用，不偏转、不电离、几乎不留下任何痕迹——就像一个幽灵穿墙而过。

1932年，这个"幽灵"终于被詹姆斯·查德威克抓住了。`,
    core: `
**奇怪的"铍辐射"**

故事的起点是1930年，德国物理学家博特和贝克尔用α粒子轰击铍（Be）靶，发现铍释放出一种穿透力极强的射线。他们以为是高能γ射线（电磁波），因为这种射线不带电，在磁场中不偏转。

1932年初，法国的约里奥-居里夫妇（居里夫人的女儿和女婿）做了进一步实验。他们让这种"铍辐射"打在石蜡（富含氢）上，发现竟然打出了高速质子——能量高达5 MeV的质子！如果入射的是γ射线，那它得有多大的能量才能把质子撞飞？按康普顿散射的公式反推，这个γ光子的能量至少要50 MeV——这在当时看来几乎不可能。

约里奥-居里夫妇没有意识到自己错过了什么。他们继续把它当成γ射线来解释，只是说"γ射线的能量出乎意料地大"。

**查德威克的洞察**

查德威克看到约里奥-居里的论文时，立刻意识到：这不是γ射线。如果入射粒子的质量和质子差不多，那5 MeV的质子就完全解释得通——就像台球撞台球，动量和能量可以合理分配。一个质量接近质子但不带电的粒子，才能同时解释"穿透力强"和"能打出质子"两个事实。

他立刻动手实验。他用同样的"铍辐射"分别轰击氢（质子）和氮（质量约14），测量被撞出的反冲核的能量。如果入射的是γ光子，反冲核的能量应该很小；如果入射的是一个质量接近质子的粒子，反冲核的能量则大得多——而且对氢和氮的结果能同时吻合。

查德威克用动量守恒和能量守恒算了两组数据，反推出这个粒子的质量约为质子的1.001~1.01倍——几乎和质子一样重，但不带电。

这就是**中子**。

1932年2月，查德威克发表论文《中子的可能存在》。整个物理学界为之震动——困扰了十多年的"核内电子"问题，终于有了干净的解答：原子核里根本没有电子，而是质子和中子。质子提供正电荷，中子提供额外的质量，两者共同构成原子核。

查德威克因此获得1935年诺贝尔物理学奖。而约里奥-居里夫妇因为错过了中子，成了科学史上最著名的"擦肩而过"之一。`,
    principle: `
**1. 弹性碰撞与动量守恒**
查德威克分析反冲核能量的核心工具就是动量守恒和能量守恒。在弹性碰撞中，如果入射粒子质量与靶粒子质量接近，能量传递效率最高——这就是为什么中子打氢（质子）能转移大量能量，而γ光子（无静止质量）碰撞则效率极低。这是**高一物理·动量守恒**的经典应用。

\$\$m_1 v_1 = m_1 v_1' + m_2 v_2'\$\$

简单说就是：碰撞前后的总动量不变，谁重谁在碰撞后"吃住"更多的能量。

**2. 原子核的质子-中子模型**
原子核由质子和中子组成。质子数=原子序数Z（决定元素种类），中子数N决定同位素。核子总数A=Z+N叫质量数。碳-12有6个质子和6个中子，碳-14有6个质子和8个中子——化学性质相同，但核稳定性不同。这是**高三物理·原子核**的基础知识。

**3. 中子的电中性**
中子不带电，这意味着它不受库仑力的排斥，可以直接"闯入"任何原子核。质子则不行——两个质子靠近时会被强大的库仑斥力弹开，需要极高的能量才能克服。正是中子的这种"通行无阻"，使得后来的核物理实验发生了质的飞跃。`,
    thinking: `
**为什么重要？**
中子的发现补全了原子核模型的最后一块拼图。更关键的是，因为中子不带电，它可以不受电磁斥力的影响，直接射入任何原子核——这为后来的人工核反应和核裂变的发现打开了大门。毫不夸张地说，没有中子的发现，就没有核能时代。

**现代应用**
中子束是探测物质结构的独特工具。因为中子有磁矩且穿透力强，中子散射技术可以探测X射线看不到的信息——比如材料内部的应力分布、生物大分子中氢原子的位置。癌症治疗中的中子俘获疗法（BNCT），则是利用中子被肿瘤细胞中的硼-10俘获后释放的α粒子精确杀灭癌细胞。

**还有什么未解之谜？**
中子虽然稳定地待在原子核里，但一旦离开原子核，它会在约15分钟内衰变为一个质子、一个电子和一个反中微子——这就是中子的β衰变。为什么自由中子不稳定？为什么它的寿命是15分钟而不是其他值？更神秘的是，不同实验方法测出的中子寿命竟然相差约8秒——"中子寿命之谜"至今没有令人信服的解释，有物理学家怀疑可能存在一种未知的衰变通道。`,
  },
  'micro-005': {
    background: `
1934年，意大利物理学家恩里科·费米做了一个大胆的实验：用中子轰击铀。

中子刚被发现两年，费米敏锐地意识到：不带电的中子可以毫无阻碍地钻进铀原子核。他猜想，如果中子被铀核吸收，铀核的质量数会加1，变成一个更重的元素——一种自然界不存在的"超铀元素"。实验结果似乎印证了他的猜想：轰击后的产物确实表现出不同于铀的放射性。费米兴奋地宣布，他可能合成了超铀元素。

但问题来了：产物的化学性质谁也说不清楚。有好几位化学家试图分离和鉴定这些产物，结果混乱不堪——出现了好几种半衰期不同的放射性物质，有些像镭，有些像锕，有些什么都不像。费米坚持认为是超铀元素，但批评者说：你怎么证明？

这场争论持续了四年。直到1938年底，两个德国化学家给出了一个所有人都没想到的答案——而这个答案，改变了世界的命运。`,
    core: `
**哈恩的困惑**

奥托·哈恩是柏林凯撒·威廉化学研究所的放射化学家，他和助手弗里茨·斯特拉斯曼一直在用中子轰击铀，试图弄清费米实验的产物到底是什么。他们的策略很直接：用化学方法把产物一样一样分出来。

1938年12月，他们遇到了一个令人困惑的结果。在轰击铀的产物中，他们分离出了一种化学行为像钡（Ba）的放射性物质。钡的原子量是137左右，而铀的原子量是238——中间差了100多个质量单位。

在当时所有物理学家的大脑里，原子核是不可分割的。中子打上去，可能被吸收，可能被弹开，可能敲掉一两个小碎片（质子或α粒子）——但绝不可能把铀核劈成两半。那就像拿一颗小石子扔向一座山，山竟然从中间裂开了。

哈恩自己都不敢相信。他写信给流亡瑞典的长期合作者莉泽·迈特纳："我们的钡结果太让人震惊了……也许你能提出什么解释。"

**迈特纳和弗里施的解读**

迈特纳收到信时，正值圣诞节假期。她的外甥奥托·弗里施——也是一位物理学家——来瑞典看她。两人边散步边讨论哈恩的结果。

弗里施后来回忆，他们突然想到了玻尔的"液滴模型"：原子核像一滴液体，核子（质子和中子）在里面运动，表面张力维持着它的形状。如果核被扰动得够厉害——比如一个中子撞进来——它可能拉长、变细、最后一分为二，就像一滴水被拉成两滴。

迈特纳立刻在纸片上算了起来。铀-235吸收一个中子后变成铀-236，如果它分裂成钡-144和氪-89，两片碎片的总质量会比原来的铀核轻——差了约0.2个原子质量单位。按照爱因斯坦的质能方程：

\$\$E = \\Delta m \\cdot c^2\$\$

这0.2个质量单位对应约200 MeV的能量——这比任何已知的化学反应大了上亿倍！一小块铀释放的能量，足以烧开几吨水。

1939年1月，迈特纳和弗里施在英国《自然》杂志上发表论文，将这个过程命名为**核裂变**（fission）——借用生物学中细胞分裂的术语。

**链式反应**

裂变发现的消息像炸弹一样在物理学界炸开。几乎在同一时间，多国科学家意识到一个可怕的可能：裂变不仅释放能量，还会释放2~3个中子。这些中子如果再轰击其他铀核，就会引发更多裂变，释放更多中子——**链式反应**。

一个铀核裂变释放200 MeV，一克铀-235如果完全裂变，释放的能量相当于2.5吨煤。如果链式反应在一瞬间完成——那就是炸弹。

1939年，二战爆发。核裂变的发现立刻被列入军事机密。1942年，费米在芝加哥大学建成了第一座核反应堆，实现了可控链式反应。1945年，原子弹在广岛和长崎爆炸。从实验室里的偶然发现到改变世界的武器，只用了不到七年。`,
    principle: `
**1. 核裂变与质量亏损**
重核（如铀-235）被中子击中后分裂为两个中等质量的核，产物总质量小于母核质量，差值以能量形式释放。这是**高三物理·原子核**中核能的计算基础，质能方程 \$E=mc^2\$ 在这里是核心——哪怕只损失0.1%的质量，对应的能量也是化学能的数亿倍。

**2. 链式反应的条件**
裂变释放的中子需要维持"中子增殖系数"\$k \\geq 1\$才能持续反应：

\$\$k = \\frac{\\text{新一代中子数}}{\\text{上一代中子数}}\$\$

\$k\$ 取决于铀的纯度、数量（临界质量）和慢化剂（让中子减速以提高俘获概率的物质）。控制棒（如硼或镉）吸收多余中子，可以把 \$k\$ 调到刚好等于1——反应堆稳定运行。这是**高三·核能**的延伸内容。

**3. 玻尔液滴模型**
原子核像液滴，核子间有"表面张力"（核力）维持形状。中子打入后给核注入能量，核发生形变，当形变超过临界点，核力无法拉回，核就断裂。这个模型虽是半经典的，但直觉上非常好理解。`,
    thinking: `
**为什么重要？**
核裂变是人类第一次从原子核内部取出实用规模的能量。它同时带来了最好的和最坏的东西：核电站为数十亿人供电，核武器却能毁灭文明。这种双面性让物理学家们从此无法回避伦理问题——科学发现本身是中性的，但它的影响不是。

**现代应用**
核电站利用可控裂变发电，全球约10%的电力来自核能。医用同位素（如钼-99/锝-99m，用于核医学成像）也由反应堆生产。小型模块化反应堆（SMR）正在成为新一代核能技术，体积小、安全性高，有望替代化石燃料。

**还有什么未解之谜？**
核裂变的详细动力学至今没有被完全理解。一个铀核在裂变的瞬间到底经历了什么形状变化？量子效应在分裂过程中扮演什么角色？这些问题的答案不仅影响核物理基础研究，也关系到如何更安全、更高效地利用核能。而更根本的问题是：人类能否驾驭聚变——另一种更清洁、更强大的核能形式——来取代裂变？`,
  },
  'micro-006': {
    background: `
1905年，爱因斯坦发表了一篇看似疯狂的论文。

他提出：光不是连续的波，而是一份一份的能量包，每个能量包的能量与光的频率成正比：

\$\$E = h\\nu\$\$

其中 \$h\$ 是普朗克常数，\$\\nu\$ 是光的频率。这个公式今天看起来平平无奇，但在当时简直是异端。麦克斯韦方程组已经证明光是电磁波——整整50年的实验都支持波动说。你爱因斯坦凭什么说光是粒子？

更让人不爽的是，他用这个假说解释了一个让人头疼的实验结果——光电效应。当光照射金属表面，金属会弹出电子。但实验发现：无论光多强，只要频率不够高，一个电子也弹不出来；频率一旦够高，再弱的光也能瞬间弹出电子。波动说完全解释不了这个现象——如果光是波，强光应该总能把电子"摇"出来，跟频率无关才对。

爱因斯坦说：因为光是一颗颗粒子（光子），每颗光子的能量由频率决定。频率低，单颗光子能量不够，再多的光子也打不出电子；频率够高，一颗光子就能踢出一个电子，瞬间完成。

绝大多数物理学家不信。美国芝加哥大学的罗伯特·密立根尤其不信。他决定用最精密的实验把爱因斯坦证伪。`,
    core: `
**密立根的十年之役**

密立根是那个时代最精密的实验物理学家之一。他之前用油滴实验测量了电子电荷，精度惊人。现在他把目标对准光电效应——他要测量不同频率的光打出的电子的最大动能，看看它和频率之间到底是什么关系。

实验难度极高。金属表面的电子逃逸需要克服一个"门槛"——逸出功（也叫功函数），不同金属的逸出功不同。而且金属表面哪怕有一丁点氧化或污染，逸出功就会变化，数据全废。密立根设计了一种精密的真空装置，在真空中用刀片刮出新鲜的金属表面，立刻测量。

他用汞灯的不同谱线（频率从紫外到可见光都有）照射碱金属（钠、锂、钾），测量每种频率下打出的电子的最大动能。方法是在金属和收集极之间加一个反向电压（截止电压），逐渐增大直到电流为零——此时电场力刚好抵消电子的最大动能。

\$\$eU_c = E_{k\\text{max}} = h\\nu - W\$\$

其中 \$U_c\$ 是截止电压，\$W\$ 是逸出功。如果爱因斯坦是对的，\$E_{k\\text{max}}\$ 对 \$\\nu\$ 作图应该是一条直线，斜率就是普朗克常数 \$h\$。

1916年，密立根发表了结果。他画出了那条直线——它确实是直的，斜率确实等于 \$h\$。

**他自己都不想承认。**

密立根在论文里写道："尽管爱因斯坦的光电方程似乎精确地描述了实验结果，但这个方程所基于的半微粒理论目前看来是完全站不住脚的。"

他花了十年想推翻光量子假说，结果亲手验证了它。科学史上大概没有比这更讽刺的事了。

不过，密立根的诚实值得尊敬。他虽然不喜欢这个结论，但数据就是数据。他精确测量出的 \$h\$ 值与普朗克从黑体辐射中推导出的值一致，这成了光量子假说最有力的实验证据。

1921年，爱因斯坦因光电效应的理论解释获得诺贝尔物理学奖——不是相对论，是光电效应。1923年，密立根也因测量电子电荷和光电效应的精确研究获诺奖。`,
    principle: `
**1. 光电效应方程**
爱因斯坦的光电效应方程 \$E_{k\\text{max}} = h\\nu - W\$ 是**高三物理·光电效应**的核心公式。它说的是：光子的能量 \$h\\nu\$ 减去逃逸所需的逸出功 \$W\$，剩下的就是电子的最大动能。频率太低（\$h\\nu < W\$），再强也不行；频率够高，一个光子踢一个电子，干净利落。

**2. 截止频率与逸出功**
每种金属都有一个截止频率 \$\\nu_0 = W/h\$，低于这个频率，光再强也打不出电子。逸出功 \$W\$ 是金属材料的特性，一般约2~5 eV。这是**高三·光电效应**的基本概念。

**3. 光的波粒二象性**
光电效应证明了光的粒子性，但干涉和衍射实验又证明了光的波动性。光既是波又是粒子——这个看似矛盾的事实，后来被德布罗意推广到所有物质：电子也是波。波粒二象性是**高三·近代物理**的哲学核心。`,
    thinking: `
**为什么重要？**
光电效应不只是又一个实验，它迫使人类重新理解"光是什么"。两千年来的争论——光是波还是粒子——最终以一个匪夷所思的答案收场：都是。这个认识催生了量子力学，而量子力学又催生了晶体管、激光、芯片——你手机里的一切。

**现代应用**
光电效应的直接应用遍布现代生活：数码相机和手机摄像头里的CMOS传感器、太阳能电池板、夜视仪、光控开关——本质上都是光子把电子踢出来，信号被读取。没有光电效应，就没有数字影像。

**还有什么未解之谜？**
光子到底是什么？它在传播时表现为波，在被吸收或发射时表现为粒子——这两种行为之间如何过渡？波函数坍缩是否是一个真实的物理过程？这些问题直指量子力学最深层的基础。费曼说过，没人真正理解量子力学——也许正是因为我们还没理解光子。`,
  },
  'micro-007': {
    background: `
1916年，爱因斯坦在发表广义相对论一年后，从方程中推导出一个惊人的预言：加速运动的大质量物体会产生"时空的涟漪"——引力波。这些涟漪以光速向外传播，经过之处，空间会被微微拉伸和压缩。

爱因斯坦自己对这个预言的态度很矛盾。他先算出了引力波，后来又写了一篇论文声称引力波不存在——结果那篇论文有个错误，被审稿人指出来了。他撤回论文，重新计算，最后承认引力波确实存在。但他说，引力波的效应太微弱了，人类永远不可能探测到。

他这次说对了一半：引力波确实极其微弱。但"永远不可能探测到"——他低估了人类有多固执。

从1960年代起，几代物理学家投入了漫长而孤独的追逐。马里兰大学的约瑟夫·韦伯声称用大型铝棒探测到了引力波，但没人能重复他的结果——那些信号可能只是地震噪声。到了1990年代，一个更雄心勃勃的计划启动了：**LIGO**——激光干涉引力波天文台。它的目标是用激光测量4公里长的臂上不到一个质子直径千分之一的长度变化。

很多物理学家觉得这是在烧钱。反对者说：就算引力波存在，信号也太弱了，你不可能从地球的震动、车辆经过、甚至人群走动产生的噪声中把它提取出来。

LIGO的建设花了近20年，花费超过10亿美元。`,
    core: `
**LIGO的工作原理**

LIGO本质上是一个巨大的迈克尔逊干涉仪。两臂各长4公里，互相垂直。激光束从分光镜分成两路，分别沿两臂传播，到尽头的镜子反射回来，在分光镜处重新汇合。

没有引力波时，两束光走过的路程完全相同，汇合时干涉相消——光子探测器什么都看不到。当引力波经过，它会让一个臂微微伸长，另一个臂微微缩短（空间被拉伸和压缩），两束光的路程差了那么一点点——干涉图案就变了。

"一点点"是多少？LIGO的设计灵敏度是 \$10^{-18}\$ 米——不到一个质子直径的千分之一。要在4公里长的距离上测出这么小的变化，相当于测量地球到最近恒星（比邻星，4.24光年）的距离，误差不超过一根头发丝。

**从Initial LIGO到Advanced LIGO**

2002年到2010年，第一代LIGO（Initial LIGO）运行了8年，什么也没探测到。但这不是失败——它证明了技术路线可行，也帮助团队理解了噪声问题。

2015年，升级后的Advanced LIGO投入使用。灵敏度提高了3~4倍，探测体积扩大了约30倍。而且这次，团队用了巧妙的信号处理：根据广义相对论的精确计算，两个黑洞合并时发出的引力波具有特定的"啁啾"信号——频率和振幅同时递增，像鸟鸣一样。只要在噪声里找到这个"啁啾"，就找到了引力波。

**2015年9月14日的信号**

2015年9月14日，北京时间17:50:45，Advanced LIGO开始正式观测前5天（还在工程调试阶段），两个探测器——一个在华盛顿州，一个在路易斯安那州——几乎同时记录到了一个信号。

信号持续约0.2秒，频率从35Hz扫到250Hz，振幅从弱到强再突然消失——完全符合两个黑洞合并的"啁啾"特征。

数据分析团队花了几个星期反复验证，排除了地震、仪器故障、恶意注入等所有可能，最终确认：这是引力波信号GW150914。

它来自13亿光年外，两个黑洞——分别约36个和29个太阳质量——互相旋转、靠近、合并为一个约62个太阳质量的黑洞。差了3个太阳质量的能量以引力波的形式辐射出去，在那0.2秒内，这个系统的辐射功率比整个可观测宇宙中所有恒星光度的总和还强50倍。

2016年2月11日，LIGO团队宣布了这个发现。一百年前爱因斯坦的预言，终于被听到了。`,
    principle: `
**1. 引力波的本质**
广义相对论预言，物质加速运动时会产生时空的涟漪，以光速传播。引力波经过时，空间在一个方向被拉伸，在垂直方向被压缩——这是一种"潮汐力"效应。引力波的应变（空间相对变化量）\$h\$ 极其微小，LIGO探测到的GW150914信号，\$h\$ 约为 \$10^{-21}\$——这意味着4公里长的臂只变化了不到 \$4 \\times 10^{-18}\$ 米。这是**高中物理·近代物理**中广义相对论的延伸概念。

**2. 干涉测量原理**
LIGO的核心是光的干涉：两束相干光走不同路径后叠加，路程差变化一个波长，明暗条纹就移动一次。通过计数条纹移动量，可以精确测量长度变化。两束光的光程差 \$\\Delta L\$ 与干涉条纹的相位变化 \$\\Delta \\phi\$ 的关系为：

\$\$\\Delta \\phi = \\frac{2\\pi}{\\lambda} \\cdot \\Delta L\$\$

其中 \$\\lambda\$ 是激光波长。相位变化再小，只要超过测量精度，就能被捕捉到——LIGO的激光波长为1064纳米，测量精度远小于一个波长。这是**高二物理·光的干涉**的极致应用。

**3. 信号提取与匹配滤波**
在极强噪声中提取微弱信号，靠的是"匹配滤波"——用理论计算的模板去跟数据做关联，只有在模板和信号高度匹配时才会出现显著峰值。这种方法本质上是用"你知道要找什么"来对抗"你不知道噪声有多乱"。`,
    thinking: `
**为什么重要？**
引力波的探测为人类打开了认识宇宙的全新窗口。在此之前，我们只能"看"宇宙（电磁波）；现在我们可以"听"宇宙了。引力波不受星际尘埃遮挡，不与物质相互作用，它携带的是电磁波无法传递的信息——比如黑洞合并、中子星碰撞这类"黑暗事件"。天文学从此多了一只耳朵。

**现代应用**
引力波天文学正在快速发展：2017年，LIGO和Virgo探测到了双中子星合并的引力波，同时全球多台望远镜捕获了对应的电磁信号——多信使天文学诞生了。未来，空间引力波探测器（如LISA）将能在太空中组建数百万公里长的干涉臂，探测更低频的引力波，听到超大质量黑洞的"合唱"。

**还有什么未解之谜？**
引力波的速度是否严格等于光速？绝大多数物理学家认为是的，但2017年的一个测量给出了两者的速度差小于 \$10^{-15}\$ 的限制——极其接近，但严格相等尚未被证实。更深层的问题是：引力波是否也有"引力子"（引力的量子）？如果存在，它的质量必须严格为零——但为什么？这些问题的答案，可能藏在尚未建立的量子引力理论中。`,
  },
  'micro-008': {
    background: `
1964年，贝尔实验室的两位无线电工程师阿诺·彭齐亚斯和罗伯特·威尔逊遇到了一件烦心事。

他们正在使用一架喇叭形天线——原本是为接收卫星信号设计的——进行射电天文观测。不管怎么调试，天线里总有一种持续不断的噪声，像嘶嘶的静电声，怎么都消不掉。

他们试了所有能想到的办法：重新校准仪器、检查电缆、调整接收器。他们甚至发现天线里住了一群鸽子——鸽粪可能影响信号？他们爬进天线清理了粪便。噪声还在。

更奇怪的是，这个噪声不随时间变化，不随方向变化，不随季节变化。它从天空中每一个角落均匀地传来，强度始终一样。不管天线指向哪里，嘶嘶声都在。

彭齐亚斯和威尔逊一度以为是纽约市的干扰，但测了天线方向图后排除了。他们也考虑过大气层的辐射，但噪声在全天均匀分布，不像大气效应。

就这样，两个工程师被一种无法解释的噪声困扰了将近一年。他们完全不知道，自己正在听到的，是138亿年前宇宙大爆炸的回声。`,
    core: `
**大爆炸的预言**

在彭齐亚斯和威尔逊发现噪声之前，理论物理学家已经预言了这种辐射的存在。

1948年，乔治·伽莫夫和他的学生拉尔夫·阿尔弗（论文合作者还有汉斯·贝特，据说伽莫夫加上他的名字是为了凑出希腊字母α-β-γ的谐音）提出：宇宙起源于一次极端高温的"大爆炸"。在早期宇宙中，物质和辐射处于热平衡状态，温度极高。随着宇宙膨胀，辐射逐渐冷却，但应该仍然充满整个空间——只是温度已经降到了几开尔文。

阿尔弗和罗伯特·赫尔曼在1948年计算出，这种残余辐射的温度应该在5 K左右。但这个预言在当时的物理学界几乎没人关注——大爆炸理论还没有成为主流，稳态宇宙模型仍然有大量支持者。

1964年，普林斯顿大学的罗伯特·迪克重新独立推导出了类似的结论，并让他的团队开始建造天线来探测这种辐射。但他们还没来得及开始观测，贝尔实验室的电话就打过来了。

**真相大白**

彭齐亚斯偶然得知了迪克的工作，两方一交流，一切都对上了。

那无法消除的噪声，对应的热力学温度约为3.5 K（后来精确测量为2.725 K），恰好落在理论预言的范围内。它不是噪声，不是干扰，而是宇宙诞生时留下的"余温"——**宇宙微波背景辐射**（Cosmic Microwave Background，CMB）。

你可以这样理解：宇宙大爆炸后约38万年，温度终于降到了约3000 K，电子和质子结合成氢原子，光子不再被频繁散射，终于可以自由传播。这些光子从那一刻起就在宇宙中旅行，随着空间膨胀，波长被不断拉伸（红移），从可见光变成了微波——就像一根弹簧被拉长，波纹变得又宽又疏。今天这些光子的等效温度只有2.725 K，频率集中在微波波段。

这就是为什么你在老式电视没有信号时看到的雪花屏，约有1%来自宇宙微波背景辐射——你看到的是宇宙诞生的光。

彭齐亚斯和威尔逊因这一发现获得1978年诺贝尔物理学奖。而阿尔弗和赫尔曼——最早的理论预言者——几乎无人提及。

**COBE、WMAP、Planck的精密绘制**

CMB的发现只是开始。1992年，COBE卫星首次测量了CMB的微小温度涨落——不同方向上的温度差异只有十万分之一。这些涨落是宇宙早期密度不均匀的"种子"，今天的星系、星系团、大尺度结构，全都从这些微小的起伏中生长而来。

WMAP（2003年）和Planck（2013年）卫星进一步精确测量了CMB的温度涨落功率谱，由此确定了宇宙的年龄（138亿年）、组成（约5%普通物质、27%暗物质、68%暗能量）和几何形状（几乎完全平坦）。`,
    principle: `
**1. 黑体辐射**
CMB的频谱是近乎完美的黑体辐射谱——这是宇宙早期处于热平衡的直接证据。黑体辐射的峰值波长由维恩位移定律决定：

\$\$\\lambda_{\\text{max}} = \\frac{b}{T}\$\$

其中 \$b \\approx 2.898 \\times 10^{-3}\$ m·K。T=2.725 K时，\$\\lambda_{\\text{max}}\$ 约1.06毫米，在微波波段。这是**高二物理·热学**中热辐射概念的宇宙级应用。

**2. 宇宙膨胀与红移**
光子在膨胀的宇宙中传播，波长被拉伸（宇宙学红移），温度从3000 K降到了2.725 K——红移因子约为1100。红移的定义是：

\$\$z = \\frac{\\lambda_{\\text{观测}} - \\lambda_{\\text{发射}}}{\\lambda_{\\text{发射}}}\$\$

\$z \\approx 1100\$ 意味着光子的波长被拉长了1100倍——原来0.97微米的近红外光变成了1.06毫米的微波。这对应**高一物理·多普勒效应**的推广，从声波扩展到电磁波。

**3. 密度涨落与结构形成**
CMB中十万分之一的温度差异，对应早期宇宙中密度的微小不均匀。引力放大了这些不均匀——密度稍高的区域吸引更多物质，变得更高——最终形成了星系。这是**高一·万有引力**在宇宙学尺度上的壮观演绎。`,
    thinking: `
**为什么重要？**
宇宙微波背景辐射是大爆炸理论最强有力的证据。在那之前，宇宙有没有起源这个问题更像哲学思辨；在那之后，它变成了可以测量的科学。CMB让我们看到了宇宙38万岁时的"婴儿照"——从那张照片上，我们能读出宇宙的年龄、成分和命运。

**现代应用**
CMB的精确测量直接催生了精确宇宙学。Planck卫星的数据让宇宙学参数的精度从"量级估计"提升到了"百分之一"水平。这些数据也约束了暗物质和暗能量的性质，为粒子物理的实验提供了方向。而CMB偏振的精确测量，可能在未来探测到原初引力波——那将是宇宙暴胀的直接证据。

**还有什么未解之谜？**
宇宙为什么如此平坦？CMB显示宇宙的几何几乎完全平坦，这意味着早期宇宙的密度必须被"微调"到极高的精度——这就是"平坦性问题"，暴胀理论试图解释它，但暴胀本身的证据仍不充分。更深层的问题是：大爆炸之前是什么？CMB是我们能看到的最远的过去，在那之前的宇宙，目前只能靠理论猜测。`,
  },
  'myth-001': {
    background: `
公元前4世纪，亚里士多德断言：物体越重，下落越快。这个说法听起来太合理了——你同时扔下一块石头和一片树叶，石头肯定先着地，谁都能看到。两千年来，几乎没人质疑过。毕竟，亚里士多德是"百科全书式"的哲人，他的话在西方世界几乎等同于真理。中世纪的大学课堂上，教授们照本宣科，学生们埋头抄写，"重物先落"就这么一代代传了下来。直到16世纪末，一个25岁的意大利年轻人决定不再抄书，而是亲手做实验。他叫伽利略。`,
    core: `
伽利略首先用逻辑给亚里士多德挖了个坑：假如重物比轻物落得快，那把一个重球和一个轻球用绳子拴在一起会怎样？轻球拖慢重球，所以组合体应该落得比重球慢——可组合体明明比单个重球更重，按亚里士多德的说法又应该落得更快。自相矛盾。逻辑上的致命一击，但伽利略没有止步于此。他让铜球从不同倾角的斜面上滚下，用自己设计的"水钟"计时，发现不管球多重，只要斜面倾角相同，滚下的距离与时间的平方成正比。倾角越大，加速度越大——当倾角趋于90°，也就是自由落体时，所有物体的加速度完全一样。传说中伽利略在比萨斜塔上同时扔下一大一小两个铁球，它们同时落地。无论这个传说是否属实，1971年阿波罗15号的宇航员斯科特在月球表面同时松开一把锤子和一根猎鹰羽毛——在没有空气阻力的月球上，两者齐齐落地。画面传回地球的那一刻，亚里士多德两千年的权威终于彻底崩塌。`,
    principle: `
1. **自由落体加速度**：在忽略空气阻力的条件下，所有物体以相同加速度下落，这个加速度叫重力加速度，\$g \\approx 9.8 \\, \\text{m/s}^2\$——意思是每过一秒，下落速度增加约9.8 m/s，跟物体轻重毫无关系。（高一上学期·运动学）

2. **空气阻力才是"帮凶"**：石头先于树叶落地，不是因为石头更重，而是因为树叶受到的空气阻力相对于自身重力太大。在真空中，没有空气阻力，一切物体——铁球、羽毛、纸片——都一样快。

3. **牛顿第二定律的解释**：物体越重，引力越大，但同时惯性也越大，两者恰好抵消。力除以质量总是等于同一个g，这就是"轻重一样快"的根本原因。`,
    thinking: `
**为什么重要？**
打破"重物先落"的迷思，是人类第一次用实验事实推翻权威教条。它不仅仅是纠正了一个物理错误，更开创了"实验验证"的科学精神——从此，物理学不再是哲学家的思辨游戏，而是可以被检验、被推翻、被重建的实证科学。

**现代应用**
航天工程中，飞船和宇航员在轨道上一起做自由落体运动——他们看起来"漂浮"，其实和比萨斜塔的铁球一样，在以相同的加速度下落。国际空间站里的物体之所以"失重"，正是自由落体原理的体现。

**还有什么未解之谜？**
引力为什么能让所有物体以相同加速度下落？这个"等效原理"是爱因斯坦广义相对论的基石，但物理学家至今仍在用越来越精密的实验检验它——如果有一天发现等效原理有极微小的偏差，那将是一场新的物理学革命。`,
  },
  'myth-002': {
    background: `
冬天结冰的路面有多难走？每个人都经历过：脚底一滑，整个人像被谁从身后拽了一把，身体往前冲，脚却往后溜。你以为冰面的问题在于"太滑了"，但更准确的说法是——摩擦力太小了。物理课本上写"摩擦力阻碍物体的相对运动或相对运动趋势"，这句话被很多人记成了"摩擦力总是坏事"。但仔细想想：你走路的时候，脚往后蹬，地面往前推你——那个推力，恰恰就是静摩擦力。如果地面真的完全光滑，你连一步都迈不出去。摩擦力不是总在拖后腿，它有时候是你唯一的动力来源。`,
    core: `
让我们重新审视摩擦力的真面目。摩擦力分为两种：**静摩擦力**和**滑动摩擦力**。滑动摩擦力确实总是和运动方向相反——你推箱子在地上滑，地面确实在"拖后腿"。但静摩擦力完全不是这么回事。你走路时，脚掌往后蹬地，脚底相对地面有向后滑动的趋势，地面就给脚一个向前的静摩擦力——正是这个力推着你前进。汽车能加速，靠的也是轮胎和地面之间的静摩擦力。如果路面结冰，静摩擦力急剧减小，轮胎打滑，发动机转得再快车也走不了。再看一个更反直觉的例子：传送带上的包裹被往上运，包裹并没有在传送带上滑动，它跟着传送带一起动，靠的也是静摩擦力——此时静摩擦力的方向和运动方向完全一致。甚至你用手指捏住一支笔，笔不会掉，也是静摩擦力在起作用。说摩擦力"总是阻碍运动"，就像说空气"总是让人窒息"一样片面——忽略了你每时每刻都在呼吸它。`,
    principle: `
1. **静摩擦力方向由相对运动趋势决定**：静摩擦力的方向总是与"接触面间相对运动趋势"相反，而不是与物体运动方向相反。你往前走，脚相对地面想往后滑，静摩擦力就往前——和你的运动方向一致。（高一下学期·力学）

2. **滑动摩擦力方向由相对运动决定**：物体已经在接触面上滑动时，摩擦力才与滑动方向相反。注意是"接触面上的相对运动方向"，不是"物体对地的运动方向"。

3. **没有摩擦力的世界**：如果没有摩擦力，你无法行走、汽车无法刹车、螺丝无法拧紧、绳子无法打结——整个机械文明将不复存在。\$f \\leq \\mu N\$——静摩擦力有一个最大值，等于摩擦系数乘以法向力，走路不滑的条件就是蹬地力不超过这个上限。`,
    thinking: `
**为什么重要？**
正确理解摩擦力的方向，是学好力学的门槛题。很多同学在受力分析时一看到"摩擦力"就画反方向，导致整道题全错。理解静摩擦力可以和运动方向一致，是突破力学思维定式的关键一步。

**现代应用**
磁悬浮列车利用电磁力将车身悬浮，消除了车轮与轨道的滑动摩擦，大幅降低了运行阻力。但列车加速和制动仍然需要牵引力和制动力——这些力靠的是直线电机的电磁推力，本质上是在寻找摩擦力的"替代方案"。

**还有什么未解之谜？**
摩擦力的微观本质至今没有完全搞清楚。两个看起来光滑的表面在原子尺度上仍然是粗糙的，真正的接触面积远小于表观面积。接触点上的原子如何相互作用、如何产生阻力？这涉及量子力学和材料科学的交叉领域，至今仍是研究热点。`,
  },
  'myth-003': {
    background: `
打开任何一段国际空间站的视频，你都能看到宇航员像鱼一样在舱内飘来飘去，水滴悬浮在空中，一本翻开的书静静漂浮。宇航员头发竖起，睡觉不用床铺——随便飘着就行。很多人脱口而出的解释是："太空中没有重力。"甚至一些科普节目也这么说，NASA自己也用"microgravity"（微重力）这个词来描述空间站环境，更让人觉得太空和重力不沾边。

听起来很合理——既然地球上的东西往下掉是因为重力，那太空中的人不往下掉，不就说明没有重力了吗？

问题在于，国际空间站飞在距地面约400公里的轨道上，而地球的引力场在400公里高度只减弱了大约10%。如果你能站在一座同样高度但静止不动的塔顶上，你的体重只会比在地面上轻大约10%——依然稳稳地站在地板上，绝不会飘起来。

那他们为什么不掉下来？答案既简单又反直觉：他们一直在掉，只是永远掉不到地面上。`,
    core: `
要理解这个看似矛盾的现象，不妨先想象一个思想实验。

你站在一座极高的大楼顶上，水平扔出一块石头。石头会沿一条弧线下落，最终落地。你加大力气再扔一次，石头飞得更远，弧线更弯，但最终还是落回地面。

现在，假设你的力气足够大——石头飞出去的速度达到每秒7.66公里（即第一宇宙速度），此时石头下落的弧线刚好与地球的弧度吻合。石头一直在"往下掉"，但地球的表面也在"往下弯"，两者完美同步——石头永远不会碰到地面。

这就是轨道运动的本质。国际空间站正是在做这件事：它以约7.66 km/s的速度绕地球飞行，每时每刻都在被重力拉向地球，同时因为水平速度太快，飞出的弧线始终贴着地球的曲率。空间站里的宇航员、水滴、书本——一切物体和空间站一起，以相同的加速度做自由落体运动。既然没有相对加速度，它们之间就彼此"漂浮"——这不是"没有重力"，而是"一切都在一起自由落体"。

\$\$g = \\frac{GM}{r^2} \\approx 8.7 \\, \\text{m/s}^2\$\$

这是400公里高度的重力加速度，大约是地面的89%——重力依然很强，只是被自由落体"隐藏"了。

我们可以做一个直观的计算：地球半径约6371公里，国际空间站轨道半径约6771公里。地球表面到地心的距离如果是100份，空间站到地心约106份——引力减弱的比例是 \$(100/106)^2 \\approx 0.89\$，也就是只少了11%。空间站每天绕地球飞行大约16圈，每圈约90分钟。在这90分钟里，空间站水平方向飞了约41000公里，同时被重力"拉"向地球——但它飞得太快了，地面的弯曲刚好"让开"了这41000公里对应的弧度。地球表面在同样的时间内也弯曲了同样的弧度，所以空间站始终和地面保持400公里的距离。

再想一层：如果太空中真的没有重力，那月球为什么绕地球转？行星为什么绕太阳转？整个太阳系、银河系的旋转结构，全是引力在撑场。说"太空中没有重力"，等于否认了天体力学最基本的事实。`,
    principle: `
**1. 自由落体与失重**

当所有物体以相同加速度下落时，物体之间没有相对运动，这就是"失重"状态。失重 ≠ 没有重力，它只是重力的效果被同加速度运动"抵消"了。你可以这样理解：你站在电梯里，电梯缆绳突然断了——你和电梯一起自由下落，你会感觉自己"漂浮"在电梯中，脚下的体重秤显示为零。国际空间站就是这个不断"下落"的电梯，只不过它永远落不到地上。（高一下学期·曲线运动与万有引力）

**2. 轨道速度与重力平衡**

做圆周运动的物体需要向心力，而在近地轨道上，地球引力恰好充当了向心力。

\$\$F_g = \\frac{GMm}{r^2} = \\frac{mv^2}{r}\$\$

引力等于向心力，这就是轨道运动成立的条件。从这个等式可以推出轨道速度 \$v = \\sqrt{GM/r}\$——轨道越高，速度越慢，但引力也越弱，两者始终保持着精确的平衡。如果空间站的发动机突然熄火（它本来就是靠惯性飞的），它不会"飘走"，也不会"掉下来"——它会继续沿着原来的轨道飞下去。

**3. 引力的作用范围**

牛顿万有引力定律表明，引力与距离的平方成反比，但永远不会减小到零。无论你飞多远，地球的引力都在——只是越来越弱。宇宙中没有真正"没有重力"的地方，即使是在星系之间的空洞中，远处的星系引力仍然存在。离地球最近的"几乎无重力"环境，可能在拉格朗日点——那里多个天体的引力刚好相互抵消，但"抵消"和"没有"是两回事。`,
    thinking: `
**为什么重要？**
"太空没有重力"是一个广泛流传的误区，纠正它不仅是物理知识的纠偏，更是对"力"和"运动"关系的深层理解。力和加速度不是一回事——重力一直在，只是你感受不到，因为周围一切都在和你一起加速。

**现代应用**
微重力环境为材料科学和生物医学提供了地面无法实现的实验条件。蛋白质结晶在微重力下更纯净，合金凝固更均匀，骨骼细胞在微重力下表现出类似骨质疏松的变化——这些研究直接推动了新药开发和太空医学的发展。

**还有什么未解之谜？**
在比国际空间站更远的深空中，宇航员将长期处于微重力环境。几十年来的研究已经发现，微重力对人体的影响远比想象中复杂：骨密度每月流失约1%~2%（相当于地球上十年老化的速度）、眼球形状会改变导致视力下降、脊椎拉长让人"长高"5厘米、甚至脑脊液的分布变化会影响认知能力。目前国际空间站上配备了两台跑步机和一台阻力训练器，宇航员每天必须锻炼两小时，也仅仅能减缓而非阻止这些退化。如何为火星任务（单程6~9个月）或更远的星际旅行设计有效的人体保护方案？旋转飞船产生离心力模拟重力是一个方案——但旋转带来的科里奥利力会导致眩晕和运动失调，多大的旋转半径和角速度才合适？至今没有公认的答案。在太空里真正"制造重力"，仍是工程学上一道悬而未决的难题。`,
  },
  'myth-004': {
    background: `
"闪电不会击中同一个地方两次"，这句俗话你可能从小听到大。它的逻辑似乎很自然：闪电是随机的事件，第一次已经放过电了，同样的路径不会再被选中——就像买彩票不可能连续中两次一样。但大自然显然没读过人类的俗语。纽约帝国大厦的塔尖每年大约被闪电击中25次，有时候一场雷暴中就被击中好几次。2011年的一项研究追踪了法国一处通信塔，发现它在一次暴风雨中被闪电击中了8次，间隔最短只有几秒钟。闪电不但会击中同一地点两次，而且专门挑"好击"的地方反复劈。`,
    core: `
为什么闪电爱"吃回头草"？这要从闪电的形成说起。雷暴云中，强烈的上升气流把小水滴推到云的上部，大水滴留在下部。上下碰撞摩擦，导致云的上部带正电、下部带负电。当云底和地面之间的电场强度超过空气的击穿阈值（约300万伏/米），空气从绝缘体瞬间变成导体，一条电离通道——叫"先导"——从云底向下延伸。先导像一棵倒长的树，分叉出很多枝杈，试探着寻找阻力最小的路径。当某条先导接近地面时，地面突出的物体——高塔、大树、山丘——会向上发出"迎面先导"，两者相遇的瞬间，一道明亮的闪电劈下。重点来了：闪电选择路径靠的是电阻最小原则，而高耸的尖端物体电阻最低。帝国大厦的塔尖就是这样一个"天然避雷针"——它的存在让周围的电场集中，先导每次都优先和它对接。换句话说，不是闪电"随机选了一个地方"，而是这个地点的物理条件让它每次都成为最优选择。同一个人在同一个地方被闪电击中两次的概率极低，但同一个地点被击中多次——在大自然看来，那简直太正常了。`,
    principle: `
1. **空气击穿**：干燥空气本是绝缘体，但当电场强度超过约 \$3 \\times 10^6 \\, \\text{V/m}\$ 时，空气分子被电离，变成导体，闪电通道就沿着这条导电路径形成——就像河水找到了最低的缺口冲出去。（高二上学期·静电场）

2. **尖端放电效应**：带电体尖端的电场最强，最容易引发放电。避雷针就是利用尖端放电，主动引导闪电沿金属棒导入地下，保护建筑物。

3. **先导-回击机制**：一次闪电通常包含多次"回击"——先导打通通道后，强大的电流从地面冲回云层，亮度极高；之后先导可以再次沿同一条通道下行，引发第二次回击。你看到的一"闪"往往包含3~5次回击，间隔仅几十毫秒。`,
    thinking: `
**为什么重要？**
"闪电不会击中两次"这个迷思可能导致致命的误判——如果在第一次雷击后你认为"安全了"而留在原地，第二次可能就找上你。了解闪电的真实行为，是户外安全常识的基础。

**现代应用**
现代避雷针系统不只是一根铁棒，而是结合了提前放电装置和接地网络，能在闪电先导接近时主动"发射"迎面先导，将雷击引导到安全路径。高层建筑、风力发电机和输电铁塔都依赖这套系统每年承受数十次雷击而安然无恙。

**还有什么未解之谜？**
闪电的触发机制至今仍有争议。云内的电荷分离过程大致清楚，但到底是什么"点燃"了那条最初的先导？有人猜测是宇宙射线撞入大气产生的高能粒子提供了初始电离通道，但这个假说尚未被完全证实。闪电最神秘的部分，恰恰发生在最开始的几微秒。`,
  },
  'myth-005': {
    background: `
几乎每一部太空电影都有这样的镜头：飞船爆炸，火球翻滚，同时伴随着震耳欲聋的轰鸣声。观众看得热血沸腾，谁也不会觉得有什么不对。可如果你真的漂浮在太空中目睹一场爆炸，你什么也听不到——没有火声，没有冲击波的嘶鸣，一片死寂。1979年的电影《异形》用一句著名海报语点破了真相："In space, no one can hear you scream." 太空中没人能听到你尖叫。这不是科幻设定，而是物理学事实。声音需要介质，真空里没有介质，所以声音无法传播。然而，这个看似简单的道理，却有着比想象更丰富的内涵。`,
    core: `
声音是什么？它是机械波——物质振动的传播。鼓面振动，推动面前的空气分子，空气分子再推动更远处的空气分子，一环扣一环，振动就这样传了出去。关键在于：每一个环节都需要有"东西"在振动。空气可以，水可以，钢铁也可以，但真空里什么都没有——没有分子可以推搡，没有粒子可以碰撞，振动无"路"可走，声波自然就断了。这不只是理论推演，而是可以亲手验证的。把一个闹钟放进玻璃罩里，罩子里的空气没抽走时你能听到铃声；用真空泵逐渐抽走空气，铃声越来越弱，最终几乎消失——但隔着玻璃你仍然能看到闹铃在振动。振动还在，声音却没了。这就证明了声音的传播依赖于介质。那为什么很多人以为真空中也有声音？除了电影的误导，还有另一个原因：光可以在真空中传播，于是人们下意识觉得"波都能在真空中走"。但光波是电磁波，不需要介质，靠的是电场和磁场的交替变化自我传播；声波是机械波，本质完全不同。把两种波混为一谈，是这则迷思最深的根源。`,
    principle: `
1. **机械波的传播条件**：声波是机械纵波，介质中的粒子沿波传播方向振动，通过碰撞传递能量。没有粒子，就没有碰撞，声波就无法前进——就像多米诺骨牌抽掉了中间的牌，后面不会倒。（高一上学期·机械波）

2. **声速与介质的关系**：声音在不同介质中速度不同，\$v_{\\text{空气}} \\approx 340 \\, \\text{m/s}\$，\$v_{\\text{水}} \\approx 1500 \\, \\text{m/s}\$，\$v_{\\text{钢铁}} \\approx 5000 \\, \\text{m/s}\$——介质越密实、分子间作用力越强，声速越快。真空中密度为零，声速也为零。

3. **电磁波与机械波的本质区别**：电磁波（光、无线电、X射线）靠电场和磁场交替激发传播，不需要介质；机械波（声波、地震波、水波）靠介质粒子的相互作用传播，必须有介质。两者都叫"波"，但传播机制完全不同。`,
    thinking: `
**为什么重要？**
区分机械波和电磁波，是理解波动物理的第一步。混淆两者不仅会导致"真空中能传声"的误区，还会影响对雷达、通信、声呐等技术原理的理解。知道什么需要介质、什么不需要，是科学素养的基本功。

**现代应用**
虽然真空中不能传声，但宇航员之间并不沉默——他们用无线电波通话，而无线电波作为电磁波可以在真空中畅通无阻。太空通信、深空探测器的数据回传，全部依赖电磁波穿越数亿公里的真空。

**还有什么未解之谜？**
声波在极端介质中的行为仍然充满挑战。科学家正在研究声波在中子星的超密物质中如何传播——那里的密度远超钢铁，声速可能接近光速的几分之一。极端条件下的"声音"会是什么样子？这不仅是物理谜题，更可能揭示物质在极限状态下的深层结构。`,
  },
  'origin-001': {
    background: `
1590年的比萨，空气里弥漫着文艺复兴的躁动。那时候的欧洲大学，教授们还在照着亚里士多德的书念课——"物体越重，落得越快"，没人觉得有什么问题。毕竟，这位古希腊哲人已经统治了人类近两千年的认知。

但有个不守规矩的数学教授，偏偏爱问"凭什么"。

他叫伽利略·伽利莱，当时才二十多岁，在比萨大学教书。他不像其他学者那样只翻故纸堆，他喜欢动手——造望远镜、造天平、造各种稀奇古怪的装置。同事们觉得他是个麻烦，学生倒是爱听他的课，因为他总在课堂上质疑那些"人人都知道"的常识。

有一天，他盯着从屋檐滴落的水珠出了神：水珠落下时，是不是一直在加速？如果物体真的"越重落得越快"，那一滴水和大石头应该完全不同——但直觉告诉他，事情没那么简单。`,
    core: `
伽利略想测量物体下落的速度变化，但有个现实难题：自由落体太快了，1590年根本没有能精确计时的工具。

于是他做了一个精妙的操作：**把"竖直下落"变成"沿斜面滚下"**。

他找来一块长约5米的木板，刻出一道光滑的凹槽，把一端垫高，让铜球沿着凹槽滚落。坡度越缓，球滚得越慢，他就有足够的时间来记录位置。

那他怎么计时呢？没有秒表，他就用自己的脉搏——后来又改进为让水流过细管，称量流出的水的重量来计算时间。这种"水钟"在当时已经算是精密仪器了。

他反复实验，记录铜球在不同时间内滚过的距离。结果让他兴奋不已：

- 铜球在**相等的时间间隔**内，走过的距离**越来越大**
- 如果第1秒走了1个单位，第2秒就走了3个单位，第3秒走了5个单位
- 总距离的比是 \$1 : 4 : 9\$——**距离与时间的平方成正比**

这就是说，铜球在做**匀变速运动**。它每秒钟增加的速度是一样的，加速度恒定不变。

更妙的是，当他把斜面垫得更高，铜球滚得更快，但那个"距离与时间平方成正比"的关系始终成立——只是比例系数变大了。他由此推断：如果斜面变成90°，也就是竖直自由落体，这个规律依然成立，只是我们来不及测量罢了。

就这样，**一个斜面实验，推翻了亚里士多德两千年的错误，建立了匀变速运动的规律**。`,
    principle: `
这个故事涉及两个核心概念：

**1. 匀变速直线运动**
物体沿直线运动，加速度大小和方向都不变。在伽利略的斜面实验中，铜球的加速度 \$a\$ 恒定，满足：

\$\$s = \\frac{1}{2}at^2\$\$

即位移与时间的平方成正比。这就是高中物理里第一个运动学公式——距离随时间的平方增长，意味着速度在均匀增加。

**2. 实验方法的智慧——"冲淡重力"**
伽利略不是直接测自由落体，而是用斜面"放慢"运动，让不可测量变成可测量。这种方法后来被称为"冲淡重力"法，是物理实验设计的经典思路：**当直接观测不可能时，找一个等效但可观测的替代方案**。

这些内容对应**高一上学期·运动学**，是整个高中物理的起点。`,
    thinking: `
**为什么重要？**
伽利略的斜面实验不只是发现了一个公式，它开创了一种全新的认识世界的方式——**用实验检验理论**。在他之前，人们相信权威；在他之后，人们相信证据。这是科学革命的起点，难怪爱因斯坦称他为"现代科学之父"。

**现代应用**
今天每一个物理实验室里，你都能看到气垫导轨——那就是伽利略斜面实验的现代版。而"冲淡重力"的思路更是无处不在：研究自由落体太危险？用降落伞减速；观测粒子衰变太快？用高速摄影机慢放。

**还有什么未解之谜？**
伽利略证明了匀变速运动的规律，但物体为什么会有惯性？为什么不受力的物体会保持匀速或静止？这个问题要等到牛顿来回答——而牛顿的回答，又引出了更深的谜题：惯性是空间的性质，还是时空本身的性质？至今，物理学家仍在探索。`,
  },
  'origin-002': {
    background: `
1665年的英格兰，瘟疫横行。剑桥大学关了门，23岁的牛顿回到了老家沃尔索普庄园。在旁人眼里，这是一个被迫停学的年轻人；但历史证明，那一年半的"隔离"，成了人类科学史上最惊人的创造力爆发期。

某个傍晚——也许是真的，也许是后人编的——牛顿坐在苹果树下，一颗苹果砸在了他的头上（或者只是落在了他眼前）。大多数人会抱怨一句"真倒霉"，但牛顿盯着那颗苹果问了一个荒唐的问题：**苹果会落地，月亮为什么不落地？**

这个问题看似简单，却要用到人类最深刻的洞察才能回答。因为答案是：月亮其实也在"落地"——它一直在向地球坠落，只是它同时跑得太快，永远坠不到地面上。`,
    core: `
牛顿的推理是这样的：想象你在山顶水平扔出一块石头。速度小，石头很快就落地；速度大一点，石头飞得更远才落地。如果速度足够大呢？石头会绕着地球转一圈，回到你手里——它变成了一个"小月亮"。

这意味着，**让苹果落地的力和让月亮绕地球转的力，是同一个力**。

牛顿大胆假设：宇宙中任意两个物体之间都存在引力，这个力的大小与两个物体质量的乘积成正比，与它们之间距离的平方成反比：

\$\$F = G\\frac{m_1 m_2}{r^2}\$\$

其中 \$G\$ 是引力常数，\$m_1\$ 和 \$m_2\$ 是两个物体的质量，\$r\$ 是它们之间的距离。

但假设归假设，牛顿需要验证。他做了如下计算：

- 已知地球表面的重力加速度 \$g \\approx 9.8 \\, \\text{m/s}^2\$
- 月球到地心的距离约为地球半径的60倍
- 如果引力与距离平方成反比，月球感受到的引力应该是地表引力的三千六百分之一

他算出月球绕地球的向心加速度，果然大约是地表重力加速度的三千六百分之一。**天上的运动和地上的运动，被一个公式统一了。**

这个发现震撼了整个科学界。在此之前，人们认为天上和地下遵循不同的规律；牛顿告诉世界——**物理定律是普适的**，从苹果到行星，没有例外。`,
    principle: `
**1. 万有引力定律**
任何两个有质量的物体之间都有引力，方向沿连线指向对方，大小由上述公式决定。这是高中物理**高一下学期·万有引力**的核心内容。

**2. 天体运动的统一解释**
月球绕地球做匀速圆周运动，所需的向心力正是万有引力提供的。由此可以算出月球的轨道速度和周期——"天上"的轨道运动和"地上"的落体运动被统一在同一条定律下，这是物理学史上第一次大统一。`,
    thinking: `
**为什么重要？**
万有引力定律是人类第一次用数学精确描述宇宙的运行规则。它证明了：无论苹果还是行星，都服从同一条自然法则。这种"统一"的思想，成了此后三百年物理学的核心追求。

**现代应用**
今天的卫星轨道计算、GPS定位、航天器变轨，全部基于万有引力定律。每一次火箭发射，都是在和这个公式打交道。2020年中国北斗导航系统全面建成，背后也是牛顿三百多年前写下的那个方程。

**还有什么未解之谜？**
牛顿自己承认，他不知道引力为什么存在——他只描述了引力怎么运作。引力到底是怎样跨越空间起作用的？这个疑问催生了爱因斯坦的广义相对论：引力不是力，而是时空的弯曲。但即便如此，引力的量子本质至今仍是物理学最大的未解之谜之一。`,
  },
  'origin-003': {
    background: `
公元前3世纪的叙拉古（今天的西西里岛），国王赫伦二世遇到了一个棘手的问题：他刚定做了一顶纯金皇冠，但总怀疑工匠偷偷掺了银子。怎么验证？皇冠不能熔化——那是国王的宝贝，也不能切割——那还叫皇冠吗？

国王把这个难题甩给了王国里最聪明的人：阿基米德。

阿基米德是那个时代最伟大的数学家和工程师，发明过各种精巧的机械。但皇冠问题让他犯了难：要判断是否掺假，就得测出皇冠的密度（纯金密度19.3 g/cm³，银只有10.5 g/cm³），可皇冠形状不规则，没法直接算体积。

传说他苦思冥想了很久，直到有一天去公共浴场洗澡。他跨进浴盆，水漫了出来，他突然愣住了——溢出的水和他的身体之间，一定有什么关系。传说他兴奋得衣服都忘了穿，光着身子跑上街头大喊："Eureka！Eureka！"（希腊语：我找到了！）`,
    core: `
阿基米德到底"找到"了什么？

他找到了一种间接测量不规则物体体积的方法：把皇冠浸入水中，溢出的水的体积就等于皇冠的体积。有了体积，再除以皇冠的质量，就能算出密度——如果密度低于纯金，说明掺了假。

但更深层的是，他从这个具体问题中提炼出了一个普遍规律：**浸在流体中的物体受到向上的浮力，浮力大小等于物体排开的流体的重量**。

这就是阿基米德原理：

\$\$F_{\\text{浮}} = \\rho_{\\text{液}} g V_{\\text{排}}\$\$

浮力只取决于液体的密度和排开液体的体积，跟物体本身是什么材料、多重、什么形状无关。一块铁和一块同样体积的木头，浸入水中时受到的浮力完全相同——只是铁比浮力重，所以沉下去；木头比浮力轻，所以浮起来。

为什么会有浮力？想象一个立方体浸在水中，上面受到水的向下压力，下面受到水的向上压力。越深的地方水压越大，所以向上的压力大于向下的压力，差值就是浮力。本质上，浮力是流体内部压强随深度增加的必然结果。

阿基米德还进一步发现了物体的浮沉条件：
- 物体密度小于液体 → 浮
- 物体密度大于液体 → 沉
- 物体密度等于液体 → 悬浮

这就是为什么钢铁做的船能浮起来——虽然钢的密度比水大，但船的形状让它排开了大量水，浮力足以支撑船重。`,
    principle: `
**1. 阿基米德原理**
浸在流体中的物体受到的浮力等于排开流体的重力。这是**高一物理·液体压强与浮力**的核心定律。

**2. 浮沉条件**
物体浮沉取决于物体密度与液体密度的比较。轮船、潜水艇、热气球的原理都可以用这一条解释。对应**高一物理**中浮力综合应用。`,
    thinking: `
**为什么重要？**
阿基米德原理是人类最早定量描述的物理定律之一，也是流体静力学的基石。从船的浮沉到大气中气球的升空，从液压机到石油管道的浮子流量计，浮力无处不在。更重要的是，阿基米德展现了一种科学方法：从一个实际问题出发，提炼出普遍规律。

**现代应用**
潜水艇通过调节水箱中的水量改变自身密度，实现上浮和下潜。密度计直接利用浮力与密度的关系读数。在航天领域，虽然太空中没有"水"来提供浮力，但阿基米德原理在微重力流体管理中仍然重要——空间站里的液体行为比地球上复杂得多。

**还有什么未解之谜？**
阿基米德原理适用于静止流体，但在湍流、气泡流、超临界流体等复杂情况下，浮力的计算远没有那么简单。尤其是流体与固体边界处的微观行为——比如纳米颗粒在液体中的"浮力"是否还遵循经典公式——这是当今软物质物理的前沿问题。`,
  },
  'origin-004': {
    background: `
1583年，19岁的伽利略坐在比萨大教堂里，心不在焉地盯着头顶的吊灯。风从门缝吹进来，吊灯开始摇摆——轻轻的，慢悠悠的。他注意到一件事：无论摆幅大小，吊灯来回一次花的时间似乎差不多。

他用脉搏默默计数（对，又是脉搏，那个年代没有秒表），发现果然如此：摆幅大的时候摆得快，摆幅小的时候摆得慢，但完成一次完整来回所需的时间几乎相同。这就是**摆的等时性**。

但伽利略只是发现了这个现象，并没有把它变成实用的东西。直到半个多世纪后的1656年，荷兰物理学家克里斯蒂安·惠更斯才把这个发现变成了现实——他造出了人类第一座摆钟。`,
    core: `
惠更斯面临的核心问题是：怎么让摆持续摆动，又怎么把摆动转化成钟表的指针转动？

伽利略的发现告诉他，单摆的周期只取决于摆长，和摆幅无关（小角度下近似成立）。周期公式为：

\$\$T = 2\\pi\\sqrt{\\frac{L}{g}}\$\$

其中 \$T\$ 是周期，\$L\$ 是摆长，\$g\$ 是重力加速度。摆长1米的单摆，周期大约2秒——秒摆就是这么来的。

但这个公式有个前提：摆角必须很小（一般小于5°）。角度一大，周期就会变长，等时性就不成立了。这就意味着，普通摆钟走久了会越来越不准——因为摩擦让摆幅越来越小，虽然小角度下等时，但大幅摆动和小幅摆动的细微差异会累积成误差。

惠更斯的解决方案堪称天才：他设计了一种特殊的摆——**摆锤沿着摆线（旋轮线）运动**。摆线的数学性质保证了，无论摆幅大小，周期完全相等——这是真正的等时，不是近似。

他用金属板做成摆线的约束导轨，让摆锤的悬线贴着导轨弯折。这样摆锤走的就不是圆弧，而是摆线弧。1656年，第一台摆钟问世，一天的误差不到15秒——在那个时代，这是前所未有的精度。

惠更斯还解决了另一个问题：能量补充。摆会因为摩擦逐渐停下来，他用一个由重锤驱动的擒纵机构，每次摆锤经过中点时轻轻推它一下，补充能量。这就像推秋千——每次经过最低点时给一个小推力，秋千就能一直荡下去。`,
    principle: `
**1. 单摆的周期公式**
小角度下，单摆做简谐运动，周期仅由摆长和重力加速度决定，与摆锤质量和振幅无关。这是**高二物理·简谐运动**的核心公式。

**2. 简谐运动**
当回复力与位移成正比且方向相反时，物体做简谐运动。单摆在小角度下近似满足这一条件，所以表现出等时性。对应**高二·机械振动**。`,
    thinking: `
**为什么重要？**
摆钟的发明让人类第一次拥有了精确到秒的计时能力。在此之前，最好的钟表一天误差15分钟；摆钟把这个数字缩小到秒级。精确计时改变了航海——经度的确定需要精确时钟，没有它，船在海上就是瞎子。惠更斯后来发明的船用钟（虽然精度不如哈里森的航海钟），开启了精密计时推动大航海时代的序幕。

**现代应用**
今天虽然没人用摆钟了，但简谐运动的思想无处不在：石英晶体在电场中以极其稳定的频率振动，这就是石英表的原理——本质上是用压电晶振替代了重力摆。原子钟则用铯原子的跃迁频率定义"秒"，精度达到10¹⁵分之一，但它的数学骨架——周期性振荡——和惠更斯的摆钟一脉相承。

**还有什么未解之谜？**
单摆的等时性只在小角度下成立，大角度下的运动方程没有解析解，只能数值计算。更有趣的是，如果同时让摆锤在两个方向上自由摆动，就得到一个球面摆——它的轨迹会画出复杂的花样，表现出混沌行为。一个看似简单的摆，竟然藏着通往混沌的门。`,
  },
  'origin-005': {
    background: `
1785年的巴黎，一个军事工程师正对着桌上的一根细丝发呆。他叫查理·奥古斯丁·库仑，43岁，退休军官，一生研究过桥梁、土壤力学和摩擦力，是个经验丰富的实验高手。

他面前的问题看起来不可能完成：测量两个带电小球之间的力。

这个力有多小？小到你打个喷嚏就能干扰实验，走动带起的气流都能让结果跑偏。当时没有任何仪器能测这么微小的力——直到库仑想到了一个灵感来源：英国的米歇尔牧师几年前发明的扭秤，用来测磁铁之间的微弱作用力。

库仑对扭秤做了改良，把测量磁力的思路转到了静电力上。他用一根极细的悬丝（据传是银丝或丝线，甚至有说法用了头发），挂一根水平横杆，横杆一端装一个带电小球。附近再放一个固定带电小球，两个球之间的静电力让横杆转动，悬丝随之扭转。**悬丝扭转的角度就是力的量度**——越大的力，扭转角度越大。

这是人类第一次精确测量电的力量。`,
    core: `
库仑扭秤的精妙之处在于：**它把极其微小的力，转化为肉眼可读的角度**。

悬丝的扭转遵循胡克定律：扭矩与扭转角成正比。库仑先标定了悬丝的扭转系数——转一度对应多大力，然后通过读取扭转角直接得出静电力的大小。

他的实验步骤大致如下：

1. 给固定小球A和可动小球B带上同种电荷（都带正电或都带负电）
2. 两球互相排斥，横杆转动，悬丝扭转，直到扭转力矩与静电力矩平衡
3. 记录此时两球的距离和悬丝的扭转角
4. 改变距离，重复实验

库仑发现，静电力与两球之间距离的平方成反比——**距离增大到2倍，力减小到1/4；距离增大到3倍，力减小到1/9**。

接着，他改变电荷量。当时没有测量电荷量的仪器，他用了一个巧妙的办法：用一个与B球相同大小的不带电球碰触B球，电荷平分，B球的电荷量减半。实验发现，力也减半。对A球做同样操作，结果一致。

综合起来，库仑得出了后来以他名字命名的定律：

\$\$F = k\\frac{q_1 q_2}{r^2}\$\$

静电力与两个电荷量的乘积成正比，与距离的平方成反比。这个公式和万有引力定律惊人地相似——都是平方反比律——只是引力永远是吸引力，而静电力既有吸引也有排斥。

库仑的实验精度其实并不完美。他只做了不多几次测量，数据的精确度后来被质疑过。但他的结论经受住了两百多年的检验——库仑定律的平方反比关系在 \$10^{-16}\$ 米的尺度上仍然成立，是物理学中被验证得最精确的定律之一。`,
    principle: `
**1. 库仑定律**
真空中两个点电荷之间的力与电荷量乘积成正比，与距离平方成反比，方向沿连线。这是**高二物理·静电场**的第一课，也是整个电磁学的起点。

\$\$F = k\\frac{q_1 q_2}{r^2}\$\$

其中 \$k \\approx 9 \\times 10^9 \\, \\text{N·m}^2/\\text{C}^2\$ 是静电力常量。

**2. 扭秤原理**
悬丝的扭矩 \$M = C\\theta\$（\$C\$ 为扭转系数，\$\\theta\$ 为扭转角）。力矩平衡时，静电力产生的力矩等于悬丝的恢复力矩，从而把力转化为角度。这是力学与电学结合的经典实验设计，对应**高二·力矩平衡**的延伸。`,
    thinking: `
**为什么重要？**
库仑定律和万有引力定律同为平方反比律，这个相似性绝不是巧合——它暗示了场的传播方式。后来麦克斯韦证明，电磁场以光速传播，平方反比律正是三维空间中点源辐射的几何结果。理解了这一点，你就理解了为什么所有"从一点向四面八方均匀辐射"的力都是平方反比的。

**现代应用**
库仑定律是静电学的基础，从原子中电子和质子的结合力，到工业中的静电除尘、静电喷涂，再到原子力显微镜（AFM）中探针与样品之间的相互作用力——本质上都是库仑力在不同尺度上的表现。

**还有什么未解之谜？**
库仑定律的平方反比关系为什么如此精确？如果空间有额外的隐藏维度，力的衰减应该比平方反比更快。物理学家在极小距离上检验库仑定律，实际上是在寻找额外维度的证据。另外，为什么引力只有吸引，而电力有吸引和排斥？这两种力如此相似又如此不同，背后是否有一个更深层的统一理论？这也是物理学圣杯之一。`,
  },
  'origin-006': {
    background: `
1820年4月的一个晚上，丹麦哥本哈根大学的讲座厅里，物理教授汉斯·克里斯蒂安·奥斯特正在给学生们演示电学实验。讲台上摆着伏打电池、导线和一个小磁针。

他的本意是演示电流让导线发热——一个再普通不过的电学演示。但不知是刻意安排还是无心插柳，导线碰巧放在了小磁针旁边，而且方向平行。

他合上开关，电流流过导线的一瞬间，小磁针微微偏转了一下。

台下学生可能没注意到，但奥斯特注意到了。他愣了一下——这不对。电流和磁针有什么关系？电是电，磁是磁，两千年来人们一直认为这是两种完全不同的现象。静电能吸引轻小物体，磁铁能吸引铁，但它们之间从没有任何交集。

奥斯特停下讲课，反复实验。确认无误：**通电导线确实让磁针偏转了**。电和磁之间，存在某种神秘的联系。

三个月后，他正式发表论文，整个欧洲物理学界炸了锅。`,
    core: `
奥斯特的发现之所以震撼，是因为它打破了物理学的一个基本假设：电和磁是两码事。

在他之前，电学研究的是电荷之间的力（库仑定律），磁学研究的是磁铁之间的力，两者井水不犯河水。奥斯特的实验证明：**运动的电荷（电流）能产生磁场**——电可以生磁。

这个磁场长什么样？奥斯特发现，磁针偏转的方向不是被导线吸引或排斥，而是绕着导线打转。也就是说，电流产生的磁感线是**环绕导线的同心圆**——就像你把右手拇指指向电流方向，四指弯曲的方向就是磁场方向。这就是著名的**右手螺旋定则**（安培定则）。

奥斯特之后仅仅几个月，法国物理学家安培就给出了数学描述：一根无限长直导线在距离 \$r\$ 处产生的磁场强度为：

\$\$B = \\frac{\\mu_0 I}{2\\pi r}\$\$

其中 \$I\$ 是电流，\$\\mu_0\$ 是真空磁导率。磁场强度与电流成正比，与距离成反比。

安培走得更远。他发现两根平行导线之间也有力——同向电流互相吸引，反向电流互相排斥。他甚至提出：所有磁现象的本质都是电流——磁铁之所以有磁性，是因为内部存在微小的环形电流。这个假说后来被证明是对的：电子绕原子核运动确实是"分子电流"的来源。

从奥斯特的偶然观察到安培的数学框架，只用了不到一年。此后法拉第顺理成章地追问：**如果电能生磁，磁能不能生电？**——1831年，他发现了电磁感应。电与磁彻底统一，人类迈入电气时代。`,
    principle: `
**1. 电流的磁效应**
通电导线在周围空间产生磁场，方向由右手螺旋定则判断。这是**高二物理·电流的磁场**的核心内容，也是整个电磁学的转折点。

**2. 安培力**
通电导线在磁场中受力，方向由左手定则判断，大小为 \$F = BIL\$（导线垂直于磁场时）。两根平行导线之间的力正是安培力的体现。对应**高二·磁场对电流的作用**。`,
    thinking: `
**为什么重要？**
奥斯特的发现是物理学史上最重要的"偶然"之一。它打开了电与磁统一的大门，直接催生了电磁感应、麦克斯韦方程组和整个电磁理论。没有这一步偏转，就不会有发电机、电动机、电磁波——也就没有现代文明。

**现代应用**
几乎所有电磁设备都源于"电生磁"的原理：电磁铁、电动机、变压器、继电器、磁悬浮列车……你手机里的振动马达就是一个小电磁铁在电流驱动下往复运动。医院里的核磁共振（MRI），用超导线圈产生超强磁场——本质上是奥斯特效应的极限放大版。

**还有什么未解之谜？**
奥斯特发现了电生磁，法拉第发现了磁生电，麦克斯韦统一了两者——但为什么电和磁能统一？在更深的层面，电磁力是四种基本力中最早被统一的。这种统一是否可以继续？电磁力和弱力已经被统一为"电弱力"，但把强力也拉进来——大统一理论——至今没有实验验证。磁单极子（只有一个磁极的粒子）如果存在，将是大统一理论的强有力证据，但它至今未被找到。`,
  },
  'origin-007': {
    background: `
1801年的英国，物理学界有一个不成文的规矩：别跟牛顿作对。

牛顿在1704年出版的《光学》中明确断言：光是一束微粒流。一百年来，这个观点几乎是教科书级别的真理。偶尔有人质疑，但都被"牛顿说得对"压回去了。微粒说能解释反射和折射，和权威站在一起，谁还敢说不？

但有个叫托马斯·杨的医生偏不信。他既是眼科大夫，又是语言学家（他后来破译了罗塞塔石碑的部分内容），还兼职物理学家。这种跨界的背景让他不迷信权威——他注意到微粒说解释不了很多东西，比如肥皂泡的颜色、薄油膜上的彩虹纹。

杨猜想：如果光是波，这些现象就顺理成章了——波可以有叠加，两列波相遇会互相加强或抵消，形成明暗交替的图案。这个现象叫**干涉**，只有波才会干涉，粒子不会。

他需要一个决定性的实验。于是，他拿了一根针和一束光。`,
    core: `
杨的实验装置极其简单，但逻辑极其锐利。

他让阳光穿过一个窄缝，变成一束细光；然后在这束光前方放一块不透光的屏，屏上刻了**两条相距很近的平行窄缝**；最后在更远处放一块观察屏。

如果光是粒子，两束微粒穿过两条缝后，应该在观察屏上形成两道亮纹——就像两束手电筒光各照一个位置。但杨看到的不是两道亮纹，而是一系列**明暗交替的条纹**。

亮纹出现的地方，是从两条缝出来的光**相互加强**了——两列波的波峰正好叠在一起；暗纹出现的地方，光**相互抵消**了——一列波的波峰正好遇上另一列波的波谷。结果就是：光+光=暗。

这就好比两个人同时往水里扔石头，两组涟漪相遇后，某些地方水面特别高，某些地方水面特别平静。**只有波才会这样**。粒子永远不会出现"1+1=0"的情况——你往墙上扔两个球，它们不会在某些位置消失。

杨还推导了条纹间距的公式：

\$\$\\Delta y = \\frac{\\lambda D}{d}\$\$

其中 \$\\Delta y\$ 是相邻亮纹的间距，\$\\lambda\$ 是光的波长，\$D\$ 是双缝到观察屏的距离，\$d\$ 是两条缝之间的间距。这个公式不仅能解释条纹为什么出现，还能**通过测量条纹间距反推光的波长**——杨由此估算出可见光的波长约在400~700纳米之间，与今天的精确值惊人地接近。

尽管证据确凿，杨的论文发表后遭到了猛烈攻击。微粒说的支持者嘲笑他，权威期刊拒绝刊登他的后续研究。但真理不因嘲讽而改变——几十年后，麦克斯韦的电磁理论彻底证明了光就是电磁波，杨的实验成了物理学史上最优雅的判决实验之一。`,
    principle: `
**1. 光的干涉**
两束相干光（频率相同、相位差恒定）叠加时，某些位置光强增大（明纹），某些位置光强减小（暗纹）。这是**高中物理·光的干涉**的核心内容，双缝干涉是最经典的干涉装置。

**2. 波长与条纹间距**
条纹间距与波长成正比，与缝距成反比。红光波长长，条纹间距大；紫光波长短，条纹间距小。这就是白光干涉时出现彩色条纹的原因。对应**高二·光学**。`,
    thinking: `
**为什么重要？**
杨氏双缝实验不只是证明了光是波。到了20世纪，物理学家用单个光子（或电子）一个个地通过双缝，结果依然出现干涉条纹——单个粒子竟然"自己和自己干涉"！这直接催生了量子力学的波粒二象性概念。费曼说：双缝实验包含了量子力学"唯一的秘密"。

**现代应用**
干涉是精密测量的最强工具。迈克尔逊干涉仪用光干涉测量长度变化，精度达到纳米级，被用来探测引力波（LIGO）。工业上用干涉仪检测透镜和镜面的加工质量，精度远超任何机械量具。全息摄影的原理也是干涉——记录下光波的干涉图案，就能重建物体的三维像。

**还有什么未解之谜？**
当你用探测器"偷看"光子到底走了哪条缝时，干涉条纹就消失了。观测行为本身改变了实验结果——这到底是为什么？量子力学给出了数学描述（波函数坍缩），但物理图像上，"观测如何影响现实"至今是最深刻的哲学-物理难题之一。双缝实验的两百年后，它的核心谜题不仅没有消失，反而越来越深了。`,
  },
  'origin-008': {
    background: `
1909年，物理学家们已经知道电子的存在——J.J.汤姆孙12年前就在阴极射线实验中发现了它。但他们只知道电子的荷质比（电荷量与质量之比），不知道电子到底带多少电，也不知道质量是多少。

问题在于：怎么测量一个如此微小的电荷？电子的电荷量大约是 \$1.6 \\times 10^{-19}\$ 库仑——这个数字小到任何直接测量都是徒劳的。

芝加哥大学的罗伯特·密立根想出了一个绝妙的主意：**不直接测电子，而是让一颗带电的油滴替他干活**。

他的思路是：如果油滴上只带几个电子的电荷，那么测量油滴在电场中的受力情况，就能反推出单个电子的电荷量。这个实验后来被称为"物理学史上最美丽的实验"之一，但也伴随着一段不那么光彩的学术争议。`,
    core: `
密立根的装置是这样的：两块水平金属板，上面一块正中有个小孔，板间可以加电压产生均匀电场。他用喷雾器把油滴喷入上方小孔，油滴在下落过程中因摩擦带上微小的电荷（通常是几个到几十个电子的电荷）。

他通过显微镜观察油滴的运动，做了两种测量：

**第一种：不加电场，让油滴自由下落**

油滴在空气中下落时受两个力：向下的重力和向上的空气阻力。当两者平衡时，油滴匀速下落。根据斯托克斯定律，空气阻力与速度成正比：

\$\$f = 6\\pi \\eta r v\$\$

其中 \$\\eta\$ 是空气的黏度，\$r\$ 是油滴半径，\$v\$ 是匀速下落速度。重力等于浮力修正后的重量：

\$\$mg - m'\\rho_{\\text{空气}}g = 6\\pi \\eta r v_1\$\$

通过测量匀速下落速度 \$v_1\$，密立根可以算出油滴的半径 \$r\$，进而算出油滴的质量 \$m\$。

**第二种：加上电场，让油滴悬浮或缓慢上升**

加上电压后，电场对油滴施加向上的力 \$qE\$（\$q\$ 是油滴电荷量，\$E\$ 是电场强度）。如果电场力恰好平衡重力，油滴就悬浮在空中——静止不动。

\$\$qE = mg\$\$

但密立根发现，精确悬浮太难调节了。他改为测量油滴在电场中的匀速上升速度 \$v_2\$，此时电场力向上，重力和空气阻力向下：

\$\$qE - mg = 6\\pi \\eta r v_2\$\$

结合第一种测量的结果，消去 \$m\$ 和 \$r\$，就能算出 \$q\$。

**关键发现**

密立根对成百上千颗油滴反复测量，得到一个惊人的结果：**所有油滴的电荷量都是某个最小单位的整数倍**——1倍、2倍、3倍、5倍……从未出现过1.5倍或2.3倍。

这个最小单位就是电子电荷：

\$\$e = 1.602 \\times 10^{-19} \\, \\text{C}\$\$

**电荷是量子化的**——它不能连续取值，只能一份一份地增减。这是人类第一次用实验证明，自然界存在一个不可再分的基本电荷单位。

密立根1913年发表的值为 \$e = (1.592 \\pm 0.002) \\times 10^{-19}\$ C，与今天的公认值偏差不到1%。`,
    principle: `
**1. 电荷量子化**
任何带电体的电荷量都是基本电荷 \$e\$ 的整数倍。这是**高二物理·静电场**中电荷守恒定律的延伸，也是量子力学的实验起点之一。

**2. 电场中的力学平衡**
带电粒子在电场中受力 \$F = qE\$，与重力、阻力平衡时做匀速运动。这是力学与电学知识的综合应用，对应**高二·带电粒子在电场中的运动**。

**3. 斯托克斯定律**
小球的低速运动阻力与速度和半径成正比，这是流体力学的基础结论。密立根巧妙地用它"称"出了油滴质量，再结合电场力"称"出电荷。`,
    thinking: `
**为什么重要？**
密立根油滴实验证明了两件大事：第一，电荷是量子化的，存在最小单位；第二，精确测定了基本电荷的值。有了 \$e\$ 的精确值，再结合汤姆孙的荷质比，就能算出电子的质量——整个原子物理的定量基础从此建立。这个实验也是物理学史上"用宏观仪器探测微观世界"的经典范例。

**现代应用**
电荷量子化是半导体物理的根基——每个晶体管里流动的电流，本质上是整数个电子的定向移动。单电子晶体管（SET）在极低温下可以逐个控制电子的通过，是未来量子计算的可能组件。2020年，国际单位制重新定义了安培，其基础正是基本电荷 \$e\$ 的精确值——密立根的油滴至今在为全世界"标定"电流。

**还有什么未解之谜？**
电荷为什么是量子化的？在标准模型中，这只是一个实验事实，没有理论解释。狄拉克在1931年提出：如果宇宙中存在磁单极子，电荷量子化就自然成立——但磁单极子至今未被找到。另外，夸克带的电荷是 \$e/3\$ 或 \$2e/3\$——但夸克不能单独存在（色禁闭），所以自由粒子的电荷仍然是 \$e\$ 的整数倍。这个"色禁闭"本身也是一个未完全理解的现象。`,
  },
  'puzzle-001': {
    background: `
1950年的一天，物理学家恩里科·费米和几位同事在洛斯阿拉莫斯实验室的食堂吃午饭。聊天中有人提到外星飞碟的传闻，费米没怎么接话。过了一会儿，他突然放下刀叉，问了一句："So where is everybody?"——大家都呢？食堂里一片沉默。这不是一个随口的问题。费米快速估算了一下：银河系有约2000亿颗恒星，其中很多比太阳古老几十亿年。只要有一小部分恒星拥有宜居行星，只要其中一小部分孕育了文明，只要这些文明中有一小部分发展出星际旅行——哪怕以1%光速扩张，整个银河系也只需要几千万年就能被殖民完毕。几千万年，在宇宙137亿年的尺度上不过一眨眼。所以，如果外星文明存在，他们应该早就到了。可是，我们一个也没看到。这就是费米悖论——宇宙应该热闹非凡，却寂静无声。`,
    core: `
费米悖论可以用一个方程来量化——德雷克方程，1961年由天文学家弗兰克·德雷克提出：

\$\$N = R_* \\times f_p \\times n_e \\times f_l \\times f_i \\times f_c \\times L\$\$

N是银河系中可通讯文明的数目。从左到右七个因子分别是：恒星形成速率、有行星的比例、宜居行星数、宜居行星上诞生生命的比例、生命进化出智慧的比例、智慧发展出通讯技术的比例、文明可通讯的寿命。前几个因子我们现在有了较好的估计——银河系恒星形成速率约每年1~3颗，开普勒望远镜的数据显示约20%的类太阳恒星有宜居带行星。但后几个因子，尤其是 \$f_i\$（生命到智慧的跃迁概率）和 \$L\$（文明寿命），几乎完全靠猜。如果 \$L\$ 很短——文明在掌握通讯技术后很快自我毁灭——N可能只有1，就是我们自己。

围绕费米悖论，几十年来诞生了大量假说。"大过滤器"理论认为：从无机物到星际文明之间，存在至少一个极难跨越的门槛——也许生命起源本身极其罕见，也许智慧的出现概率极低，也许文明总是自毁于核战或环境崩溃。关键问题是：大过滤器在我们身后还是前方？如果在我们身后，那人类是宇宙中的幸运儿；如果在前方，那我们离末日可能不远了。

另一个令人不安的思路是"黑暗森林"假说：宇宙不是没人，而是所有人都藏起来了。因为无法判断其他文明的善恶，最安全的策略是保持沉默——暴露就意味着被消灭。这听起来像科幻（刘慈欣《三体》让它广为人知），但在博弈论上并非不合理：无限重复的囚徒困境中，"先下手为强"可能是纳什均衡。

还有一种可能：我们根本不在同一个"频道"上。外星文明也许用中微子或引力波通讯，也许他们早已上传意识不再需要物理身体，也许他们的时间尺度完全不同——对寿命百万年的文明来说，人类的千年文明不过是一闪而过。`,
    principle: `
1. **德雷克方程**：将文明数量分解为可估算的因子乘积。\$N = R_* f_p n_e f_l f_i f_c L\$——这是一个量级估计框架，不是精确计算，但它清晰地标出了我们的无知之处。（不在高中课本，但逻辑上可理解）

2. **光速限制与星际旅行**：即使以1%光速扩张，殖民一个直径10万光年的银河系约需1000万年——这远小于银河系的年龄，说明如果有文明开始扩张，早该到我们这里了。

3. **可居住带**：恒星周围液态水可能存在的区域。太近水蒸发，太远水冻结。\$d_{\\text{HZ}} \\propto \\sqrt{L/L_\\odot}\$——恒星光度越大，可居住带越远。开普勒望远镜的发现表明，银河系中可能有数百亿颗宜居带行星。

4. **电磁波探测的局限**：人类无线电信号最远传播约100光年，且信号强度随距离平方衰减。\$P_{\\text{接收}} \\propto P_{\\text{发射}}/d^2\$——在几光年之外，我们的电视信号已经弱到几乎无法探测。`,
    thinking: `
**为什么重要？**
费米悖论逼迫我们直面一个终极问题：人类在宇宙中是孤独的吗？如果答案是"是"，我们的存在就更加珍贵；如果"否"，为什么我们看不到他们？无论哪种答案，都深刻地影响我们对文明命运的思考。

**现代应用**
SETI（搜寻地外智慧生命）项目持续监听宇宙中的可疑信号，中国的500米口径球面射电望远镜（FAST）也在参与搜寻。系外行星探测方面，詹姆斯·韦布空间望远镜已经能分析部分系外行星的大气成分，寻找生命标志物（如氧气、甲烷的同时存在）。

**还有什么未解之谜？**
费米悖论本身就是最大的未解之谜。我们甚至不知道该从哪个方向寻找答案——是生命起源的化学问题，是文明演化的人类学问题，还是宇宙结构的物理学问题？也许答案不在任何单一学科中，而需要一种全新的跨学科思维。或者，也许答案就在下一个接收到的信号里——只是这一次，我们准备好了吗？`,
  },
  'puzzle-002': {
    background: `
1929年，哈勃发现远处的星系正在离我们远去，宇宙在膨胀。此后的半个世纪，天文学家默认膨胀在减速——引力在拉住一切，就像抛向空中的石头终将减速回落。问题是：减速有多快？宇宙会不会最终收缩？1998年，两个独立团队——索尔·珀尔马特和亚当·里斯/布莱恩·施密特——决定用Ia型超新星来精确测量宇宙膨胀的减速速率。Ia型超新星亮度几乎恒定，堪称"标准烛光"，测出它看起来多暗，就知道它离我们多远。但结果让所有人跌破了眼镜：远处的超新星比预期的更暗——它们比减速膨胀模型预测的更远。宇宙不是在减速膨胀，而是在加速膨胀。有什么东西在把宇宙往外推。这个"东西"被叫做暗能量。珀尔马特、里斯和施密特因此获得2011年诺贝尔物理学奖。`,
    core: `
暗能量是什么？最简单的假说是**宇宙学常数**——爱因斯坦1917年引入的那个"最大的错误"。当年爱因斯坦为了让宇宙保持静止，在广义相对论场方程中加了一项 Λ（Lambda），代表空间本身的固有能量。哈勃发现膨胀后，爱因斯坦撤回了 Λ。但1998年的发现让它起死回生：Λ 不为零，它代表着真空本身具有正能量，产生排斥性引力——正是这种排斥在推动宇宙加速膨胀。

\$\$\\Lambda = 8\\pi G \\rho_v / c^2\$\$

Λ是宇宙学常数，\$\\rho_v\$ 是真空能量密度。在标准宇宙学模型中，暗能量贡献了宇宙总能量密度的约68%，暗物质约27%，普通物质仅约5%——我们熟悉的一切只占5%。

但这里有一个令人窒息的问题：量子场论计算的真空能量密度，比观测值大了约 \$10^{120}\$ 倍——这被称为"物理学中最严重的预测失败"。如果真空能量真有量子场论预言的那么大，宇宙会在极早期就被自身能量炸开，星系、恒星、地球根本不可能形成。为什么实际的暗能量这么小？又为什么恰好是这个值——不多不少，刚好让宇宙在当前时代从减速膨胀转为加速？这就是所谓的"巧合问题"。

另一种假说认为暗能量不是常数，而是一种随时间变化的**Quintessence**（第五元素）场——一种弥散在宇宙中的标量场，其能量密度随宇宙膨胀缓慢变化。如果Quintessence存在，暗能量在不同时代可能表现不同，甚至有一天可能变为吸引力，让宇宙重新收缩。但目前的数据更支持宇宙学常数——暗能量的密度在测量精度内确实看起来是恒定的。

更激进的思路是：也许暗能量根本不存在，而是广义相对论在大尺度上需要修正。修改引力理论（如f(R)引力）可以在不引入暗能量的情况下解释加速膨胀。但这些理论往往在其他观测上碰壁，比如它们对星系团形成和宇宙微波背景的预测与数据不符。`,
    principle: `
1. **哈勃定律**：星系退行速度与距离成正比，\$v = H_0 d\$——\$H_0\$ 是哈勃常数，约70 km/s/Mpc。这是宇宙膨胀的直接证据。加速膨胀意味着H随时间增大。（高一下学期·万有引力延伸）

2. **弗里德曼方程**：描述宇宙膨胀速率的方程。\$\\left(\\frac{\\dot{a}}{a}\\right)^2 = \\frac{8\\pi G}{3}\\rho - \\frac{k}{a^2} + \\frac{\\Lambda}{3}\$——a是宇宙尺度因子，\$\\rho\$ 是物质密度，k是曲率参数。当Λ项足够大，膨胀就从减速变为加速。

3. **真空能量与排斥性引力**：在广义相对论中，压强为负的能量产生排斥性引力。暗能量的状态方程 \$w = p/\\rho \\approx -1\$——压强是负能量密度的负值，这在日常物质中闻所未闻，却是宇宙学常数的标准特征。

4. **Ia型超新星测距**：Ia型超新星峰值亮度几乎恒定，距离模数 \$m - M = 5\\log_{10}(d/10\\text{pc})\$——测出视星等m和已知绝对星等M，就能算出距离d，再与红移对比，判断膨胀是加速还是减速。`,
    thinking: `
**为什么重要？**
暗能量占宇宙的68%，主宰着宇宙的命运，但我们完全不知道它是什么。这是物理学最深刻的悖论之一：我们精确地知道了宇宙的组成比例，却对其中最大的成分一无所知。它可能只是真空的一个数学性质，也可能是某种全新的物理场，甚至可能暗示我们需要修改爱因斯坦的引力理论。

**现代应用**
暗能量研究推动了大规模巡天项目的发展。中国的暗能量光谱仪（DESI）正在对数千万个星系进行红移测量，精确追踪宇宙膨胀历史。欧几里得空间望远镜于2023年发射，将绘制史上最大尺度的宇宙三维地图。这些项目的数据处理技术也被用于大数据分析和人工智能领域。

**还有什么未解之谜？**
暗能量的本质是21世纪物理学的最大谜题之一。为什么真空能量比量子场论预言的小 \$10^{120}\$ 倍？暗能量真的恒定不变吗？它会不会在遥远的未来突然改变行为——让宇宙"大撕裂"（一切物质被撕碎）或"大坍缩"（一切重新收缩）？更根本的问题是：我们关于量子引力的无知，是否正是理解暗能量的钥匙？`,
  },
  'puzzle-003': {
    background: `
1925年之后，爱因斯坦把几乎所有精力都投入了一项事业：寻找统一场论——把引力和电磁力纳入同一个数学框架。他拒绝接受量子力学的概率诠释，坚信"上帝不掷骰子"，认为一定存在一个更优雅的理论能同时描述引力和电磁力。他失败了。到他1955年去世时，统一场论仍然遥不可及。但爱因斯坦的直觉没有错——力的统一确实是物理学最深层的追求。后来发现，宇宙中不是两种力而是四种：引力、电磁力、强力、弱力。20世纪后半叶，物理学家成功统一了电磁力和弱力，又把强力纳入了标准模型的框架——三种力在极高温下归一，唯独引力顽固地拒绝被纳入量子体系。大统一理论，就是要把这最后一步走完。`,
    core: `
四种基本力看上去截然不同：引力最弱但力程无限，电磁力控制原子和光，强力把夸克捆在核子里但力程极短，弱力负责放射性衰变。但物理学家发现了一个惊人的模式：力越强，作用范围越短；而随着能量升高，这些力的强度会趋同。

电磁力和弱力在1970年代被格拉肖、温伯格和萨拉姆统一为**电弱力**。在日常低能条件下，电磁力和弱力表现完全不同；但当能量超过约100 GeV，两种力的强度趋于一致，W和Z玻色子的质量差异消失——它们变成了同一种力的不同方面。就像冰和水在零度以下是不同形态，但在高温下都是水蒸气。

\$\$\\alpha_1(M_{GUT}) = \\alpha_2(M_{GUT}) = \\alpha_3(M_{GUT})\$\$

在约 \$10^{16}\$ GeV的能量（大统一尺度）下，三种力的耦合常数趋于同一点——这就是大统一理论（GUT）的核心预言。不过，标准模型中三种力的汇聚点不够精确，需要超对称（每种粒子都有一个"超伴"）的修正才能完美交汇。

大统一理论预言了一些惊人的现象：**质子衰变**。如果三种力真的统一，夸克和轻子之间就存在某种对称性，质子（由夸克组成）理论上可以衰变成轻子。但质子衰变的预期半衰期超过 \$10^{34}\$ 年——比宇宙年龄大24个数量级。日本超级神冈探测器用5万吨纯水监测了20多年，没有看到一起质子衰变事件。

真正的终极统一必须纳入引力，这就是**万物理论（Theory of Everything）**。但引力和其他三种力的矛盾极其深刻：引力用广义相对论描述，是经典的、确定性的、几何化的；其他三种力用量子场论描述，是量子的、概率性的、代数化的。把时空的几何和量子的概率融合在一起，是物理学最难的问题。

弦理论是最野心勃勃的尝试：把点粒子替换为一维的振动弦，不同的振动模式对应不同的粒子——引力子自然地出现在谱中。弦理论需要10或11维时空，多余的维度蜷缩在普朗克尺度（\$10^{-35}\$ 米）。但弦理论目前无法做出可检验的预言，而且它有约 \$10^{500}\$ 种可能的真空态——哪个对应我们的宇宙？这被称为"弦景观"问题。`,
    principle: `
1. **耦合常数跑动**：力的强度随能量变化。量子场论中，真空极化效应屏蔽或反屏蔽电荷，使得耦合常数随能量"跑动"。电磁力增强、强力减弱——三条线在高能处可能交汇。（高二下学期·电磁场延伸）

2. **电弱统一**：在100 GeV以上，电磁力和弱力统一。对称性破缺温度约 \$10^{15}\$ K——宇宙大爆炸后约 \$10^{-12}\$ 秒时电弱力一分为二。

3. **引力与量子力学的矛盾**：广义相对论把时空视为平滑的连续流形；量子力学要求在普朗克尺度下时空剧烈涨落。\$l_P = \\sqrt{\\hbar G/c^3} \\approx 1.6 \\times 10^{-35}\$ 米——在这个尺度下，时空本身可能是离散的、泡沫状的。

4. **弦理论的额外维度**：弦的振动模式在10维时空中才能自洽。多余6维蜷缩成卡拉比-丘流形，不同的蜷缩方式对应不同的物理常数——解释了为什么我们的宇宙有这些特定的参数值。`,
    thinking: `
**为什么重要？**
大统一理论不只是"把方程写得更好看"。如果成功，它将回答物理学最根本的问题：为什么宇宙恰好有这些力和这些常数？为什么粒子有这些质量？统一意味着简单——在最高层次上，宇宙的运行逻辑可能出奇地简洁，就像麦克斯韦把电和磁统一后，电磁学变得比电学加磁学更简单。

**现代应用**
虽然大统一理论本身尚未成功，但研究过程中的数学工具已经产生了深远影响。弦理论中的对偶性概念被应用于凝聚态物理和量子信息；超对称的思想推动了超导理论的发展；额外维度的数学被用于解决纯数学中的拓扑学难题。

**还有什么未解之谜？**
大统一理论是否真的存在？也许自然本来就不是统一的——四种力可能就是四种独立的存在，统一只是人类的审美偏好。或者，也许统一需要的不是更复杂的数学，而是一种全新的物理思想——就像量子力学不是经典力学的推广，而是一种全新的范式。下一个爱因斯坦——或者费曼——会从哪个角落冒出来？没有人知道，但物理学家们仍在追寻。`,
  },
  'stars-001': {
    background: `
1791年，迈克尔·法拉第出生在伦敦郊区一个铁匠家庭。家里穷到什么程度？他13岁就辍学了，在书店当装订工学徒——每天把书页缝在一起，装上封面。

但对法拉第来说，这简直是世界上最棒的工作——因为他可以免费看书。他贪婪地读一切科学书籍，尤其是《大英百科全书》中关于电的条目。他还照着书上的描述做实验——用废旧的瓶子和铜线，在书店的角落里搭起了自己的"实验室"。

改变他命运的时刻发生在1812年。他听到著名化学家戴维在皇家学会的公开讲座，疯狂地做了详细笔记，整理成300多页的手稿寄给戴维，附信写道："我渴望进入科学的世界。"

戴维被这个年轻人的热情打动了。恰好戴维在一次实验中伤了眼睛，需要一个助手——法拉第就这样被录用了。戴维太太把他当仆人使唤，但法拉第不在乎。他终于站在了科学的门口——而他即将推开的，是一扇通往电气时代的大门。`,
    core: `
法拉第一生最重要的发现是**电磁感应**。

1820年奥斯特发现电生磁之后，法拉第在笔记本上写下一句话："磁能否生电？"他花了整整十年寻找答案。

他的实验方法非常朴素：在一个铁环上绕了两组线圈，一组接电池（初级线圈），另一组接电流计（次级线圈）。他想：初级线圈通电后产生磁场，磁场穿过铁环到达次级线圈，次级线圈里应该出现电流。

但实验结果出乎意料——次级线圈没有持续电流。电流计的指针只是在合上开关的一瞬间跳了一下，然后又回到零。

法拉第反复实验，终于意识到关键：**不是磁场的存在产生了电，而是磁场的变化产生了电**。开关合上时磁场从无到有——电流计动了；稳定后磁场不变——电流消失；断开开关时磁场从有到无——电流计又反方向跳了一下。

这就是电磁感应定律：**变化的磁场在闭合回路中产生感应电动势**。法拉第用实验证明了"磁生电"，补上了电与磁统一的最后一块拼图。

他还发现，感应电动势的大小与磁通量变化率成正比：

\$\$\\mathcal{E} = -\\frac{\\Delta \\Phi}{\\Delta t}\$\$

这个公式中的负号表示感应电流总是试图阻碍磁通量的变化——这就是**楞次定律**，像是自然界在说"我不喜欢变化"。

法拉第不懂高等数学，但他的物理直觉惊人。他不用公式，而是用"力线"来想象电磁场——磁力线从磁铁北极出发，弯弯曲曲地到达南极。这个图像后来被麦克斯韦用数学方程严格描述，成为电磁理论的基石。`,
    principle: `
**1. 法拉第电磁感应定律**
闭合回路中磁通量变化时产生感应电动势，大小与磁通量变化率成正比。这是**高二物理·电磁感应**的核心定律，也是发电机的工作原理。法拉第本人不会数学，他用直觉和实验发现了这个规律，而后来者用精确的数学语言把它写成了方程——科学史上，直觉先行、数学殿后的例子并不少见。

**2. 楞次定律**
感应电流的方向总是阻碍引起感应的磁通量变化。这是能量守恒在电磁现象中的体现——如果感应电流"帮助"变化，就会凭空产生能量，违反守恒律。你可以这样理解：自然界是个"保守派"，它不喜欢任何突然的变化，总要制造阻力来延缓——楞次定律就是这种"保守"性格在电磁世界的体现。`,
    thinking: `
**为什么重要？**
没有电磁感应，就没有发电机，没有电网，没有电灯——人类可能至今还在烧煤点蜡烛。法拉第的发现直接催生了第二次工业革命，电从此不再是实验室里的玩物，而是走进了千家万户。而他的"力线"思想，超越了当时的数学工具，为麦克斯韦建立电磁场理论铺平了道路。一个没上过大学的人，改写了人类文明的进程。

**现代应用**
今天世界上每一个发电站——无论是火力、水力还是核能——都在用法拉第的原理发电：让线圈在磁场中转动，磁通量不断变化，持续产生感应电流。变压器、无线充电、电磁炉，也都是电磁感应的直接应用。

**还有什么未解之谜？**
法拉第统一了电和磁，麦克斯韦统一了电磁和光，但电磁力和引力的统一至今未完成。法拉第晚年痴迷于寻找电磁和引力的联系，设计了各种实验，都失败了。他毕生相信自然界应该有统一的规律——这个信念，至今仍在驱动物理学家寻找大统一理论。`,
  },
  'stars-002': {
    background: `
法拉第发现了电磁感应，但他不会数学。他的论文里没有公式，全是力线图和文字描述。数学物理学家们看不上他的工作，觉得那不过是"实验匠人的直觉"。

但有一个人读懂了法拉第。他叫詹姆斯·克拉克·麦克斯韦，苏格兰人，1850年代剑桥大学最耀眼的数学天才。麦克斯韦在读法拉第的论文时被震撼了——那些力线不是比喻，而是真实的物理存在。法拉第用直觉看到的东西，麦克斯韦要用数学把它写出来。

1855年，24岁的麦克斯韦发表了第一篇电磁学论文《论法拉第的力线》。他后来回忆说，法拉第的论文里其实充满了数学，只不过用的是几何语言而非代数语言。他的工作，就是把这些几何语言"翻译"成方程。

这一翻译，用了整整十年。`,
    core: `
麦克斯韦的目标是：**用一组数学方程，完整描述所有电磁现象**。

他从前人的成果出发：

- **库仑定律**：电荷产生电场
- **毕奥-萨伐尔定律**：电流产生磁场
- **法拉第定律**：变化的磁场产生电场

但麦克斯韦发现了一个漏洞：前三个定律在数学上不自洽。根据安培定律，电流产生磁场，但如果在电流回路中加一个电容器（两块板中间是绝缘体，没有电流通过），磁场还是存在——这说明**变化的电场也能产生磁场**，就像变化的磁场产生电场一样。

麦克斯韦在安培定律中加了一项，叫**位移电流**：

\$\$\\nabla \\times \\mathbf{B} = \\mu_0 \\mathbf{J} + \\mu_0 \\varepsilon_0 \\frac{\\partial \\mathbf{E}}{\\partial t}\$\$

右边第一项是真实的电流，第二项就是变化的电场——位移电流。这一项的加入让方程组自洽了，同时也揭示了一个惊人的推论。

**变化的电场产生磁场，变化的磁场又产生电场——两者可以互相激发，像接力赛一样传播出去。** 麦克斯韦计算了这种传播的速度：

\$\$v = \\frac{1}{\\sqrt{\\mu_0 \\varepsilon_0}} \\approx 3 \\times 10^8 \\, \\text{m/s}\$\$

这个数字他太熟悉了——那就是光速。麦克斯韦在1865年的论文中写道："我们有充分的理由得出结论，光本身是一种电磁扰动，以波的形式通过电磁场传播。"

**电、磁、光，被四组方程统一了。**

这四组方程后来被简化为今天的形式，称为**麦克斯韦方程组**。爱因斯坦说："麦克斯韦方程组是牛顿时代以来物理学最重要的事件。"

麦克斯韦1879年因胃癌去世，年仅48岁。他没能看到赫兹在1888年用实验证实电磁波的存在——那束从方程中预言出来的波，终于在实验室里闪烁了。`,
    principle: `
**1. 麦克斯韦方程组（概念层面）**
四组方程描述了电磁场的全部行为：电荷产生电场、没有磁单极子、变化的磁场产生电场、电流和变化的电场产生磁场。这是**高二物理·电磁学**的终极框架，虽然完整的微分形式超出高中范围，但其物理含义完全可以在高中理解。

**2. 电磁波**
交替变化的电场和磁场互相激发，以光速向外传播。电磁波谱包括无线电波、微波、红外线、可见光、紫外线、X射线、伽马射线——本质都是电磁波，只是波长不同。对应**高二·电磁波**。`,
    thinking: `
**为什么重要？**
麦克斯韦方程组是物理学史上第一次大统一——电、磁、光三种看似不同的现象被归入同一个理论框架。这种"统一"的追求从此成为物理学的最高理想：爱因斯坦统一了时间和空间，后来又试图统一引力和电磁力；今天物理学家仍在寻找四种基本力的终极统一。麦克斯韦指明了方向。

**现代应用**
所有无线通信——手机信号、WiFi、蓝牙、卫星通信——都是电磁波的应用。每一次你连上WiFi，都是在验证麦克斯韦的方程。微波炉、雷达、X光机、CT扫描，不过是电磁波在不同频段的把戏。可以说，现代信息社会就建在麦克斯韦方程组上。

**还有什么未解之谜？**
麦克斯韦方程组是经典理论，它不涉及量子效应。光子的粒子性、真空的能量涨落、光与物质的微观相互作用——这些需要量子电动力学（QED）来描述。但QED的数学极其复杂，至今仍有一些微妙的计算难题。而把电磁理论引力和平共处——量子引力——更是悬而未决的终极问题。`,
  },
  'stars-003': {
    background: `
1905年，瑞士伯尔尼专利局的三级技术员阿尔伯特·爱因斯坦，26岁，月薪3500法郎，每天审查各种电磁设备的专利申请。没有人觉得他会改变物理学的面貌。

但就在这一年，他在业余时间发表了四篇论文——后来被称为"奇迹年论文"——每一篇都足以获得诺贝尔奖。其中一篇关于狭义相对论的论文，没有引用任何参考文献，没有感谢任何导师，就像凭空从石头里蹦出来的。

这篇论文的起点是一个看似荒唐的问题：**如果我以光速追赶一束光，我会看到什么？**

按照牛顿力学，你应该看到一束静止的光——但麦克斯韦方程组不允许"静止的电磁波"存在。要么牛顿错了，要么麦克斯韦错了，要么……你对时间和空间的理解全错了。

爱因斯坦选了第三条路。`,
    core: `
**狭义相对论的两个假设**

爱因斯坦从两个基本假设出发，推导出了整个狭义相对论：

1. **相对性原理**：物理定律在所有惯性参考系中形式相同。没有"绝对静止"的参考系。
2. **光速不变原理**：真空中的光速对所有惯性观察者都是相同的常数 \$c\$，与光源和观察者的运动状态无关。

第二条假设违背直觉——如果你坐在一列以0.5c速度行驶的火车上，向前射出一束光，按照牛顿力学，光的速度应该是1.5c。但爱因斯坦说：不，光速永远是c。

如果光速不变，那么时间和空间就必须"让步"。

**时间膨胀**

如果你坐在一艘以速度 \$v\$ 飞行的飞船上，地面上的人看你的钟，会发现它走得比地面上的钟慢：

\$\$\\Delta t' = \\frac{\\Delta t}{\\sqrt{1 - v^2/c^2}}\$\$

速度越快，时间越慢。这不是钟坏了，而是**时间本身变慢了**。当 \$v\$ 接近 \$c\$ 时，你的时间几乎停止——从你的视角，宇宙的亿万年可能只是一瞬间。

**长度收缩**

运动方向上的长度会缩短：

\$\$L' = L\\sqrt{1 - v^2/c^2}\$\$

飞船在你看来变短了，但在飞船上的人看来，一切正常——缩短的是你所在的世界。

**质能等价**

相对论最著名的推论：质量和能量是同一事物的两种形式：

\$\$E = mc^2\$\$

一小块物质蕴含着巨大的能量。1克物质完全转化为能量，相当于2万吨TNT炸药——这就是原子弹和核电站的物理基础。

这个公式也可以写成更完整的版本：

\$\$E^2 = (mc^2)^2 + (pc)^2\$\$

对于静止的物体，动量 \$p=0\$，就回到 \$E=mc^2\$。对于光子，质量 \$m=0\$，但能量不为零——光子的能量完全来自动量。

**广义相对论（1915年）**

狭义相对论只适用于惯性系，爱因斯坦不满足。他花了十年推广到非惯性系，得到了广义相对论。

核心思想：**引力不是力，而是时空的弯曲**。质量和能量告诉时空如何弯曲，弯曲的时空告诉物质如何运动。

想象一张绷紧的橡皮膜，放一个保龄球上去，膜会凹陷——如果再滚一颗弹珠过去，弹珠会沿弯曲的路径偏转。这不是保龄球在"吸引"弹珠，而是弹珠在沿着弯曲的膜的"直线"走。同样，地球绕太阳运行，不是因为太阳在"拉"地球，而是太阳弯曲了周围的时空，地球沿着弯曲时空中最直的路径运动。

1919年，英国天文学家爱丁顿在日全食期间观测到星光经过太阳附近时确实发生了偏折，偏折角度与广义相对论的预言完全吻合。消息传来，爱因斯坦一夜之间成为世界名人。`,
    principle: `
**1. 狭义相对论的时空观**
同时性是相对的——在一个参考系中同时发生的两件事，在另一个参考系中可能不同时。时间和空间不再是绝对独立的，而是统一为"时空"。这些概念涉及**高中物理·近代物理**中的相对论初步。

**2. 质能方程**
\$E = mc^2\$ 揭示了质量与能量的等价性。核反应中质量的微小亏损对应巨大的能量释放。对应**高三·原子物理**中核能的计算。

**3. 广义相对论的等效原理**
在局部区域，引力和加速度不可区分——这就是等效原理。想象你站在一个封闭的电梯里，感觉到的"重力"可能是地球的引力，也可能是电梯在太空中加速。这个原理是高中物理中万有引力概念的深层延伸。`,
    thinking: `
**为什么重要？**
相对论彻底颠覆了人类对时间和空间的认识。在牛顿的世界里，时间是绝对的、空间是绝对的——宇宙有一个大钟，到处走得一样快。爱因斯坦告诉我们：没有绝对时间，每个观察者有自己的时间；没有绝对空间，空间会弯曲。这不是哲学思辨，而是被无数实验验证的物理事实。GPS卫星上的时钟必须同时修正狭义和广义相对论效应，否则定位误差每天累积约10公里。

**现代应用**
除了GPS，相对论的应用远比想象中广泛：医院里的PET扫描依赖正电子湮灭释放的伽马射线（\$E=mc^2\$的直接验证）；同步辐射光源利用接近光速的电子产生强X射线；金原子核中的相对论效应甚至让金子呈现黄色而非银白色。

**还有什么未解之谜？**
广义相对论在极端条件下——黑洞奇点、宇宙大爆炸的起点——会给出无穷大的结果，物理学家知道这表示理论失效了。需要一个量子引力理论来替代，但引力至今拒绝被量子化。弦理论、圈量子引力等候选方案竞争了半个世纪，没有一个获得实验支持。爱因斯坦的遗产，至今仍是物理学最深的谜。`,
  },
  'stars-004': {
    background: `
1925年的欧洲物理学界，一场风暴正在酝酿。

玻尔的原子模型虽然成功解释了氢光谱，但它有太多"硬塞"的假设——电子只能在特定轨道上运行，跳到另一个轨道时瞬间完成，不能经过中间位置。这套理论能算对一些结果，但没人知道它为什么对。

年轻的德布罗意提出了一个大胆的想法：既然光有波粒二象性，那电子为什么不能也是波？他算出了电子的波长，但这个"物质波"到底是波还是粒子？没人说得清。

这时候，38岁的奥地利物理学家埃尔温·薛定谔出场了。他在瑞士苏黎世大学任教，1925年底读到德布罗意的论文后，灵感爆发。据说他在阿尔卑斯山度假时——身边有一位神秘的女伴——悟出了那个方程。

1926年，他在一系列论文中提出了**薛定谔方程**。这个方程把量子世界从一团迷雾变成了可以计算的数学框架。但他本人大概没想到，自己方程的"正统解释"会让他深感不安——甚至让他发明了物理学史上最有名的猫。`,
    core: `
**薛定谔方程**

薛定谔方程是量子力学的基本方程，就像牛顿第二定律是经典力学的基本方程一样：

\$\$i\\hbar \\frac{\\partial}{\\partial t}\\Psi = \\hat{H}\\Psi\$\$

其中 \$\\Psi\$（读作Psi）是**波函数**，描述粒子在空间中的概率分布；\$\\hat{H}\$ 是哈密顿算符，代表系统的总能量；\$\\hbar\$ 是约化普朗克常数。

这个方程告诉你：**如果知道一个量子系统现在的状态，就能算出它未来任何时刻的状态**——前提是你知道波函数，而不是粒子的确定位置和速度。

因为波函数描述的不是"粒子在哪里"，而是"粒子在某处的概率有多大"。波函数的模的平方 \$|\\Psi|^2\$ 就是粒子出现在那个位置的概率密度。

这意味着：在量子世界里，你永远不能说"电子此刻在A点"，你只能说"电子此刻在A点的概率是30%"。

**薛定谔的猫**

薛定谔对自己的方程被这样解读并不满意。1935年，他提出了一个思想实验来展示这种解释的荒谬性：

想象一个密封的箱子，里面有一只猫、一个放射性原子、一个盖革计数器和一瓶毒气。如果原子衰变，计数器触发，毒气释放，猫死；如果原子不衰变，猫活。

根据量子力学的哥本哈根诠释：在你打开箱子观察之前，原子处于"衰变"和"未衰变"的**叠加态**——两种状态同时存在。既然猫的生死取决于原子状态，那猫也处于"既死又活"的叠加态？

这显然荒唐——宏观的猫不可能同时既死又活。薛定谔的本意是：**如果量子力学的解释在微观上行得通，推到宏观就会产生矛盾**——这说明要么量子力学的诠释有问题，要么微观和宏观之间存在某种尚不清楚的过渡机制。

这个悖论至今没有被完美解决。

**波函数坍缩**

哥本哈根诠释说：观察之前，波函数描述所有可能性的叠加；观察的瞬间，波函数"坍缩"到一个确定的结果。但"观察"是什么意思？需要人的意识参与吗？测量仪器算不算观察者？没有人给出令人满意的定义。

薛定谔的方程本身不包含坍缩——它描述的是波函数平滑、确定性的演化。坍缩是后来硬加进去的"补丁"。这个理论上的不协调，就是所谓的"测量问题"。`,
    principle: `
**1. 波函数与概率解释**
量子力学中，粒子的状态由波函数描述，\$|\\Psi|^2\$ 给出粒子在各位置出现的概率。这和经典力学中"粒子有确定位置"的概念截然不同，是**高中物理·近代物理**中量子力学初步的核心内容。

**2. 叠加原理**
量子系统可以同时处于多个状态的叠加。一个电子可以同时"在左边"和"在右边"，直到被测量才"选择"一个结果。这是量子计算的理论基础——量子比特可以同时是0和1。

**3. 不确定性原理（海森堡）**
薛定谔方程的另一个推论：你不可能同时精确知道粒子的位置和动量：

\$\$\\Delta x \\cdot \\Delta p \\geq \\frac{\\hbar}{2}\$\$

这不是仪器不够精密，而是自然的根本限制。`,
    thinking: `
**为什么重要？**
薛定谔方程是量子力学的核心引擎。没有它，就没有对原子结构的定量理解，没有化学键的计算，没有半导体物理，没有激光理论。现代科技的一切——从芯片到药物设计——都依赖于量子力学的数学框架，而这个框架的第一块砖就是薛定谔方程。

**现代应用**
量子计算直接利用叠加态：经典比特只能是0或1，量子比特可以同时是0和1，多个量子比特组合后，计算空间指数级增长。薛定谔方程也是量子化学的基础——预测分子结构、模拟化学反应、设计新药，都是在解薛定谔方程（近似解）。

**还有什么未解之谜？**
薛定谔的猫至今没被真正"放出来"——测量问题仍然是量子力学最深刻的哲学难题。多世界诠释认为没有坍缩，每次测量都分裂出一个新宇宙；退相干理论认为与环境的相互作用让叠加态快速消失；客观坍缩理论认为坍缩是真实的物理过程……每一种解释都有支持者，但没有一种能被实验证实。近百年过去了，薛定谔的猫仍然既死又活。`,
  },
  'stars-005': {
    background: `
如果你觉得物理学家都是严肃刻板的书呆子，那你一定没听过理查德·费曼。

他年轻时在洛斯阿拉莫斯参与曼哈顿计划，闲着没事就撬同事的保险箱，留下恶作剧纸条；他学画裸体画，在酒吧里画速写；他打邦戈鼓，在巴西狂欢节上演出；他自学开锁，自学西班牙语，自学画画——每一项都玩到了专业水准。

但在所有"不正经"的表象下面，费曼是20世纪最深刻的物理头脑之一。他1965年获得诺贝尔奖，表彰他在量子电动力学（QED）中的工作。但比诺奖更重要的是他发明的一个工具——**费曼图**，它让原本需要写满几页纸的复杂计算，变成了一张简单直觉的图画。

费曼还是教育大师。他的《费曼物理学讲义》被公认为有史以来最好的物理教材之一。他有一个著名的学习方法：**如果你不能用简单的话解释一个概念，说明你没有真正理解它**。`,
    core: `
他不是不正经，而是在用最直觉的方式理解最深的问题。对费曼来说，物理不是写在纸上的公式，而是可以画出来的图、可以讲出来的故事。这种直觉式的思维方式，催生了他最伟大的发明。

**费曼图：把方程变成画**

在量子电动力学中，计算两个电子的散射概率需要处理极度复杂的积分——一个看似简单的物理过程，数学上可能涉及几十项，每一项都有多重积分和无穷级数。物理学家被这些数学淹没，常常算错。

费曼的天才在于：他发明了一种图形记号，把每一项数学计算对应成一幅画。

在费曼图中：
- 直线代表电子
- 波浪线代表光子
- 顶点代表电子发射或吸收光子
- 时间从左到右流动

比如，两个电子靠近时交换一个光子（虚光子），就画成两条直线之间连一条波浪线。这幅图对应的数学表达式精确可算，而且一目了然——**电子之间通过交换光子来传递电磁力**。

费曼图不是"示意图"，而是**精确的计算工具**。每一幅图对应一个数学项，所有可能的图加起来就是完整的物理结果。费曼图把原本需要几页纸的计算压缩成几行——不是偷懒，而是抓住了物理的本质。

**纳米技术的先知**

1959年，费曼在加州理工做了一个演讲，题目叫《在底部还有很大空间》。他问：能不能把大英百科全书全部写在一颗针尖上？

他算了一下：如果每个字母用6个原子编码，针尖上完全可以容纳整套百科全书。他预言人类终将能够在原子尺度上操控物质——这就是后来的**纳米技术**。

当时没人当真。但40年后，2000年美国正式启动国家纳米技术计划，费曼的演讲被视为这个领域的开山宣言。

**挑战者号调查**

1986年，航天飞机"挑战者号"在升空73秒后爆炸，7名宇航员遇难。费曼被邀请加入调查委员会。其他成员在听证会上听报告、看文件，费曼做了一件所有人都没想到的事：

他要了一杯冰水和一个O型橡胶圈（密封航天飞机助推器的零件），把橡胶圈浸入冰水，拿出来后轻轻一捏——橡胶圈在低温下失去了弹性，无法密封。

就这么简单。事故原因就是发射当天气温过低，O型圈失效。费曼用一杯冰水，让所有复杂的官僚报告哑口无言。`,
    principle: `
**1. 量子电动力学（QED）**
QED描述电子和光子的相互作用，是迄今为止最精确的物理理论——理论预测与实验测量吻合到小数点后11位。费曼图是QED的核心计算工具，涉及**高中物理·电磁学**中电磁相互作用的量子本质。

**2. 虚粒子与力的传递**
在量子场论中，力不是"超距作用"，而是通过交换虚粒子来传递。电磁力交换虚光子，强力交换虚胶子。费曼图直观展示了这个过程，是**近代物理**中粒子物理的入门概念。`,
    thinking: `
**为什么重要？**
费曼图不仅是计算工具，更是一种思维方式——**用图像理解方程**。费曼证明了，物理不只是数学推导，还需要直觉和想象力。他的思想影响了整个理论物理学：今天从粒子物理到凝聚态物理，几乎每个领域都在用费曼图。

**现代应用**
费曼图是粒子物理标准模型的计算基础——每一次在大型强子对撞机（LHC）上分析数据，都在用费曼图计算背景。在凝聚态物理中，费曼图用来描述电子在固体中的行为，直接关系到超导材料的设计。

**还有什么未解之谜？**
费曼在晚年承认，没人真正理解量子力学——"我想我可以安全地说，没有人理解量子力学。"他自己发展了路径积分（另一种量子力学的表述），试图给出更直觉的理解，但测量问题依然悬而未决。费曼也许是最接近量子力学"本质"的人，但他也坦诚：那扇门后面，我们还什么都没看到。`,
  },
  'stars-006': {
    background: `
1891年，24岁的玛丽亚·斯克沃多夫斯卡坐了三天三夜的火车，从波兰华沙来到法国巴黎。她带着微薄的积蓄和一个疯狂的想法：上大学。

那时的波兰被俄国统治，女性不能上大学。玛丽亚省下每一分钱，白天在索邦大学听课，晚上在冰冷的阁楼里自学，有时穷到只靠面包和水度日。她以物理和数学双学位毕业，成绩都是全班第一。

1894年，她遇到了皮埃尔·居里——一个同样痴迷科学的法国物理学家。两人因科学相识、相爱、结婚，开始了物理学史上最伟大的合作。

1896年，贝克勒尔偶然发现铀盐能让底片感光——某种看不见的射线从铀中自发地发出。玛丽亚决定以此作为博士课题。她很快发现，一种叫"沥青铀矿"的天然矿石，发出的射线比纯铀还强——这意味着矿石里藏着一种未知元素，放射性比铀强得多。

她要找到它。`,
    core: `
**从矿渣中找元素**

居里夫妇面临的挑战令人绝望：沥青铀矿中未知元素的含量极低——不到百万分之一。要从数吨矿石中提炼出零点几克纯物质，需要的不是天才的灵感，而是凡人难以想象的毅力。

他们没有实验室。学校给了他们一间废弃的棚屋，冬天滴水成冰，夏天闷热如蒸笼。皮埃尔负责测量放射性，玛丽亚负责化学提炼——搅拌大锅里沸腾的矿渣，用巨大的铁棒翻动几十公斤的溶液，日复一日。

整整四年。

1898年，他们先后宣布发现了两种新元素：**钋**（以玛丽亚的祖国波兰命名）和**镭**（意为"射线"）。但宣布发现是一回事，拿到纯品是另一回事。为了制备足够多的纯镭来证明它的存在，玛丽亚又花了好几年处理了数吨矿渣。

1902年，她终于从数吨沥青铀矿中提炼出0.1克纯氯化镭。这0.1克淡蓝色的粉末，在黑暗中发出幽幽的荧光——镭自己在发光。

**两次诺贝尔奖**

1903年，居里夫妇和贝克勒尔共获诺贝尔物理学奖——玛丽亚是第一位女性诺贝尔奖得主。1906年，皮埃尔在巴黎街头被马车撞倒身亡，年仅46岁。玛丽亚悲痛欲绝，但接过了丈夫的教席，成为索邦大学第一位女教授。

1911年，她因发现镭和钋、分离出纯镭，再次获得诺贝尔奖——这次是化学奖。她是历史上第一位两次获得诺贝尔奖的人，也是至今唯一在两个不同科学领域获奖的人。

**致命的发现**

居里夫人不知道的是，那些幽蓝的荧光正在杀死她。她常年把装有镭的试管放在口袋里，甚至放在床头当夜灯。她的手指被辐射灼伤，皮肤干裂，但当时没人知道辐射的危害。

1934年，居里夫人因再生障碍性贫血去世，享年66岁。直到今天，她的实验笔记本仍然带有强烈的放射性，被存放在铅盒中——想查阅的人必须穿防护服。`,
    principle: `
**1. 放射性衰变**
某些不稳定的原子核会自发地发射粒子或电磁波，转变为更稳定的核素。主要类型：
- **α衰变**：发射氦核，质量数减4，原子序数减2
- **β衰变**：发射电子或正电子，原子序数增1或减1
- **γ衰变**：发射高能光子，核素不变但能量降低

这是**高三物理·原子核**的核心内容。

**2. 半衰期**
放射性核素的量减半所需的时间是恒定的，叫半衰期 \$T_{1/2}\$。镭-226的半衰期约1600年。放射性强度随时间指数衰减：

\$\$N = N_0 \\cdot 2^{-t/T_{1/2}}\$\$

对应**高三·原子物理**中放射性衰变的计算。`,
    thinking: `
**为什么重要？**
居里夫人的工作开创了放射性和核物理两个领域。镭的发现直接催生了放射治疗——用辐射杀死癌细胞，至今仍是癌症治疗的三大手段之一。更重要的是，她证明了一种元素可以自发地变成另一种元素——这在当时是革命性的，因为化学家们一直认为元素是不可变的。

**现代应用**
放射治疗、核医学成像（PET、SPECT）、核电站、放射性年代测定（碳-14测年法）——所有这些都始于居里夫人的发现。她在一战期间还推动建立了流动X射线车，在前线为伤员检查弹片位置，被称为"小居里"。

**还有什么未解之谜？**
辐射的生物学效应至今不是完全清楚。低剂量辐射是否真的有害（线性无阈值模型是否正确）？辐射诱导的DNA损伤修复机制如何精确运作？这些问题直接影响核能政策和辐射防护标准。而更深层的谜题是：为什么某些原子核稳定，某些不稳定？核力的精确描述至今仍是理论物理的难题。`,
  },
  'stars-007': {
    background: `
1911年，26岁的丹麦物理学家尼尔斯·玻尔来到剑桥，投奔J.J.汤姆孙——电子的发现者。他满心期待能和这位大师讨论原子结构，但汤姆孙对这位年轻的外国人兴趣不大。

玻尔转而去了曼彻斯特，投奔卢瑟福。卢瑟福刚在1909年用α粒子轰击金箔，发现了原子核——原子中心有一个极小的、带正电的核，电子在核外运行。

但这个模型有一个致命问题：按照经典电磁学，做加速运动的电荷（绕核转动的电子）会不断辐射电磁波，损失能量，最终在 \$10^{-11}\$ 秒内螺旋坠入原子核。**按经典理论，原子不可能稳定存在。**

可原子明明就在那里。你活着，我活着，整个世界都在——这本身就是一个需要解释的事实。

玻尔决定做一件大胆的事：**直接否定经典物理的适用性**。他引入量子规则，硬性规定电子只能在特定轨道上运行，不辐射能量。这在当时几乎是"不讲道理"的——但他算出来的结果，和实验数据吻合得惊人地好。`,
    core: `
**玻尔的三个假设**

1913年，玻尔提出了氢原子的量子模型，基于三个假设：

1. **定态假设**：电子只能在特定的圆形轨道上运行，每个轨道对应一个确定的能量。在这些轨道上，电子不辐射能量——这直接违背经典电磁学，但玻尔说"就是这样"。

2. **跃迁假设**：电子从一个轨道跳到另一个轨道时，会发射或吸收一个光子。光子的能量等于两个轨道的能量差：

\$\$h\\nu = E_2 - E_1\$\$

其中 \$h\$ 是普朗克常数，\$\\nu\$ 是光子频率。电子从高能级跳到低能级就发光，从低能级跳到高能级就吸光——这就解释了原子光谱为什么是离散的线而不是连续的带。

3. **角动量量子化**：电子的轨道角动量必须是 \$h/2\\pi\$ 的整数倍：

\$\$L = n\\frac{h}{2\\pi}, \\quad n = 1, 2, 3, \\ldots\$\$

这个条件决定了哪些轨道是"允许"的。

**惊人的成功**

玻尔用这三个假设算出了氢原子光谱的所有谱线波长，与实验测量完全吻合。此前，巴尔末等人只发现了氢光谱的经验公式，但没人知道为什么会这样。玻尔第一次给出了物理解释。

他还算出了氢原子的基态轨道半径（玻尔半径）\$a_0 \\approx 5.3 \\times 10^{-11}\$ m，和电离能 \$E_1 \\approx 13.6\$ eV——这些数字和实验值几乎完全一致。

**哥本哈根诠释**

玻尔不只是建立了一个原子模型，他还建立了一个学派。1920年，他在哥本哈根创建理论物理研究所，吸引了海森堡、泡利、狄拉克等最优秀的年轻物理学家。他们共同发展了量子力学的完整理论，并给出了被称为"哥本哈根诠释"的哲学框架：微观世界本质上是不确定的，波函数描述的是概率，观测会导致坍缩。

爱因斯坦坚决反对这种诠释——"上帝不掷骰子"。玻尔回应："爱因斯坦，不要告诉上帝该怎么做。"这场辩论持续了几十年，至今没有最终答案。`,
    principle: `
**1. 玻尔原子模型**
电子在量子化轨道上运行，跃迁时发射或吸收特定频率的光。这是**高三物理·原子结构**的核心内容，是量子力学建立前的关键过渡模型。

**2. 能级与光谱**
原子的能量是量子化的，只能取特定值——能级。电子跃迁产生的不连续光谱（线光谱）是能级存在的直接证据。对应**高三·原子物理**。`,
    thinking: `
**为什么重要？**
玻尔模型是第一个成功的量子原子模型。虽然它只对氢原子精确成立，对多电子原子需要近似处理，但它确立了"量子化"这个概念在微观物理中的核心地位。没有玻尔的勇敢假设，就不会有后来的薛定谔方程和完整的量子力学。

**现代应用**
原子钟利用电子跃迁的精确频率定义时间标准——铯-133原子基态超精细跃迁的9192631770个周期定义为1秒。LED灯利用电子在半导体能级间的跃迁发光，颜色取决于能级间距。激光的工作原理——受激辐射——最早也是爱因斯坦在玻尔模型基础上预言的。

**还有什么未解之谜？**
玻尔模型虽然成功，但本质上是一个"半经典"理论——它把经典轨道和量子规则硬拼在一起，缺乏自洽的理论基础。完整的量子力学（薛定谔方程）取代了玻尔轨道的概念，用"电子云"代替了"电子轨道"。但量子力学的诠释问题——波函数到底在描述什么——玻尔和爱因斯坦的争论至今仍是开放的。`,
  },
  'stars-008': {
    background: `
1963年，21岁的牛津大学毕业生斯蒂芬·霍金被诊断出肌萎缩侧索硬化症（ALS），医生说他最多还能活两年。

他没有等死。他去了剑桥读博士，研究宇宙学——这个连正常人都觉得头疼的领域。疾病让他的身体逐渐瘫痪：先是走路需要拐杖，然后坐上轮椅，最后只剩几根手指和面部肌肉能动。

但他的大脑完好无损。当身体被困在轮椅上时，他的思想正在穿越黑洞的事件视界，探索时空的终极秘密。

霍金后来活了整整55年，远超医生的预言。他成为了世界上最著名的物理学家——不仅因为他的科学成就，也因为他用残破的身体证明了人类精神的韧性。他的《时间简史》卖出了2500万册，让"黑洞""奇点""大爆炸"这些词走进了千家万户。`,
    core: `
**黑洞：宇宙的终极牢笼**

黑洞是广义相对论的预言：当一颗大质量恒星燃尽燃料，引力坍缩，没有任何力量能阻止它收缩成一个点——奇点。奇点周围有一个边界叫**事件视界**，任何东西（包括光）一旦越过这个边界，就永远无法逃出。

事件视界的半径叫**史瓦西半径**：

\$\$r_s = \\frac{2GM}{c^2}\$\$

其中 \$M\$ 是黑洞质量，\$G\$ 是万有引力常数，\$c\$ 是光速。对太阳质量的黑洞，\$r_s\$ 约3公里。

按照经典广义相对论，黑洞只进不出，永远只会变大——它是宇宙中最黑暗、最贪婪的存在。

**霍金辐射：黑洞不黑**

1974年，霍金做了一个让所有人震惊的计算。

他用量子场论分析了黑洞视界附近的真空，发现：视界边缘会不断产生虚粒子对（正反粒子对）。正常情况下，虚粒子对瞬间出现又瞬间湮灭，不留痕迹。但如果其中一个粒子刚好在视界内侧，另一个在外侧——内侧的粒子坠入黑洞，外侧的粒子逃逸到无穷远。

结果：**黑洞在向外发射粒子**——这就是**霍金辐射**。

更惊人的是，霍金辐射带有温度：

\$\$T_H = \\frac{\\hbar c^3}{8\\pi G M k_B}\$\$

黑洞质量越大，温度越低。太阳质量黑洞的温度只有约 \$6 \\times 10^{-8}\$ K，远低于宇宙微波背景辐射的2.7K——所以实际上还在吸热。但如果黑洞足够小（比如微型黑洞），温度可以非常高，辐射非常剧烈，黑洞会快速"蒸发"——最终在猛烈的爆发中消失。

**这意味着：黑洞不是永恒的。** 它会慢慢蒸发，最终消失。宇宙中最"不灭"的东西，原来也有寿命。

**信息悖论**

霍金辐射带来了一个深刻的问题：如果一个黑洞蒸发殆尽，之前掉入黑洞的信息去了哪里？

量子力学说信息永远不会真正消失。但如果黑洞真的完全蒸发，那些信息就像被烧掉的书一样不可恢复。这就是**黑洞信息悖论**——量子力学和广义相对论在这里发生了正面冲突。

霍金最初认为信息确实丢失了，但2004年他改变立场，承认信息可能通过霍金辐射的微妙关联被保存下来。但具体的保存机制至今无人能说清——这需要一套完整的量子引力理论，而我们还没有。`,
    principle: `
**1. 事件视界与逃逸速度**
黑洞视界处的逃逸速度等于光速。这是**高一物理·万有引力**中第二宇宙速度概念的极端推广。

**2. 虚粒子与量子真空**
量子力学中，真空不是"什么都没有"，而是充满了虚粒子对的涨落。这是**高三·近代物理**中量子场论的初步概念，也是海森堡不确定性原理的后果——能量可以在极短时间内"借来"，只要 \$\\Delta E \\cdot \\Delta t \\leq \\hbar/2\$。

**3. 黑洞热力学**
霍金证明黑洞有温度和熵，熵与视界面积成正比。这是把热力学、量子力学和广义相对论三个领域联系在一起的深刻结果。`,
    thinking: `
**为什么重要？**
霍金辐射是20世纪理论物理最重要的发现之一，因为它第一次把量子力学和引力放在同一个问题里，得到了一个虽然不完整但自洽的结果。它证明了：**量子和引力不是不能对话的，只是我们还没学会完整的语言。** 霍金为后来所有的量子引力研究划定了起跑线。

**现代应用**
霍金辐射对日常应用没有直接影响——它太微弱了。但黑洞热力学催生了物理学中最疯狂的猜想之一：**全息原理**——一个三维空间区域的全部信息可能被编码在其二维边界上。这个原理正在深刻影响量子信息、凝聚态物理甚至量子引力的研究。

**还有什么未解之谜？**
黑洞信息悖论至今悬而未决。2019年事件视界望远镜（EHT）拍摄了人类第一张黑洞照片——M87星系中心的超大质量黑洞——但那只是观测验证了广义相对论，对信息悖论毫无帮助。真正需要的，是一套能在奇点处取代广义相对论的量子引力理论。弦论和圈量子引力各有所长，但都还没有给出可检验的预言。霍金用他的辐射照亮了一扇门，但门后面是什么，我们还看不到。`,
  },
  'stars-009': {
    background: `
1935年，24岁的钱学森从上海登上了去美国的轮船，怀里揣着庚子赔款奖学金和满腔抱负。他到了麻省理工学院，又转到加州理工，拜在"超音速飞行之父"冯·卡门门下读博士。

他太优秀了。28岁和导师一起提出"卡门-钱近似"公式，解决了超音速飞行的空气动力学难题。36岁成为麻省理工最年轻的终身教授。他是美国喷气推进实验室（JPL）的创始人之一，参与美国最早的火箭研究，拥有最高级别的安全许可。

但1950年，一切都变了。麦卡锡主义席卷美国，钱学森被指控为共产党员，安全许可被吊销，遭到软禁。他家的电话被监听，信件被拆检，出门有人跟踪。

他多次要求回国，都被拒绝。美国海军次长丹·金布尔据说说过一句著名的话："他抵得上五个师的兵力，我宁可枪毙他也不让他回国。"

经过五年的拉锯和外交谈判，1955年，在中国政府的斡旋下，钱学森终于踏上了回国的轮船。他带走的，只有脑子里的知识和对祖国的一腔热血。`,
    core: `
回国后的钱学森，面临的是一个几乎从零开始的中国航天。

没有大型计算机，没有风洞，没有精密加工设备。他用的工具是计算尺和算盘。研究人员在他指导下，用手摇计算机算了整整几个月，完成了一枚导弹的弹道计算。

1956年，钱学森起草了《建立我国国防航空工业意见书》，这是中国航天事业的蓝图。他组建了国防部第五研究院——中国第一个导弹研究机构。

他最大的贡献不是某个具体技术，而是**系统工程**的方法论。他把极其复杂的航天工程拆解为多个子系统，每个子系统独立攻关，最终整合成一个协调运转的整体。这种思路在中国此后的所有重大工程中——从两弹一星到载人航天——都被沿用。

1960年，中国第一枚仿制导弹发射成功。1964年，中国第一颗原子弹爆炸。1966年，导弹核武器试验成功。1970年，中国第一颗人造卫星"东方红一号"升空——中国成为世界上第五个独立发射卫星的国家。

从1955年回国到1970年东方红升空，15年。一个一穷二白的国家，在钱学森和千千万万科研人员的努力下，完成了从零到太空的跨越。`,
    principle: `
**1. 火箭推进原理**
火箭靠向后喷射高速气体获得向前的推力，遵循动量守恒。这就是**高一物理·动量守恒**的经典应用——系统的总动量不变，气体向后动量增加，火箭向前动量等量增加。

火箭的最终速度由齐奥尔科夫斯基公式决定：

\$\$\\Delta v = v_e \\ln \\frac{m_0}{m_f}\$\$

其中 \$v_e\$ 是喷气速度，\$m_0\$ 是初始质量，\$m_f\$ 是燃料耗尽后的质量。要提高速度，要么提高喷气速度，要么增加燃料比例——这就是多级火箭的原理，每级用完就扔掉，减轻 \$m_f\$。

**2. 轨道力学**
卫星入轨需要达到第一宇宙速度 \$v_1 = \\sqrt{gR} \\approx 7.9\$ km/s。这是**高一·万有引力**中圆周运动和引力的综合应用。`,
    thinking: `
**为什么重要？**
钱学森的故事不只是科学故事，也是一段关于选择和信念的故事。他放弃了美国最优越的科研条件，回到一穷二白的祖国，把毕生所学变成了一个国家的航天脊梁。他的系统工程思想，至今仍是中国工程管理的核心方法论。

**现代应用**
今天的中国航天——嫦娥探月、天问火星、天宫空间站——都可以追溯到钱学森打下的地基。他的系统工程方法论不仅用于航天，还被推广到经济规划、社会管理等领域。他晚年提出的"沙产业"理论，试图用科学技术改造沙漠，至今仍在西北地区实践。

**还有什么未解之谜？**
人类能否走出地球？钱学森那一代人把卫星送上了天，但载人深空探测——火星登陆、小行星采矿、星际旅行——仍然面临巨大的技术挑战。可重复使用火箭正在降低发射成本，但太空辐射、长期失重、心理孤立等问题仍未完全解决。钱学森的征途是星辰大海，而这条路，还在延伸。`,
  },
  'stars-010': {
    background: `
1974年之前，粒子物理学界处于一种微妙的焦虑中。

夸克模型已经提出十年了——盖尔曼认为质子和中子由更小的夸克组成，上夸克、下夸克、奇异夸克，三个家族。理论看起来很美，但第四种夸克（粲夸克）的存在只有理论推测，没有任何实验证据。

更让人不安的是：当时流行的"新粒子"理论预言了一批新粒子，但实验上什么都没找到。一些人开始怀疑，也许粒子物理已经走进了死胡同——也许夸克模型就是错的。

这时候，一个华裔物理学家站了出来。他叫丁肇中，当时在麻省理工和布鲁克海文国家实验室工作。他有一个特点：**别人觉得不可能的实验，他偏要做**。

他不是理论家——他是实验物理学家，信奉一条铁律：**物理学是实验的科学，理论再漂亮，实验说了算。**`,
    core: `
**J粒子的发现**

丁肇中的计划是：用高能质子束轰击铍靶，产生大量次级粒子，然后在产物中寻找一种特殊的新粒子——它衰变为正负电子对，而且质量比较大。

这个实验的难度在于"信噪比"。高能碰撞产生的粒子数以亿计，而丁肇中要找的信号可能只有几个——就像在一场暴风雪中寻找一片特定的雪花。

他做了几件别人不愿意做的事：

1. **极严格的筛选**：他把探测器的质量分辨率调到极高，只接受极窄的能量范围内的信号。大多数同行觉得这样做太保守，会漏掉信号——但丁肇中认为，新粒子的信号应该非常尖锐。

2. **极耐心地积累数据**：他花了数月时间，一点一点积累碰撞事件，仔仔细细地筛选。

1974年夏天，数据开始出现异常：在3.1 GeV（十亿电子伏特）的能量处，出现了一个极其尖锐的峰——窄到几乎是一条竖线。在粒子物理中，这样的峰意味着**一个新粒子**的存在。

丁肇中不敢相信。他反复检查，排除了所有可能的系统误差，让不同团队独立验证。结果一致：这个峰是真实的。

这个粒子的质量约为质子的3.3倍，寿命却异常长——比同质量的其他粒子长约1000倍。就像一颗本该秒级爆炸的炸弹，竟然安安静静地放了一个小时。

1974年11月，丁肇中宣布发现J粒子。几乎同时，斯坦福直线加速器中心的里克特团队也独立发现了同一个粒子（他们叫它ψ粒子）。两个实验室使用了完全不同的方法，得到了相同的结果。

这个发现被称为"十一月革命"——它彻底改变了粒子物理的格局。J/ψ粒子的存在证实了第四种夸克（粲夸克）的存在，为后来的粒子物理标准模型奠定了关键基础。丁肇中和里克特共享了1976年诺贝尔物理学奖。

**AMS实验：从粒子到宇宙**

丁肇中没有躺在诺奖上休息。1994年，他提出了一个更疯狂的实验：把一个精密的粒子探测器送到国际空间站上，在太空中探测宇宙射线中的反物质和暗物质。

这就是**阿尔法磁谱仪（AMS）**。它重7.5吨，包含6种探测器，是国际空间站上最大的科学仪器。2011年，AMS-02由奋进号航天飞机送入太空。

AMS至今已收集了超过2000亿条宇宙射线数据，发现了一些反常信号——比如正电子比例异常偏高——这可能（仅仅是可能）是暗物质湮灭的迹象。

丁肇中说："实验的目的是发现未知。如果你已经知道答案，那就不需要做实验了。"`,
    principle: `
**1. 夸克模型与粲夸克**
质子和中子由夸克组成。J/ψ粒子由粲夸克和反粲夸克组成，其极长的寿命可以用**OZI规则**和色荷量子数来解释。在粒子物理中，一个共振态的信号强度用散射截面描述，其随能量的变化遵循布雷特-维格纳公式：

\$\$\\sigma(E) \\propto \\frac{1}{(E - E_0)^2 + \\Gamma^2/4}\$\$

其中 \$E_0\$ 是共振粒子的质量，\$\\Gamma\$ 是衰变宽度——\$\\Gamma\$ 越小，峰越尖锐，粒子寿命越长。J/ψ粒子的 \$\\Gamma\$ 极小（约93 keV），所以3.1 GeV处出现了那条几乎竖直的尖峰。这是**高三·近代物理**中粒子物理初步的核心内容。

**2. 高能物理实验方法**
加速器让粒子以接近光速碰撞，产物中的新粒子通过衰变产物来推断——不直接"看到"新粒子，而是从衰变产物的能量和动量反推。质量由能量-动量关系决定：

\$\$E^2 = (pc)^2 + (mc^2)^2\$\$

对应**高三·相对论**和**粒子物理**。`,
    thinking: `
**为什么重要？**
丁肇中的工作代表了实验物理的精神：**理论可以猜，但自然说了算**。J粒子的发现不是理论的胜利，而是实验的胜利——理论家们没有预料到这个粒子，是实验把它从数据的海洋中捞了出来。这种"用数据推翻教条"的精神，是物理学最珍贵的传统。

**现代应用**
粒子加速器技术已经渗透到日常领域：医院里的PET扫描和质子治疗用的就是粒子加速器的缩小版。同步辐射光源为材料科学和药物设计提供强大工具。而AMS收集的宇宙射线数据，正在帮助科学家理解宇宙中正反物质的不对称性。

**还有什么未解之谜？**
AMS发现的正电子异常，到底是暗物质的信号，还是脉冲星等天体物理来源？目前无法确定。更根本的问题是：为什么宇宙中的物质远多于反物质？标准模型中的CP破坏不足以解释这种不对称——一定存在某种超出标准模型的新物理。丁肇中仍然在太空中寻找答案。`,
  },
  'think-001': {
    background: `
1704年，牛顿出版《光学》，宣布光是粒子。他不是随便说的——他用自己的名字命名了光的粒子说，而牛顿的名字在18世纪的科学界，基本上等于"真理"。

牛顿的理由很直观：光沿直线传播，像子弹；光在镜面上反射，像台球弹回；光的不同颜色可以用不同大小的粒子来解释。粒子说统治了整个18世纪。

但总有人不服。荷兰物理学家惠更斯早在1678年就提出：光是一种波。他的论据是，两束光交叉后互不干扰——如果光是粒子，交叉时应该像两群子弹相撞一样混乱，但事实是光穿过光，完好无损。只有波能做到这一点：两列水波交叉后，各自继续前进，互不影响。

19世纪初，托马斯·杨用双缝实验给了粒子说致命一击：一束光通过两条窄缝后，在屏幕上形成明暗相间的条纹——**干涉图样**。只有波才会干涉，粒子不可能。此后，麦克斯韦方程组更是从理论上证明了光是电磁波。

到19世纪末，波动说似乎已经赢得了最终胜利。然后，1905年，爱因斯坦说光是粒子。

三百年了，这场仗还没打完。`,
    core: `
**波动说的辉煌**

杨氏双缝实验是波动说的铁证。一束单色光通过两条相距很近的缝，在远处的屏幕上出现的不是两道亮纹，而是明暗交替的条纹——亮处是两列波峰叠峰（相长干涉），暗处是波峰叠谷（相消干涉）。只有波才有这种行为，粒子绝不会。

麦克斯韦在1865年用数学证明了光是电磁波——振荡的电场和磁场互相激发、以光速传播。赫兹在1888年用实验证实了电磁波的存在。波动说似乎完胜。

**爱因斯坦的反击**

1900年，普朗克在研究黑体辐射时被迫假设能量是不连续的，只能一份一份地取值。但他觉得这只是数学技巧，不代表光真的是粒子。

爱因斯坦更激进。1905年，他指出：如果光的能量是一份一份的（光子），光电效应的所有反常现象立刻得到解释。频率决定每份的能量，强度决定份数——频率不够，单份能量不够，再多份也打不出电子；频率够高，一份就够，瞬间完成。

波动说对此哑口无言。

**德布罗意的统一**

1924年，路易·德布罗意提出了一个疯狂的想法：既然光既是波又是粒子，那电子为什么不能既是粒子又是波？他推导出物质波的波长：

\$\$\\lambda = \\frac{h}{p}\$\$

其中 \$h\$ 是普朗克常数，\$p\$ 是粒子的动量——简单说，越重的粒子波长越短，日常物体波长短到完全察觉不到，但电子的波长刚好可以被实验观测到。

1927年，戴维森和革末用电子束照射镍晶体，果然得到了类似X射线衍射的图样——电子真的在"干涉"！粒子也具有波动性。

**波粒二象性**

最终的答案不是"光是波"或"光是粒子"，而是：**光既是波又是粒子**——更准确地说，它既不像经典的波，也不像经典的粒子，它是某种全新的东西。在传播时它表现为波（干涉、衍射），在与物质交换能量时它表现为粒子（光电效应、康普顿散射）。

这不是"有时候这样有时候那样"的投机取巧，而是微观世界的根本特征——**波粒二象性**，量子力学的基石之一。`,
    principle: `
**1. 杨氏双缝实验**
两束相干光叠加，光程差为波长的整数倍时相长干涉（亮），为半波长的奇数倍时相消干涉（暗）。这是**高二物理·光的干涉**的核心实验，也是波动说的决定性证据。

**2. 光电效应**
光子的能量 \$E = h\\nu\$，金属有逸出功 \$W\$。只有 \$h\\nu > W\$ 才能打出电子，与光强无关。这是**高三物理·光电效应**的核心，也是粒子说的决定性证据。

**3. 物质波**
所有物质都具有波动性，波长 \$\\lambda = h/p\$。日常物体动量大、波长极短，波动性不可察觉；电子动量小，波长在原子尺度，可以被观测。这是**高三·物质波**的基础概念。`,
    thinking: `
**为什么重要？**
波粒二象性是量子力学最根本的概念。它打破了经典物理中"要么是波要么是粒子"的二元思维，告诉我们：微观世界的本质超越了人类宏观经验的分类。这不是物理学的失败，而是认识论的升级——我们用旧概念描述新现象，难免会有矛盾，但矛盾本身指向了更深的真相。

**现代应用**
电子显微镜利用电子的波动性成像，分辨率远超光学显微镜——因为电子波长比可见光短得多。中子衍射用于探测材料结构。量子计算机则直接操控量子态的叠加性质——波粒二象性不再是抽象的哲学讨论，而是工程实践。

**还有什么未解之谜？**
在单光子双缝实验中，一个一个地发射光子，屏幕上每次只出现一个点（粒子性），但积累足够多的点后，干涉图样依然出现（波动性）。单个光子到底是怎么"同时通过两条缝"的？或者说，"通过缝"这个说法本身就有问题？波函数到底在描述什么——是物理实在，还是信息？这个问题的答案，至今没人能说清。`,
  },
  'think-002': {
    background: `
1927年10月，比利时布鲁塞尔，第五次索尔维会议。

这是物理学史上最星光熠熠的聚会：爱因斯坦、玻尔、海森堡、薛定谔、狄拉克、普朗克、居里夫人、洛伦兹……29个人里有17个已经或即将获得诺贝尔奖。会议的主题是"电子和光子"，但真正的战场只有一个——量子力学的意义到底是什么。

玻尔在会上阐述了哥本哈根诠释：微观世界本质是不确定的，粒子的位置和动量不可能同时精确知道，测量前粒子没有确定的状态，只有概率分布。物理学的终极目标不再是预言"会发生什么"，而是计算"可能发生什么的概率"。

爱因斯坦坐不住了。

他站起来反驳：物理学的使命是描述客观实在，而不是概率。如果你告诉我"电子在某个位置的概率是30%"，那不是物理学，那是无知的掩饰。在概率背后，一定有更深层的确定性规律——只是我们还没发现罢了。

这场辩论在会议上激烈交锋了几天。爱因斯坦每天提出一个思想实验试图反驳量子力学，玻尔每天晚上彻夜思考，第二天逐一化解。会议结束时，两人谁也没说服谁。

但这场辩论只是开始。它持续了将近三十年，直到爱因斯坦去世。`,
    core: `
**爱因斯坦的论点：物理实在性**

爱因斯坦的核心论点不是"量子力学算错了"——他承认量子力学的计算结果是对的。他反对的是量子力学的**诠释**：如果粒子在被测量前真的没有确定的位置，那意味着客观实在不存在——世界是由观察行为"创造"出来的，这太荒谬了。

1935年，爱因斯坦和波多尔斯基、罗森合作，提出了著名的**EPR悖论**，试图证明量子力学是不完备的。

EPR的论证是这样的：假设两个粒子A和B在某个时刻相互作用后分开，各自飞向远方。根据量子力学，A和B的某些物理量（比如自旋）处于"纠缠态"——测量A的自旋，B的自旋立刻确定，无论它们相距多远。

爱因斯坦说：这有两种可能。第一，A和B之间有某种超光速的"心灵感应"——但相对论不允许超光速传递信息。第二，A和B的自旋在分开时就已经确定了，只是量子力学没描述出来——这意味着量子力学不完备，少了某些"隐变量"。

爱因斯坦选了第二种。他坚信：**物理实在应该独立于观察而存在**，粒子的属性在测量前就已经有确定值，不是"测量创造了现实"。

**玻尔的回应：互补性**

玻尔的回应出人意料。他承认EPR的论证在逻辑上没有漏洞，但他不同意"物理实在"的定义。玻尔说：你不能把微观粒子想象成"本来就有确定位置的东西"——在量子世界，"位置"这个概念只有在测量的语境下才有意义。测量之前，问"电子在哪里"就像问"黑暗中的光是什么颜色"——问题本身就没有意义。

玻尔的哲学被称为**互补原理**：波和粒子、位置和动量，这些概念不是矛盾的，而是互补的——你用不同的实验装置看到不同的侧面，没有一个侧面能给出完整的描述。

**贝尔不等式：实验判了谁赢**

辩论在哲学层面僵持了三十年。1964年，爱尔兰物理学家约翰·贝尔提出了一个数学不等式——**贝尔不等式**——把哲学争论变成了可检验的实验。

贝尔证明：如果爱因斯坦是对的（存在隐变量，粒子属性预先确定），那某些关联测量的结果必须满足一个数学约束。如果量子力学是对的（没有隐变量，纠缠是真正的非定域关联），那这个约束可以被违反。

1982年，法国物理学家阿斯佩做了第一个精确的贝尔不等式检验实验。结果：**贝尔不等式被违反了**。此后三十多年，多个实验以越来越高的精度重复了这一结果，漏洞逐一封堵。

结论越来越明确：**爱因斯坦错了**。量子纠缠不是因为我们忽略了隐变量，而是微观世界真的存在非定域的关联——两个粒子之间的联系不能被任何局域的"预先设定"来解释。

但这是否意味着玻尔完全赢了？也不尽然。贝尔不等式的违反排除了"局域隐变量理论"，但并不排除"非局域隐变量"（如玻姆力学）。量子力学的诠释问题，至今仍有多种竞争方案。`,
    principle: `
**1. 海森堡不确定性原理**
粒子的位置和动量不能同时精确测量，\$\\Delta x \\cdot \\Delta p \\geq \\hbar/2\$。这不是仪器精度的问题，而是自然的根本限制。这是**高三物理·量子力学初步**的核心概念。

**2. 量子纠缠**
两个粒子可以处于一种关联态，测量其中一个立刻影响另一个的状态，无论距离多远。这种关联不能用经典的方式理解——它不传递信息，但确实存在。这是**高三·近代物理**中量子信息的核心资源。

**3. 贝尔不等式**
如果粒子属性预先确定（局域隐变量），关联测量结果必须满足某个数学约束；量子力学的预言违反这个约束。贝尔不等式的一个简单版本是：

\$\$|P(a, b) - P(a, c)| \\leq 1 + P(b, c)\$\$

其中 \$P(x, y)\$ 是沿方向 \$x\$ 测量粒子A和沿方向 \$y\$ 测量粒子B得到相同结果的概率。量子力学预言某些角度组合下这个不等式会被违反——实验证实了这一点。实验结果支持量子力学，排除了局域隐变量理论。`,
    thinking: `
**为什么重要？**
爱因斯坦-玻尔论战不只是两个人的争吵，它触及了物理学的哲学根基：物理理论到底在描述什么？是客观实在，还是我们对实在的认知？贝尔不等式和后续实验告诉我们，微观世界的"实在"比我们想象的更奇异——你不能同时拥有"局域性"（没有超光速影响）和"实在性"（属性预先确定），必须放弃至少一个。

**现代应用**
量子纠缠是量子通信和量子计算的核心资源。中国的"墨子号"卫星实现了千公里级的量子纠缠分发，量子密钥分发已经在金融和政务领域试点。2022年，阿斯佩、克劳泽和塞林格因贝尔不等式实验和量子信息科学获诺贝尔物理学奖——六十年前的哲学争论，已经变成了工程技术的基石。

**还有什么未解之谜？**
量子纠缠的非定域性到底意味着什么？"纠缠"是一种新的物理关联，还是我们描述方式的局限？多世界诠释认为不存在非定域问题——因为每次测量都分裂出了不同的宇宙。退相干理论认为与环境的相互作用让叠加态消失。但没有任何一种诠释被实验证实——也许，我们永远无法"看到"波函数坍缩的过程，也许量子力学的"底层真相"根本不是实验能触及的。`,
  },
  'think-003': {
    background: `
1971年10月，两位物理学家约瑟夫·哈菲尔和理查德·基廷做了一个大胆的实验：把四台铯原子钟分别放在民航客机上，让飞机绕地球飞一圈，回来和地面上的原子钟对比。

结果：飞行的钟确实比地面的钟走得慢——差别虽然只有几百纳秒，但完全符合相对论的预言。

这可能是人类历史上最反直觉的实验结果之一。你的第一反应大概是：钟坏了？不，钟没坏。时间本身变慢了。

相对论告诉你：**没有绝对时间**。你的时间取决于你的运动状态和所处的引力场。你飞得越快，你的时间越慢；你站得越高（引力场越弱），你的时间越快。这不是幻觉，不是比喻，不是近似——这是已经被无数实验验证的物理事实。

但对大多数人来说，这仍然像天方夜谭。时间不是均匀流逝的吗？过去、现在、未来，不是对所有人都一样的吗？让我们从最基本的地方开始。`,
    core: `
**光速不变——一切荒谬的起点**

相对论的出发点是一个看似简单的事实：**光速对所有观察者都是一样的**，不管你跑得有多快。

这完全违背直觉。如果你坐在一列以0.5c（光速的一半）行驶的火车上，向前射出一束光，按常理，地面上的人测到的光速应该是1.5c。但实验告诉你：不管你怎么量，光速永远是c。

如果光速不变，那时间和空间就必须"让步"。

**时间膨胀**

想象你在地面上，看一艘以速度 \$v\$ 飞过的飞船。飞船里有一个光钟——两面镜子上下放置，光子在之间来回反射，每次反弹就是"滴答"一声。

在你看来，飞船里的光子不是直上直下的——它跟着飞船一起走，画出了锯齿形的路径。锯齿路径比直上直下更长，但光速不变，所以光子走完一个来回需要更多时间。你的结论：**飞船上的钟比我手上的钟走得慢**。

数学表达：

\$\$\\Delta t' = \\frac{\\Delta t}{\\sqrt{1 - v^2/c^2}}\$\$

速度越快，分母越小，时间膨胀越明显。当 \$v = 0.99c\$ 时，飞船上的1秒对应地面的7秒。当 \$v\$ 无限接近 \$c\$，时间几乎停止。

**双生子佯谬**

这个效应引出了一个著名的悖论：假设有一对双胞胎，哥哥留在地球，弟弟乘坐飞船以0.9c的速度飞了5年后折返。回到地球时，哥哥老了10岁，弟弟只老了约4.4岁——弟弟比哥哥年轻了5.6岁。

等一下——运动是相对的。在弟弟看来，是地球在飞走再飞回来，应该是哥哥更年轻才对。这不是矛盾吗？

这就是"双生子佯谬"。解决的关键在于：弟弟经历了加速和减速（折返时），而哥哥没有。狭义相对论只适用于惯性系，弟弟在折返时离开了惯性系，所以两个参考系不对称。广义相对论更精确地描述了加速过程对时间的影响——结论一致：弟弟确实更年轻。

这不是思想实验——2010年，物理学家用精确的原子钟实际测量了高度差仅33厘米的两个位置的时间差异，结果与相对论预言完全吻合。你头上的时间比你脚下的时间走得快——虽然差别只有万亿分之几。

**引力时间膨胀**

广义相对论预言：引力越强，时间越慢。这就是为什么GPS卫星上的原子钟需要相对论修正——卫星在2万公里高空，引力比地面弱，钟每天快约45微秒（广义效应）；同时卫星在运动，钟每天慢约7微秒（狭义效应）。综合下来，卫星钟每天比地面快约38微秒。如果不修正，GPS定位每天累积约10公里误差——整个系统就废了。`,
    principle: `
**1. 狭义相对论的时间膨胀**
运动参考系中的时间流逝更慢，因子为 \$\\gamma = 1/\\sqrt{1-v^2/c^2}\$。这是**高三物理·近代物理**中相对论的核心预言，已被粒子寿命实验（高速运动的μ子寿命延长）和原子钟实验反复证实。

**2. 广义相对论的引力时间膨胀**
引力场越强，时间越慢。在地球表面和高度 \$h\$ 处的时间差约为：

\$\$\\frac{\\Delta t_h - \\Delta t_0}{\\Delta t_0} \\approx \\frac{gh}{c^2}\$\$

\$gh\$ 就是高度差对应的引力势差。这是**高三·相对论**的延伸概念，GPS卫星必须修正这个效应。

**3. 等效原理**
引力效应和加速效应在局部不可区分——这就是广义相对论的基石。一个在火箭中加速上升的人，和一个站在地球表面的人，感受到的"重力"完全相同。`,
    thinking: `
**为什么重要？**
相对论的时间观彻底推翻了牛顿的绝对时间。在牛顿的世界里，宇宙有一个大钟，到处走得一样快。爱因斯坦告诉我们：每个观察者有自己的时间，没有哪个时钟比别的更"正确"。这不只是物理发现，也是认识论的革命——我们对"同时性""过去""未来"的日常理解，在高速和强引力下不再成立。

**现代应用**
GPS是最直接的日常应用——每一次手机导航都在默默修正相对论效应。粒子加速器中，高速粒子的寿命延长（时间膨胀）是设计加速器时必须考虑的因素。卫星导航、深空通信、引力波探测，都离不开相对论的时间修正。2022年发射的中国空间站"梦天"实验舱上，也搭载了高精度原子钟用于验证相对论效应。

**还有什么未解之谜？**
时间是连续的还是离散的？普朗克时间（约 \$5.4 \\times 10^{-44}\$ 秒）可能是时间的最小单位——如果这是真的，时间就像电影帧一样是一帧一帧的，而不是连续流动的。时间有方向吗？物理定律几乎都是时间对称的（正放和倒放都成立），但我们的体验明显有"时间箭头"——过去和未来不同。这个矛盾至今没有令人满意的解释。`,
  },
  'think-004': {
    background: `
1935年，薛定谔提出那个著名的思想实验时，他不是想让你相信猫真的可以既死又活。

恰恰相反——他觉得这个结论荒唐透顶，所以故意把它推到极端，让所有人看到量子力学的诠释有多不靠谱。

事情的来龙去脉是这样的。那一年，爱因斯坦、波多尔斯基和罗森刚发表了EPR论文，质疑量子力学的完备性。薛定谔站在爱因斯坦一边——他虽然发明了量子力学的核心方程，但对哥本哈根诠释深感不满。

薛定谔的问题是：如果量子力学说一个原子可以同时处于"衰变"和"未衰变"的叠加态，那这种叠加态能延伸到多大？一个原子可以叠加——两个呢？一百个呢？一只猫呢？

他设计了一个场景，让一只猫的生死直接绑在一个量子事件上，然后问：如果量子力学的诠释是对的，猫是不是也处于"既死又活"的叠加态？如果荒唐，那说明诠释有问题；如果不荒唐，那你得给我一个合理的解释。

九十年过去了，没有人给出让所有人满意的解释。`,
    core: `
**原始思想实验**

薛定谔的设想是这样的：一个密封的钢箱，里面有一只猫、一个放射性原子、一个盖革计数器、一个继电器和一瓶氰化物。如果原子衰变，计数器触发继电器，打破毒药瓶，猫死；如果原子不衰变，猫活。

根据量子力学的哥本哈根诠释：在你打开箱子观察之前，原子处于"衰变"和"未衰变"的叠加态。既然猫的生死完全取决于原子状态，那猫也处于"死"和"活"的叠加态——既死又活，直到你打开箱子"看了一眼"，波函数坍缩，猫才"选择"了死或活。

薛定谔说：这显然是荒谬的。宏观的猫不可能处于叠加态。如果你坚持量子力学的诠释是正确的，那你就必须接受这个荒谬结论——这说明你的诠释有根本性缺陷。

**退相干：叠加态的"蒸发"**

1980年代，物理学家提出了退相干理论来回应这个问题。核心思想是：叠加态之所以在宏观世界看不到，是因为宏观物体无时无刻不在和环境发生相互作用——空气分子、热辐射、宇宙射线，甚至观察者的身体热量，都在不断"触碰"这个系统。

每一次相互作用，都是一次"信息泄漏"——叠加态的信息散布到环境中，系统自身失去了相干性，叠加态在极短时间内"蒸发"了。对一只猫来说，退相干时间大约只有 \$10^{-26}\$ 秒——你根本来不及看到"既死又活"的猫，它就已经坍缩了。

退相干解释了为什么宏观世界看不到叠加态，但它并没有回答薛定谔的核心问题：**波函数坍缩到底是不是一个真实的物理过程？** 退相干只是说叠加态很快消失，但没有说它是怎么"选择"一个结果的。

**多世界诠释：没有坍缩**

1957年，休·埃弗雷特提出了一个更激进的方案：波函数从来不坍缩。每次你"观察"一个叠加态，宇宙就分裂成多个分支——在一个分支里猫死了，在另一个分支里猫活着。你只看到其中一个分支，但另一个分支同样真实地存在着。

这个诠释的好处是数学上干净——不需要硬加"坍缩"这个补丁，薛定谔方程始终成立。但代价是：你需要接受存在无数个平行宇宙，每一个可能的测量结果都在某个宇宙中真实发生。这在形而上学上太重了——为了解释一只猫，你要创造无数个宇宙？

**客观坍缩理论：坍缩是物理过程**

还有一种方案：坍缩是真实的物理过程，不需要观察者。比如GRW理论（Ghirardi-Rimini-Weber）假设，每一个粒子都有极小的概率自发"定位"（坍缩到某个位置），单独粒子几乎不会自发定位，但当大量粒子纠缠在一起时，至少有一个粒子定位的概率大大增加——猫体内有 \$10^{26}\$ 个粒子，定位几乎是瞬间完成的。

这个理论修改了薛定谔方程，但预言的修改效应极其微弱，目前实验上无法检验。`,
    principle: `
**1. 量子叠加**
量子系统可以同时处于多个状态的叠加。在数学上，波函数 \$|\\psi\\rangle = \\alpha|0\\rangle + \\beta|1\\rangle\$，系数的模的平方 \$|\\alpha|^2\$ 和 \$|\\beta|^2\$ 分别代表测量得到0和1的概率。这是**高三物理·量子力学**的核心概念。

**2. 波函数坍缩与测量问题**
哥本哈根诠释认为测量导致波函数从叠加态"跳"到一个确定结果，但薛定谔方程本身不包含坍缩——它描述的是平滑、确定性的演化。这个理论上的不协调就是"测量问题"。这是量子力学**最深刻的哲学难题**。

**3. 退相干**
与环境相互作用导致叠加态的相位信息泄漏，叠加态在宏观尺度上极快消失。退相干时间与系统尺度和环境温度有关：

\$\$\\tau_d \\sim \\frac{\\hbar^2}{m k_B T (\\Delta x)^2}\$\$

系统越大（\$m\$ 越大）、温度越高（\$T\$ 越大），退相干越快。这是量子力学向经典物理过渡的关键机制。`,
    thinking: `
**为什么重要？**
薛定谔的猫暴露了量子力学最深层的矛盾：理论在计算上无比精确，在诠释上却模糊不清。"观察"到底是什么？需要意识参与吗？测量仪器算不算观察者？这些问题不只是哲学家的消遣——量子计算机的设计就依赖于叠加态的维持，退相干是最大的敌人。理解"猫为什么不能叠加"，就是理解"量子计算机为什么这么难造"。

**现代应用**
量子计算利用叠加态实现并行计算——一个量子比特可以同时是0和1，多个量子比特组合后计算空间指数增长。但退相干会破坏叠加态，所以量子计算机必须在极低温下运行，并使用量子纠错码对抗退相干。薛定谔的猫不只是思想实验，它是量子工程的头号难题。

**还有什么未解之谜？**
猫到底有没有"既死又活"的一瞬间？退相干理论说"有，但太短暂了"，多世界说"有，在另一个宇宙里"，客观坍缩说"没有，坍缩是真实的物理过程"。目前没有任何实验能区分这些诠释——也许永远不能。费曼的话仍然成立："没人理解量子力学。"但理解不了，不代表它不真实。量子力学是实验验证最精确的物理理论，只是我们还没搞懂它在说什么。`,
  },
  'think-005': {
    background: `
你有没有注意到一个奇怪的不对称？

物理定律几乎都是对称的——你可以让时间倒流，方程照样成立。台球碰撞的正放和倒放都符合牛顿定律，行星逆行也不违反任何规则。在微观层面，过去和未来没有区别。

但你的日常经验告诉你：过去和未来截然不同。打碎的杯子不会自动复原，泼出去的水不会自动回到盆里，你不会越活越年轻。时间似乎有一个箭头，只朝一个方向流动。

这个箭头从哪里来？1850年代，一个叫克劳修斯的德国物理学家找到了答案——**熵**。

他发现了一个量，它在一个孤立系统中永远只能增加，不能减少。这个量就叫熵。熵增的方向，就是时间流动的方向。宇宙从有序走向无序，从低熵走向高熵——这不是偶然，而是热力学第二定律的铁律。

这个定律如此根本，以至于爱因斯坦说："它是唯一一个永远不会被推翻的物理定律。"`,
    core: `
**什么是熵？**

熵是对"混乱程度"的量度。一个整齐的房间，熵低；一个凌乱的房间，熵高。一杯热咖啡放在桌上慢慢变凉，是熵增；你不能让凉咖啡自动变热，那是熵减——不会发生。

从微观角度看，熵实际上是在量度**微观状态数**。一个系统的微观状态数越多，它看起来就越"乱"，熵就越高。一滴墨水滴入清水，最终均匀扩散——因为"均匀分布"对应的微观状态数远远多于"墨水集中在一处"对应的微观状态数。系统自然地从概率低的状态走向概率高的状态，这就是熵增的统计本质。

数学表达：

\$\$S = k_B \\ln \\Omega\$\$

其中 \$S\$ 是熵，\$k_B\$ 是玻尔兹曼常数，\$\\Omega\$ 是微观状态数。熵就是对数意义上的"可能性多少"。

**热力学第二定律**

在一个孤立系统中，熵永远不会减少：

\$\$\\Delta S \\geq 0\$\$

这意味着：封闭系统自发地从有序走向无序，从低概率走向高概率。你可以局部地创造有序（比如把房间收拾干净），但代价是向环境排放更多的无序（你出汗、消耗能量、产生废热），总熵还是增加了。

**时间箭头**

为什么时间只朝一个方向流？因为熵增定义了时间的方向。如果你看到一段影片：碎杯子自动拼好——你立刻知道影片在倒放。你判断"倒放"的依据不是力学定律（力学定律不禁止），而是熵在减少——而熵不会减少。

物理学家认为，宇宙大爆炸时熵极低（高度有序），此后熵不断增加。热力学第二定律决定了时间的方向：从低熵的过去走向高熵的未来。

**麦克斯韦妖**

1867年，麦克斯韦提出了一个著名的"魔鬼"：假设有一个小妖精守在一个隔板的门旁边，它能看到分子飞来飞去，只让快的分子去一边、慢的分子去另一边——这样一边变热一边变冷，熵就减少了，第二定律就被违反了。

这个思想实验困扰了物理学家一个多世纪。最终的解答来自信息论：小妖要区分快慢分子，必须获取信息、存储信息、擦除信息——而擦除信息本身就会产生熵。兰道尔原理证明，擦除1比特信息至少产生 \$k_B \\ln 2\$ 的熵增。小妖省下的熵，还不够它操作时产生的——第二定律依然成立。`,
    principle: `
**1. 热力学第二定律**
孤立系统的熵永不减少，\$\\Delta S \\geq 0\$。这是**高二物理·热学**中热力学定律的核心，也是整个物理学中唯一有方向性的基本定律——它告诉你什么过程"自然发生"，什么过程"不会发生"。

**2. 玻尔兹曼熵公式**
\$S = k_B \\ln \\Omega\$——简单说就是：可能性越多，熵越高。这个公式刻在玻尔兹曼的墓碑上。它把宏观的热力学量和微观的状态数联系在一起，是统计力学的基础。

**3. 时间箭头**
熵增的方向就是时间流动的方向。这不是从其他物理定律推导出来的——力学定律本身是时间对称的。时间箭头是宏观统计效应，只对大量粒子的系统成立。`,
    thinking: `
**为什么重要？**
热力学第二定律是唯一一个给出"时间方向"的物理定律。它告诉你：宇宙有一个不可逆的趋势——从有序到无序，从低熵到高熵。这不是悲观，而是自然界最深刻的秩序。没有熵增，就没有热机、没有生命、没有记忆——所有这些都需要利用熵增来驱动有序过程。

**现代应用**
热机效率的上限由卡诺定理决定，而卡诺定理的根源就是第二定律——无论技术如何进步，热机效率永远不可能超过 \$(T_H - T_C)/T_H\$。冰箱、空调、内燃机、核电站，全部受此约束。信息论中，香农将熵的概念推广到信息领域——"信息熵"衡量信息的不确定性，是数据压缩和通信理论的基石。

**还有什么未解之谜？**
宇宙为什么从低熵状态开始？大爆炸时熵极低，这个"低"有多低？罗杰·彭罗斯估计，大爆炸的熵只有最大可能熵的 \$1/10^{10^{122}}\$——这个数字小到无法想象。为什么初始条件如此特殊？有人说是暴胀造成的，有人说暴胀本身就需要低熵初始条件——这陷入了循环论证。宇宙的"低熵起点"至今是最深的谜之一。`,
  },
  'think-006': {
    background: `
1961年，气象学家爱德华·洛伦兹在麻省理工的办公室里做天气预报的数值模拟。他用计算机求解一组大气对流的方程——简化过的，只有12个变量。

那天他运行了一次模拟，出去喝了杯咖啡，回来看结果。为了检查某个中间步骤，他决定重新运行——但为了省时间，他没有从头开始，而是从中间某个时刻的数据手动输入，让计算机接着算。

他输入的数字是0.506——计算机内部存储的完整值是0.506127。

差了0.000127——不到千分之一。按理说，这点误差应该可以忽略，结果应该几乎一样。

但洛伦兹看到的是：新的计算结果在最初几步和老结果几乎完全一致，但很快就分道扬镳——几天之后的天气完全不同，根本认不出来是同一组初始数据。

他以为计算机坏了。检查了几遍，没坏。他又试了一次，结果一样。

洛伦兹意识到，他发现了一个被所有人忽略的事实：**即使系统的运动规律是完全确定的（方程没有随机项），初始条件的微小差异也会被指数级放大，最终导致完全不同的结果。**

这就是混沌。`,
    core: `
**对初始条件的敏感依赖**

混沌最本质的特征就是：初始条件的极小差异，会导致结果的巨大分歧。洛伦兹后来用一个生动的比喻来描述这个现象：一只蝴蝶在巴西扇动翅膀，可能在德克萨斯引发一场龙卷风——这就是"蝴蝶效应"。

这并不意味着蝴蝶真的能制造龙卷风。它的意思是：大气是一个混沌系统，初始条件中的任何微小不确定——无论是蝴蝶翅膀的气流，还是你测量温度时0.01度的误差——都会在足够长的时间后被放大到让预测失效。

数学上，这种敏感依赖用**李雅普诺夫指数**来量度。如果李雅普诺夫指数 \$\\lambda > 0\$，两个初始轨迹之间的距离随时间按 \$e^{\\lambda t}\$ 增长——指数增长意味着误差翻倍的时间是固定的，不管误差多小。

**洛伦兹吸引子**

洛伦兹从他的气象方程中提炼出了一个更简单的三方程模型：

\$\$\\frac{dx}{dt} = \\sigma(y - x)\$\$

\$\$\\frac{dy}{dt} = x(\\rho - z) - y\$\$

\$\$\\frac{dz}{dt} = xy - \\beta z\$\$

其中 \$\\sigma\$、\$\\rho\$、\$\\beta\$ 是参数。这三个方程看起来简单，但它们产生的轨迹异常复杂——在三维空间中画出一条永不重复、永不自交的曲线，始终被吸引到一个蝴蝶形状的区域内，但在区域内随机跳荡。这就是**洛伦兹吸引子**——混沌理论最著名的图标。

"吸引子"的意思是：不管你从哪个初始条件出发，轨迹最终都会被"吸"进这个蝴蝶形状里。但进去之后怎么跳，完全不可预测。

**混沌不是随机**

一个关键区分：混沌≠随机。随机是"没有规律"，混沌是"有规律，但不可预测"。洛伦兹方程是100%确定的——没有随机项，没有概率——但你仍然无法长期预测，因为你永远不可能精确到无限位地知道初始条件。

这打破了自牛顿以来的一套信仰：拉普拉斯曾经宣称，如果能知道宇宙中每个粒子的位置和速度，就能预言未来的一切。混沌告诉我们：就算你知道了，精度不够也没用——而无限精度在物理上是不可能的。

**三体问题**

混沌的另一个经典例子是三体问题。两个天体的运动有精确解（开普勒轨道），但加上第三个天体，运动方程就没有一般解析解。19世纪末，庞加莱就证明了三体问题的解对初始条件极度敏感——这是混沌的最早数学证明。

2018年，中国科幻作家刘慈欣的《三体》让这个概念出圈了——小说中三颗恒星的无规则运动，正是混沌的真实写照。`,
    principle: `
**1. 非线性系统与混沌**
当系统的运动方程包含非线性项（如 \$xy\$ 或 \$x^2\$），微扰会被放大而非衰减，系统可能表现出混沌行为。这是**高中物理·力学**中运动方程概念的深层延伸——线性系统可叠加、可预测，非线性系统则可能不可预测。

**2. 李雅普诺夫指数**
量度初始误差的指数增长率，\$\\lambda > 0\$ 意味着系统是混沌的。一个简单的类比：如果 \$\\lambda = 1\$（单位：1/秒），则1秒后误差翻倍，10秒后误差放大1024倍。误差增长的时间尺度 \$1/\\lambda\$ 就是"可预测时限"。

**3. 吸引子**
混沌系统的轨迹虽然不可预测，但会被限制在相空间的特定区域内——吸引子。洛伦兹吸引子是最著名的例子，它说明混沌不等于"什么都有可能"，而是"在有限范围内无法预测"。`,
    thinking: `
**为什么重要？**
蝴蝶效应打破了决定论的最后堡垒。即使自然界遵循完全确定的规律，长期预测仍然可能是不可能的——不是因为我们不够聪明，而是因为自然界本身就不允许。这个认识深刻影响了气象学、经济学、生态学、神经科学……几乎所有涉及复杂系统的领域。

**现代应用**
天气预报的"有效预报期限"约7~10天，这不是技术不行，而是大气混沌的本质决定的——再好的超级计算机也推不翻蝴蝶效应。混沌控制在工程中也有应用：心律失常的混沌控制、化学反应的周期扰动、甚至航天器利用混沌轨道节省燃料——利用"敏感依赖"这个看似缺点的特性，反而可以实现精确操控。

**还有什么未解之谜？**
混沌和量子不确定性是什么关系？经典混沌在量子力学中还存在吗？量子力学的线性结构似乎不允许经典意义的混沌——但量子系统的半经典极限确实表现出类似混沌的行为。量子混沌（或"量子混沌的缺失"）是理论物理的活跃研究领域。更深层的问题是：意识的不可预测性，是混沌还是量子？也许都是，也许都不是。`,
  },
}

// ==================== 物理视界首页 ====================
export function VisionListPage() {
  const [search, setSearch] = useState('')
  const [activeCategory, setActiveCategory] = useState('all')
  const [activeDiff, setActiveDiff] = useState<string | null>(null)

  const filtered = physicsVisionStories.filter((s) => {
    const matchSearch = !search || s.title.includes(search) || s.category.includes(search)
    const matchCat = activeCategory === 'all' || s.category === activeCategory
    const matchDiff = !activeDiff || s.difficulty === activeDiff
    return matchSearch && matchCat && matchDiff
  })

  return (
    <AppLayout showSubjectNav>
      <div className="max-w-4xl mx-auto px-4 py-8 space-y-6">
        {/* 头部 */}
        <div>
          <div className="flex items-center gap-2 mb-1">
            <Eye className="w-6 h-6 text-cyan-500" />
            <h1 className="text-2xl font-bold">物理视界</h1>
          </div>
          <p className="text-muted-foreground text-sm">
            用故事的方式，看见物理学的广度与深度
          </p>
        </div>

        {/* 十大分类 */}
        <div>
          <p className="text-xs font-medium text-muted-foreground mb-2">十大分类</p>
          <div className="grid grid-cols-2 sm:grid-cols-5 gap-2">
            {categories.filter((c) => c.id !== 'all').map((cat) => {
              const CatIcon = cat.icon
              return (
                <button
                  key={cat.id}
                  onClick={() => setActiveCategory(activeCategory === cat.id ? 'all' : cat.id)}
                  className={`flex flex-col items-center gap-1 p-3 rounded-xl border text-center transition-all text-xs ${
                    activeCategory === cat.id
                      ? 'border-primary bg-primary/5 shadow-sm'
                      : 'hover:border-primary/30 hover:bg-muted/50'
                  }`}
                >
                  <CatIcon className="w-5 h-5" style={{ color: cat.color }} />
                  <span className="font-medium">{cat.label}</span>
                </button>
              )
            })}
          </div>
        </div>

        {/* 搜索 */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="搜索故事标题..."
            className="pl-9"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        {/* 难度筛选 */}
        <div className="flex gap-2">
          {[['🟢', '简单'], ['🟡', '中等'], ['🔴', '困难']].map(([d, label]) => (
            <Button
              key={d}
              variant={activeDiff === d ? 'default' : 'outline'}
              size="sm"
              className="text-xs h-8"
              onClick={() => setActiveDiff(activeDiff === d ? null : d)}
            >
              {d} {label}
            </Button>
          ))}
          {(activeDiff || activeCategory !== 'all') && (
            <Button variant="ghost" size="sm" className="text-xs h-8"
              onClick={() => { setActiveDiff(null); setActiveCategory('all'); }}>
              清除筛选
            </Button>
          )}
        </div>

        {/* 故事列表 */}
        <div className="space-y-3">
          {filtered.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground">
              <Eye className="w-8 h-8 mx-auto mb-2 opacity-30" />
              <p>没有找到匹配的物理视界故事</p>
            </div>
          ) : (
            filtered.map((story) => {
              const diffCfg = DIFFICULTY_CONFIG[story.difficulty]
              const cat = categories.find((c) => c.id === story.category)
              return (
                <Link key={story.id} to={`/physics/vision/${story.id}`}>
                  <Card className="hover:shadow-md hover:border-primary/30 transition-all group cursor-pointer">
                    <CardContent className="p-5">
                      <div className="flex gap-4">
                        <div className="w-1 rounded-full flex-shrink-0" style={{ backgroundColor: cat?.color }} />
                        <div className="flex-1 min-w-0">
                          <div className="flex items-start justify-between gap-2 mb-1">
                            <div className="flex items-center gap-2 flex-wrap">
                              <Badge className={`${diffCfg.bg} text-xs`}>{diffCfg.label}</Badge>
                              <Badge variant="outline" className="text-xs" style={{ borderColor: cat?.color, color: cat?.color }}>
                                {cat?.label}
                              </Badge>
                            </div>
                            <div className="flex items-center gap-1 text-xs text-muted-foreground flex-shrink-0">
                              <Clock className="w-3 h-3" />
                              {story.readTime}分钟
                            </div>
                          </div>
                          <h3 className="font-semibold text-base mb-1 group-hover:text-primary transition-colors">
                            {story.title}
                          </h3>
                          <p className="text-xs text-muted-foreground line-clamp-2">
                            点击阅读全文，了解故事背后的物理原理和思维方式
                          </p>
                        </div>
                        <ChevronRight className="w-5 h-5 text-muted-foreground group-hover:text-primary transition-colors flex-shrink-0 mt-1" />
                      </div>
                    </CardContent>
                  </Card>
                </Link>
              )
            })
          )}
        </div>
      </div>
    </AppLayout>
  )
}

// ==================== 故事详情页 ====================
export function VisionDetailPage() {
  const { storyId } = useParams<{ storyId: string }>()
  const story = physicsVisionStories.find((s) => s.id === storyId)
  const cat = categories.find((c) => c.id === story?.category)
  const CatIcon = cat?.icon || Eye
  const diffCfg = story ? DIFFICULTY_CONFIG[story.difficulty] : DIFFICULTY_CONFIG['🟢']
  const detail = story ? storyDetails[story.id] : null

  if (!story) {
    return (
      <AppLayout showSubjectNav>
        <div className="max-w-3xl mx-auto px-4 py-16 text-center">
          <Eye className="w-12 h-12 mx-auto mb-4 text-muted-foreground opacity-30" />
          <h2 className="text-xl font-bold mb-2">故事不存在</h2>
          <p className="text-muted-foreground mb-4">未找到对应的物理视界故事</p>
          <Link to="/physics/vision">
            <Button variant="outline">返回物理视界</Button>
          </Link>
        </div>
      </AppLayout>
    )
  }

  return (
    <AppLayout showSubjectNav>
      <div className="max-w-3xl mx-auto px-4 py-8 space-y-8">
        {/* 返回 */}
        <div>
          <Link to="/physics/vision">
            <Button variant="ghost" size="sm" className="gap-1">← 返回物理视界</Button>
          </Link>
        </div>

        {/* 故事头部 */}
        <div className="space-y-4">
          <div className="flex items-center gap-2 flex-wrap">
            <Badge className={`${diffCfg.bg} text-xs`}>{diffCfg.label}</Badge>
            <Badge variant="outline" style={{ borderColor: cat?.color, color: cat?.color }}>
              <CatIcon className="w-3 h-3 mr-1" />{cat?.label}
            </Badge>
            <span className="flex items-center gap-1 text-xs text-muted-foreground">
              <Clock className="w-3 h-3" />约 {story.readTime} 分钟阅读
            </span>
          </div>
          <h1 className="text-3xl font-bold leading-tight">{story.title}</h1>
        </div>

        {/* 故事正文 */}
        {detail ? (
          <div className="space-y-8">
            {/* 故事背景 */}
            <section>
              <div className="flex items-center gap-2 mb-3">
                <div className="w-6 h-6 rounded-full flex items-center justify-center" style={{ backgroundColor: `${cat?.color}22` }}>
                  <Globe className="w-4 h-4" style={{ color: cat?.color }} />
                </div>
                <h2 className="font-bold text-base">故事背景</h2>
              </div>
              <Card>
                <CardContent className="p-5 text-base leading-relaxed">
                  <MarkdownRenderer content={detail.background} />
                </CardContent>
              </Card>
            </section>

            {/* 核心内容 */}
            <section>
              <div className="flex items-center gap-2 mb-3">
                <div className="w-6 h-6 rounded-full bg-primary/10 flex items-center justify-center">
                  <Atom className="w-4 h-4 text-primary" />
                </div>
                <h2 className="font-bold text-base">核心内容</h2>
              </div>
              <Card className="bg-blue-50/50 border-blue-100">
                <CardContent className="p-5 text-base leading-relaxed">
                  <MarkdownRenderer content={detail.core} />
                </CardContent>
              </Card>
            </section>

            {/* 物理原理 */}
            <section>
              <div className="flex items-center gap-2 mb-3">
                <div className="w-6 h-6 rounded-full bg-yellow-100 flex items-center justify-center">
                  <Zap className="w-4 h-4 text-yellow-600" />
                </div>
                <h2 className="font-bold text-base">物理原理</h2>
              </div>
              <Card className="bg-yellow-50/50 border-yellow-100">
                <CardContent className="p-5 text-base leading-relaxed">
                  <MarkdownRenderer content={detail.principle} />
                </CardContent>
              </Card>
            </section>

            {/* 思考延伸 */}
            <section>
              <div className="flex items-center gap-2 mb-3">
                <div className="w-6 h-6 rounded-full bg-purple-100 flex items-center justify-center">
                  <Sparkles className="w-4 h-4 text-purple-600" />
                </div>
                <h2 className="font-bold text-base">思考延伸</h2>
              </div>
              <Card className="bg-purple-50/50 border-purple-100">
                <CardContent className="p-5 text-base leading-relaxed">
                  <MarkdownRenderer content={detail.thinking} />
                </CardContent>
              </Card>
            </section>
          </div>
        ) : (
          <Card className="bg-muted/30 border-dashed">
            <CardContent className="p-8 text-center text-muted-foreground">
              <Eye className="w-8 h-8 mx-auto mb-2 opacity-30" />
              <p className="text-sm">该故事详细内容正在编写中</p>
            </CardContent>
          </Card>
        )}

        {/* 相关推荐 */}
        <div>
          <h3 className="font-bold text-base mb-3">相关故事</h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {physicsVisionStories
              .filter((s) => s.id !== storyId && s.category === story.category)
              .slice(0, 2)
              .map((s) => {
                const sdiff = DIFFICULTY_CONFIG[s.difficulty]
                return (
                  <Link key={s.id} to={`/physics/vision/${s.id}`}>
                    <Card className="hover:shadow-sm hover:border-primary/30 transition-all cursor-pointer">
                      <CardContent className="p-4">
                        <div className="flex items-start gap-2">
                          <Badge className={`${sdiff.bg} text-xs flex-shrink-0`}>{sdiff.label}</Badge>
                          <div className="min-w-0">
                            <p className="text-sm font-medium line-clamp-2">{s.title}</p>
                            <p className="text-xs text-muted-foreground mt-0.5">{s.readTime} 分钟</p>
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  </Link>
                )
              })}
            {physicsVisionStories.filter((s) => s.id !== storyId && s.category === story.category).length === 0 && (
              <Link to="/physics/vision">
                <Button variant="outline" className="w-full gap-2">
                  查看更多物理视界 <ArrowRight className="w-4 h-4" />
                </Button>
              </Link>
            )}
          </div>
        </div>
      </div>
    </AppLayout>
  )
}
